        It 'counts Protected Users as delegation protection only at domain functional level 2012 R2 or later (finding 14)' {
            $alice = New-C10Record -Name 'adm.alice' -Sid "$($script:C10RootSid)-1101" -Uac 512
            $mk = { param($Enforced) [pscustomobject]@{ Known = $true; Dns = @{ ($alice.Dn.ToLowerInvariant()) = $true }; Why = ''; DelegationEnforced = $Enforced; ModeText = 'the domain functional level is Windows2012Domain, below Windows Server 2012 R2' } }
            $pop = [pscustomobject]@{ Records = @($alice, $script:C10RootAdmin); Complete = $true; Gaps = @() }
            (Get-AdfaPrivDelegableVerdict -Domain 'contoso.com' -Population $pop -ProtectedUsers (& $mk $true) -Config $script:Pc).Status | Should -Be 'Pass'
            $below = Get-AdfaPrivDelegableVerdict -Domain 'contoso.com' -Population $pop -ProtectedUsers (& $mk $false) -Config $script:Pc
            $below.Status | Should -Be 'Warning'
            $below.Principals | Should -Be 'adm.alice'
            $below.Detail | Should -Match 'below Windows Server 2012 R2'
            $unknown = Get-AdfaPrivDelegableVerdict -Domain 'contoso.com' -Population $pop -ProtectedUsers (& $mk $null) -Config $script:Pc
            $unknown.Status | Should -Be 'Not Assessed'
            $unknown.Unresolved | Should -Match 'Windows Server 2012 R2'
            # The level is read from Get-ADDomain's DomainMode, per domain.
            $cases = @(@{ Mode = 'Windows2012Domain'; Expect = $false }, @{ Mode = 'Windows2012R2Domain'; Expect = $true }, @{ Mode = 'Windows2025Domain'; Expect = $true }, @{ Mode = 'UnknownDomain'; Expect = $null }, @{ Mode = ''; Expect = $null })
            # Declared population: five DomainMode answers.
            $cases.Count | Should -Be 5
            foreach ($case in $cases) {
                $set = Get-AdfaPrivProtectedSet -State (New-C10PureState -Mode $case.Mode) -Domain 'contoso.com' -Config $script:Pc
                if ($null -eq $case.Expect) { $set.ProtectedUsers.DelegationEnforced | Should -BeNullOrEmpty -Because $case.Mode }
                else { $set.ProtectedUsers.DelegationEnforced | Should -Be $case.Expect -Because $case.Mode }
            }
            # Through the seams: contoso.com at 2012 makes its Protected Users member adm.alice delegable.
            $script:C10DomainMode = @{ 'contoso.com' = 'Windows2012Domain' }
            $rows = Get-C10AllRows -State (Get-C10State)
            (Get-C10Row $rows 'Privileged accounts delegable: contoso.com')[0].Principals | Should -Be 'adm.alice; adm.bob'
            (Get-C10Row $rows 'Privileged accounts delegable: north.contoso.com')[0].Status | Should -Be 'Pass'
        }
        It 'marks a member list of exactly 5000 values, the second range-retrieval limit, as possibly truncated (finding 16)' {
            $ctx = New-AdfaPrivContext -DomainMap @{} -Config $script:Pc -Offline
            $members = @(1..5000 | ForEach-Object { "CN=u$_,DC=contoso,DC=com" })
            $rec = New-C10Record -Name 'u' -Sid "$($script:C10RootSid)-3000"
            foreach ($m in $members) { $ctx['Objects'][$m.ToLowerInvariant()] = [pscustomobject]@{ Ok = $true; Class = 'Read'; Error = ''; ErrorType = ''; Record = $rec } }
            $big = New-C10Record -Name 'Big' -Kind 'Group' -Sid 'S-1-5-32-544' -Dn 'CN=Big,DC=contoso,DC=com' -Uac $null -Members $members
            $c = Resolve-AdfaPrivGroupClosure -Group $big -Context $ctx -Config $script:Pc
            $c.Complete | Should -BeFalse
            $c.Unresolved[0].Reason | Should -Match 'exactly 5000 values'
        }
        It 'counts a Kerberoastable account whose Enabled state was not returned, never dropping it (finding 18)' {
            $roast = [pscustomobject]@{ RoastOk = $true; RoastClass = 'Read'; RoastError = ''; RoastErrorType = ''; Roast = @([pscustomobject]@{ Name = 'svc.sql'; Enabled = $null })
                AsRepOk = $true; AsRepClass = 'Read'; AsRepError = ''; AsRepErrorType = ''; AsRep = @() }
            $r = @(Get-AdfaKerberosRoastVerdict -Domain 'contoso.com' -Roast $roast -Config $script:Pc)[0]
            $r.Status | Should -Be 'Warning'
            $r.Count | Should -Be '1'
            $r.Principals | Should -Be 'svc.sql'
        }
    }

    Context 'Config override' {
        It 'accepts a valid override and rewrites the provenance for the keys it supplied only' {
            $o = '{ "Privileged": { "OrphanStatus": "Fail", "NameListCap": 3, "MaxExpandedObjects": 100, "EnterpriseAdminsExemptRootAdministrator": true } }' | ConvertFrom-Json
            $r = Resolve-AdfaConfigOverride -Override $o -BaseConfig $script:Config -Sections $script:ConfigOverrideSections -OverrideSource 'C:\cfg\priv.json'
            $m = $r['Privileged']
            [string]$m['OrphanStatus'] | Should -Be 'Fail'
            [int]$m['NameListCap'] | Should -Be 3
            [int]$m['MaxExpandedObjects'] | Should -Be 100
            [bool]$m['EnterpriseAdminsExemptRootAdministrator'] | Should -BeTrue
            [string]$m['SchemaAdminsStatus'] | Should -Be 'Warning'
            [string]$m['ThresholdSource'] | Should -Match 'C:\\cfg\\priv\.json'
            [string]$m['ThresholdSource'] | Should -Match 'OrphanStatus'
            [string]$m['ThresholdSource'] | Should -Not -Match 'for .*SchemaAdminsStatus'
            # The built-in table still says what it said.
            [string]$script:Pc['OrphanStatus'] | Should -Be 'Warning'
            (@($script:Pc['Groups'])).Count | Should -Be 17
        }
        It 'refuses <Name>' -TestCases @(
            @{ Name = 'an array'; Json = '[ { "OrphanStatus": "Fail" } ]'; Pattern = 'single object' }
            @{ Name = 'an empty object'; Json = '{ }'; Pattern = 'empty object' }
            @{ Name = 'an unknown key'; Json = '{ "Groups": [] }'; Pattern = 'unknown key' }
            @{ Name = 'a null'; Json = '{ "RbcdStatus": null }'; Pattern = 'null' }
            @{ Name = 'a Pass grade'; Json = '{ "SchemaAdminsStatus": "Pass" }'; Pattern = 'Warning or Fail' }
            @{ Name = 'an Info grade'; Json = '{ "UnconstrainedStatus": "Info" }'; Pattern = 'Warning or Fail' }
            @{ Name = 'a quoted boolean'; Json = '{ "EnterpriseAdminsExemptRootAdministrator": "true" }'; Pattern = 'JSON true or false' }
            @{ Name = 'a quoted number'; Json = '{ "NameListCap": "5" }'; Pattern = 'JSON number' }
            @{ Name = 'a fraction'; Json = '{ "NameListCap": 2.5 }'; Pattern = 'whole number from 0 to 1000' }
            @{ Name = 'a cap above the range'; Json = '{ "NameListCap": 1001 }'; Pattern = 'whole number from 0 to 1000' }
            @{ Name = 'a read cap of zero'; Json = '{ "MaxExpandedObjects": 0 }'; Pattern = 'whole number from 1 to 100000' }
            @{ Name = 'a bit value'; Json = '{ "Uac": { "NotDelegated": 0 } }'; Pattern = 'unknown key' }
        ) {
            param($Name, $Json, $Pattern)
            # ConvertFrom-Json unrolls a top-level array on PowerShell 7, so the array is built directly.
            if ($Name -eq 'an array') { $value = @([pscustomobject]@{ OrphanStatus = 'Fail' }) }
            else { $value = $Json | ConvertFrom-Json }
            { Merge-AdfaPrivilegedConfig -BaseConfig $script:Pc -Override $value -OverrideSource 'C:\cfg\bad.json' } | Should -Throw -ExpectedMessage ("*{0}*" -f $Pattern)
        }
        It 'accepts the boundaries of each range' {
            (Merge-AdfaPrivilegedConfig -BaseConfig $script:Pc -Override ('{ "NameListCap": 0 }' | ConvertFrom-Json))['NameListCap'] | Should -Be 0
            (Merge-AdfaPrivilegedConfig -BaseConfig $script:Pc -Override ('{ "NameListCap": 1000 }' | ConvertFrom-Json))['NameListCap'] | Should -Be 1000
            (Merge-AdfaPrivilegedConfig -BaseConfig $script:Pc -Override ('{ "MaxExpandedObjects": 1 }' | ConvertFrom-Json))['MaxExpandedObjects'] | Should -Be 1
            (Merge-AdfaPrivilegedConfig -BaseConfig $script:Pc -Override ('{ "MaxExpandedObjects": 100000 }' | ConvertFrom-Json))['MaxExpandedObjects'] | Should -Be 100000
        }
    }

    Context 'Recommendations' {
        It 'places its entries before every unscoped entry, anchored on its Item prefixes, with a catch-all per section' {
            $map = @($script:RecommendationMap)
            $mine = @(for ($i = 0; $i -lt $map.Count; $i++) { if ($map[$i].ContainsKey('Section') -and [string]$map[$i].Section -match '^\(\?i\)\^(privileged accounts|privileged hygiene|kerberos exposure)$') { $i } })
            # Declared population: 2 + catch-all, 3 + catch-all, 3 + catch-all.
            $mine.Count | Should -Be 11
            $firstUnscoped = @(for ($i = 0; $i -lt $map.Count; $i++) { if (-not $map[$i].ContainsKey('Section')) { $i } })[0]
            foreach ($i in $mine) { $i | Should -BeLessThan $firstUnscoped }
            foreach ($i in $mine) { [string]$map[$i].Match | Should -Match '^\(\?i\)\^(Privileged Accounts|Privileged Hygiene|Kerberos Exposure) :: ' }
            @($mine | Where-Object { [string]$map[$_].Text -eq '' }).Count | Should -Be 3
        }
        It 'answers each graded family with its own advice, whatever its Detail says' {
            $cases = @(
                @{ Section = 'Privileged Accounts'; Item = 'Schema Admins members: contoso.com'; Expect = 'temporarily and occasionally' }
                @{ Section = 'Privileged Accounts'; Item = 'Enterprise Admins members: contoso.com'; Expect = 'day-to-day' }
                @{ Section = 'Privileged Hygiene'; Item = 'adminCount orphans: contoso.com'; Expect = 're-enable permission inheritance' }
                @{ Section = 'Privileged Hygiene'; Item = 'Privileged accounts with SPN: contoso.com'; Expect = 'Remove the service principal names' }
                @{ Section = 'Privileged Hygiene'; Item = 'Privileged accounts delegable: contoso.com'; Expect = 'Account is sensitive and cannot be delegated' }
                @{ Section = 'Kerberos Exposure'; Item = 'Unconstrained delegation: contoso.com'; Expect = 'impersonate a client' }
                @{ Section = 'Kerberos Exposure'; Item = 'Protocol transition delegation: contoso.com'; Expect = 'strictly controlled' }
                @{ Section = 'Kerberos Exposure'; Item = 'Resource-based delegation: contoso.com'; Expect = 'PrincipalsAllowedToDelegateToAccount' }
            )
            # Declared population: the eight graded families.
            $cases.Count | Should -Be 8
            foreach ($c in $cases) {
                $rec = Get-AdfaRecommendation -Section $c.Section -Item $c.Item -Detail $script:C10Hostile
                $rec | Should -Match ([regex]::Escape($c.Expect)) -Because $c.Item
                $rec | Should -Not -Match 'repadmin|wbadmin|New-KrbtgtKeys|dfsrmig|ENROLLEE_SUPPLIES_SUBJECT|replace with resource-based' -Because $c.Item
            }
            foreach ($item in @('Privileged group: Backup Operators: contoso.com', 'Privileged group population: contoso.com', 'Protected Users members: contoso.com', 'Constrained delegation: contoso.com')) {
                $section = 'Privileged Accounts'
                if ($item -match '^Protected Users') { $section = 'Privileged Hygiene' }
                if ($item -match '^Constrained') { $section = 'Kerberos Exposure' }
                Get-AdfaRecommendation -Section $section -Item $item -Detail $script:C10Hostile | Should -Be '' -Because $item
            }
        }
        It 'still sends the Kerberoast and AS-REP rows to the advice they had' {
            (Get-AdfaRecommendation -Section 'Kerberos Exposure' -Item 'Kerberoastable user accounts (SPN set)' -Detail '1 enabled user account(s) with a service principal name visible to this account; names are in the Principals column.') | Should -Match 'Group Managed Service Accounts'
            (Get-AdfaRecommendation -Section 'Kerberos Exposure' -Item 'AS-REP roastable accounts (no pre-auth)' -Detail '1 enabled account(s) that do not require Kerberos pre-authentication visible to this account; names are in the Principals column.') | Should -Match 'pre-authentication'
        }
        It 'attaches advice to Warning rows only, chosen without the NotRun note, and none to a row that measured nothing' {
            $rows = Get-C10AllRows -State (Get-C10State)
            $findings = @($rows | ForEach-Object {
                    $section = @{ Privileged = 'Privileged Accounts'; PrivHygiene = 'Privileged Hygiene'; Kerberos = 'Kerberos Exposure' }[$_.Area]
                    ConvertTo-AdfaConsolidatedFinding -Section $section -Row $_ -StatusColumn 'Status' })
            $findings.Count | Should -Be $rows.Count
            @($findings | Where-Object { $_.Status -match '^(Pass|Info|Not Assessed)$' -and $_.Recommendation }).Count | Should -Be 0
            @($findings | Where-Object { $_.Status -eq 'Warning' -and -not $_.Recommendation }).Count | Should -Be 0
            @($findings | Where-Object { $_.Status -eq 'Warning' }).Count | Should -BeGreaterThan 5   # non-vacuity
            $orphan = @($findings | Where-Object { $_.Item -eq 'adminCount orphans: contoso.com' })[0]
            $orphan.Detail | Should -Match 'formerly protected'
        }
    }
}

Describe 'dcdiag per DC, per partition and per scope: the grid, Topology, CheckSDRefDom, CrossRefValidation, Intersite (C11)' {
    # PORT-PLAN C11. The dcdiag command reference (read 2026-11-16) prints per-DC results under
    # "Testing server: <site>\<DC>", partition results under "Running partition tests on : <NC>" and
    # enterprise results under "Running enterprise tests on : <forest>", and wraps a verdict line so
    # that the test name can fall on the next line. Each verdict is attributed to the block it is in:
    # a partition or enterprise result never becomes a DC's failure, and a DC's own result is graded
    # for that DC only.
    BeforeAll {
        $script:C11Url = 'https://learn.microsoft.com/windows-server/administration/windows-commands/dcdiag'
        # The 28 tests in Learn's "DCDiag known tests" table (read 2026-11-16).
        $script:C11LearnTests = @('Advertising', 'CheckSDRefDom', 'CheckSecurityError', 'Connectivity', 'CrossRefValidation', 'CutoffServers',
            'DcPromo', 'DFSREvent', 'DNS', 'FrsEvent', 'Intersite', 'KccEvent', 'KnowsOfRoleHolders', 'MachineAccount', 'NCSecDesc', 'NetLogons',
            'ObjectsReplicated', 'OutboundSecureChannels', 'RegisterInDNS', 'Replications', 'RidManager', 'Services', 'SysVolCheck', 'SystemLog',
            'Topology', 'VerifyEnterpriseReferences', 'VerifyReferences', 'VerifyReplicas')
        $script:C11PerDc = @('Connectivity', 'Replications', 'Advertising', 'Services', 'Netlogons', 'SysVolCheck', 'DFSREvent', 'FrsEvent',
            'KccEvent', 'RidManager', 'KnowsOfRoleHolders', 'MachineAccount', 'ObjectsReplicated', 'NCSecDesc', 'VerifyReferences',
            'VerifyReplicas', 'FsmoCheck', 'CheckSecurityError', 'VerifyEnterpriseReferences', 'SystemLog', 'DNS')
        $script:C11Partitions = @('ForestDnsZones', 'DomainDnsZones', 'Schema', 'Configuration', 'contoso')
        $script:C11Dc1 = 'dc1.contoso.com'
        $script:C11Dc2 = 'dc2.contoso.com'
        $script:C11Dc3 = 'dc3.north.contoso.com'
        $script:C11Ro = 'rodc4.north.contoso.com'
        $script:C11Cfg = $script:Config.DcDiag

        function New-C11Target { param([string]$HostName, [string]$Scope, [string]$Site = 'HQ', [AllowNull()]$IsReadOnly = $false)
            [pscustomobject]@{ HostName = $HostName; Scope = $Scope; Site = $Site; IsReadOnly = $IsReadOnly; Name = ($HostName.Split('.')[0].ToUpperInvariant()) } }
        function Get-C11Short { param([string]$HostName) $HostName.Split('.')[0].ToUpperInvariant() }
        # The shape the dcdiag command reference prints: a banner, the initial Connectivity block for
        # the server, then the test's own block. -Wrap splits the verdict as Learn's sample does.
        function New-C11DcOutput {
            param([string]$Dc, [string]$Test, [string]$Verdict = 'passed', [string[]]$Lines = @(), [string]$ConnVerdict = 'passed', [switch]$Wrap, [string]$Subject = '')
            if ($Subject -eq '') { $Subject = $Dc }
            if ($Test -eq 'Connectivity') { $ConnVerdict = $Verdict }
            $b = New-Object System.Collections.Generic.List[string]
            foreach ($l in @('Directory Server Diagnosis', '', 'Performing initial setup:', ("   Home Server = {0}" -f $Dc), '   * Identified AD Forest.', '   Done gathering initial info.', '', 'Doing initial required tests', '',
                    ("   Testing server: Default-First-Site-Name\{0}" -f $Dc), '      Starting test: Connectivity')) { $b.Add($l) }
            if ($Test -eq 'Connectivity') { foreach ($l in $Lines) { $b.Add(("         {0}" -f $l)) } }
            $b.Add(("         ......................... {0} {1} test Connectivity" -f $Dc, $ConnVerdict))
            if ($Test -ne 'Connectivity') {
                foreach ($l in @('', 'Doing primary tests', '', ("   Testing server: Default-First-Site-Name\{0}" -f $Dc), ("      Starting test: {0}" -f $Test))) { $b.Add($l) }
                foreach ($l in $Lines) { $b.Add(("         {0}" -f $l)) }
                if ($Wrap) { $b.Add(("         ......................... {0} {1} test " -f $Subject, $Verdict)); $b.Add(("         {0}" -f $Test)) }
                else { $b.Add(("         ......................... {0} {1} test {2}" -f $Subject, $Verdict, $Test)) }
            }
            return ($b -join "`r`n")
        }
        # Partition blocks, one per naming context, as in Learn's sample (Configuration wrapped).
        function New-C11PartitionOutput {
            param([string]$Dc, [string]$Test, [string[]]$Failed = @(), [string[]]$Partitions = $script:C11Partitions)
            $b = New-Object System.Collections.Generic.List[string]
            $b.Add((New-C11DcOutput -Dc $Dc -Test 'Connectivity'))
            $b.Add(''); $b.Add('Doing primary tests')
            foreach ($p in $Partitions) {
                $v = 'passed'
                if ($Failed -contains $p) { $v = 'failed' }
                $b.Add(''); $b.Add(("   Running partition tests on : {0}" -f $p)); $b.Add(("      Starting test: {0}" -f $Test))
                if ($v -eq 'failed') { $b.Add(("         The cross-reference for {0} is not valid." -f $p)) }
                if ($p -eq 'Configuration') { $b.Add(("         ......................... {0} {1} test " -f $p, $v)); $b.Add(("         {0}" -f $Test)) }
                else { $b.Add(("         ......................... {0} {1} test {2}" -f $p, $v, $Test)) }
            }
            return ($b -join "`r`n")
        }
        function New-C11EnterpriseOutput {
            param([string]$Dc, [string]$Test, [string]$Name = 'contoso.com', [string]$Verdict = 'passed')
            $b = New-Object System.Collections.Generic.List[string]
            $b.Add((New-C11DcOutput -Dc $Dc -Test 'Connectivity'))
            foreach ($l in @('', ("   Running enterprise tests on : {0}" -f $Name), ("      Starting test: {0}" -f $Test), ("         ......................... {0} {1} test " -f $Name, $Verdict), ("         {0}" -f $Test))) { $b.Add($l) }
            return ($b -join "`r`n")
        }
        # DNS: the server block's verdict says the DNS tests ran on the server; the summary verdict of
        # these "enterprise-wide DNS health checks" (Learn) is printed under the enterprise block.
        function New-C11DnsOutput {
            param([string]$Dc, [string]$ServerVerdict = 'passed', [string]$EnterpriseVerdict = 'passed', [string]$Name = 'contoso.com')
            $b = New-Object System.Collections.Generic.List[string]
            $b.Add((New-C11DcOutput -Dc $Dc -Test 'DNS' -Verdict $ServerVerdict -Lines @('DNS Tests are running and not hung. Please wait a few minutes...')))
            foreach ($l in @('', ("   Running enterprise tests on : {0}" -f $Name), '      Starting test: DNS', '         Test results for domain controllers:', ("            DC: {0}" -f $Dc))) { $b.Add($l) }
            if ($EnterpriseVerdict -eq 'failed') { $b.Add('               Error: no delegated name server for _msdcs could be reached') }
            $b.Add(("         ......................... {0} {1} test DNS" -f $Name, $EnterpriseVerdict))
            return ($b -join "`r`n")
        }
        function New-C11Result { param([string]$StdOut, [bool]$Success = $true, $ExitCode = 0, $ErrorText = $null)
            [pscustomobject]@{ Success = $Success; ExitCode = $ExitCode; Attempt = 1; Error = $ErrorText; StdOut = $StdOut; OutFile = $null } }
        # The default answer: every test passes, each in the block it is printed in. FsmoCheck, like
        # Intersite and LocatorCheck in Learn's sample, answers in the enterprise block (field
        # captures; Microsoft publishes no FsmoCheck output), DNS in both.
        function Get-C11DefaultAnswer { param([string]$Server, [string]$Test)
            $short = Get-C11Short $Server
            if (@('CheckSDRefDom', 'CrossRefValidation') -contains $Test) { return (New-C11Result (New-C11PartitionOutput -Dc $short -Test $Test)) }
            if (@('Intersite', 'FsmoCheck') -contains $Test) { return (New-C11Result (New-C11EnterpriseOutput -Dc $short -Test $Test)) }
            if ($Test -eq 'DNS') { return (New-C11Result (New-C11DnsOutput -Dc $short)) }
            return (New-C11Result (New-C11DcOutput -Dc $short -Test $Test))
        }
        # The unscoped advice a grid row should reach: the dcdiag entry of the recommendation map.
        $script:C11DcdiagAdvice = [string]@($script:RecommendationMap | Where-Object { -not $_.ContainsKey('Section') -and [string]$_.Match -eq '(?i)dcdiag|advertising|netlogons|sysvolcheck|fsmocheck|kccevent' })[0].Text
        $script:C11ReplAdvice = [string]@($script:RecommendationMap | Where-Object { -not $_.ContainsKey('Section') -and [string]$_.Match -eq '(?i)replication' })[0].Text
        $script:C11Fab = 'dc9.fabrikam.com'
        # Every collector call in this Describe goes through this: the dcdiag stub answers from
        # $script:C11Answer (server, test) and records every argument string it was given.
        function Invoke-C11Collector {
            param([object[]]$Targets, [switch]$Active, [string[]]$Scoped = @('contoso.com', 'north.contoso.com'), [string]$Root = 'contoso.com',
                [hashtable]$Config = $script:Config.DcDiag, $InventoryFailures = @(), [string[]]$Down = @(), [bool]$HaveDcdiag = $true)
            $script:C11Calls = @()
            $script:C11Down = @($Down)
            $script:C11Have = $HaveDcdiag
            Clear-AdfaDcPortCache
            Mock Test-CommandAvailable { [bool]$script:C11Have }
            Mock Test-TcpPort { $script:C11Down -notcontains [string]$ComputerName }
            Mock Invoke-ExternalCommand {
                $script:C11Calls += [pscustomobject]@{ Arguments = [string]$Arguments; Timeout = $TimeoutSeconds; Retries = $Retries }
                $t = ([regex]::Match([string]$Arguments, '/test:(\S+)')).Groups[1].Value
                $s = ([regex]::Match([string]$Arguments, '/s:(\S+)')).Groups[1].Value
                & $script:C11Answer $s $t
            }
            return @(Get-AdfaDcDiagnostic -DomainControllers $Targets -IncludeActiveTests:$Active -TimeoutSeconds 5 -Retries 1 -RetryDelaySeconds 0 `
                    -Config $Config -InventoryFailures $InventoryFailures -ScopedDomains $Scoped -ForestRoot $Root)
        }
        # The comma keeps a one-row answer an array, so .Count works under StrictMode on Windows PowerShell 5.1.
        function Get-C11Grid { param($Rows) return , @($Rows | Where-Object { $null -ne $_.PSObject.Properties['DomainController'] }) }
        function Get-C11Row { param($Rows, [string]$Item) return , @($Rows | Where-Object { $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -eq $Item }) }
        function Get-C11CallsFor { param([string]$Server, [string]$Test = '')
            @($script:C11Calls | Where-Object { $_.Arguments -match ('/s:{0}(\s|$)' -f [regex]::Escape($Server)) -and ($Test -eq '' -or $_.Arguments -match ('/test:{0}(\s|$)' -f [regex]::Escape($Test))) }) }
        $script:C11ThreeDcs = @((New-C11Target $script:C11Dc1 'contoso.com' 'HQ'), (New-C11Target $script:C11Dc2 'contoso.com' 'Branch'), (New-C11Target $script:C11Dc3 'north.contoso.com' 'HQ'))
    }
    BeforeEach {
        $script:C11Answer = { param($Server, $Test) Get-C11DefaultAnswer -Server $Server -Test $Test }
    }

    Context 'Config table (Learn, read 2026-11-16)' {
        It 'lists the per-DC tests in the reference order, Connectivity first, each one in Learn''s table except the flagged FsmoCheck' {
            $names = @($script:C11Cfg['PerDcTests'] | ForEach-Object { [string]$_['Test'] })
            # Declared population: the 21 per-DC grid tests.
            ($names -join ',') | Should -Be ($script:C11PerDc -join ',')
            foreach ($entry in @($script:C11Cfg['PerDcTests'])) {
                $t = [string]$entry['Test']
                if ($t -eq 'FsmoCheck') {
                    $entry['InLearnTable'] | Should -BeFalse
                    continue
                }
                $entry['InLearnTable'] | Should -BeTrue -Because $t
                @($script:C11LearnTests | Where-Object { $_ -eq $t }).Count | Should -Be 1 -Because "$t must be in Learn's table"
            }
            # 1.29.0 since PORT-PLAN C12 added the DNS summary table to this config table.
            [string]$script:C11Cfg['Version'] | Should -Be '1.29.0'
            [string]$script:C11Cfg['SourceUrl'] | Should -Be $script:C11Url
            [string]$script:C11Cfg['ReadDate'] | Should -Be '2026-11-16'
            [string]$script:C11Cfg['ThresholdSource'] | Should -Be 'tool default, not a Microsoft value'
        }
        It 'runs Topology per domain, CheckSDRefDom and CrossRefValidation per forest and Intersite per site, and never LocatorCheck' {
            (@($script:C11Cfg['DomainTests'] | ForEach-Object { [string]$_['Test'] }) -join ',') | Should -Be 'Topology'
            (@($script:C11Cfg['ForestTests'] | ForEach-Object { [string]$_['Test'] }) -join ',') | Should -Be 'CheckSDRefDom,CrossRefValidation'
            (@($script:C11Cfg['SiteTests'] | ForEach-Object { [string]$_['Test'] }) -join ',') | Should -Be 'Intersite'
            $notAdded = @($script:C11Cfg['NotAdded'] | ForEach-Object { [string]$_['Test'] })
            $notAdded | Should -Contain 'LocatorCheck'
            $notAdded | Should -Contain 'CutoffServers'
            $everyRun = @($script:C11Cfg['PerDcTests']) + @($script:C11Cfg['DomainTests']) + @($script:C11Cfg['ForestTests']) + @($script:C11Cfg['SiteTests'])
            # Declared population: 21 per DC, 1 per domain, 2 per forest, 1 per site.
            @($everyRun).Count | Should -Be 25
            foreach ($banned in @('LocatorCheck', 'CutoffServers', 'DcPromo', 'RegisterInDNS', 'OutboundSecureChannels')) {
                @($everyRun | Where-Object { [string]$_['Test'] -eq $banned }).Count | Should -Be 0 -Because "$banned is not run"
            }
            'LocatorCheck' | Should -Not -BeIn $script:C11LearnTests   # the reason it is not run
        }
        It 'holds back SystemLog with DNS and Intersite, because Learn says it reads AND WRITES entries' {
            $active = @($script:Config.DcdiagActiveTests)
            # Declared population: the three tests Microsoft's text describes as changing state.
            (@($active | ForEach-Object { [string]$_.Test }) -join ',') | Should -Be 'DNS,Intersite,SystemLog'
            $sl = @($active | Where-Object { $_.Test -eq 'SystemLog' })[0]
            [string]$sl.Quote | Should -Match 'reading and writing entries'
            [string]$sl.Source | Should -Be $script:C11Url
            [string]$sl.ReadDate | Should -Be '2026-11-16'
        }
        It 'keeps RidManager in the default list on Learn''s description of what it checks (C6e)' {
            $rid = @($script:C11Cfg['PerDcTests'] | Where-Object { [string]$_['Test'] -eq 'RidManager' })
            $rid.Count | Should -Be 1
            [string]$rid[0]['Learn'] | Should -Match 'Checks whether the relative identifier \(RID\) master is accessible'
            [string]$rid[0]['Source'] | Should -Be $script:C11Url
            [string]$rid[0]['ReadDate'] | Should -Be '2026-11-16'
            @($script:Config.DcdiagActiveTests | Where-Object { $_.Test -eq 'RidManager' }).Count | Should -Be 0
        }
        It 'marks the unreachable-DC patterns provisional, and sources the event-log and access-denied ones' {
            $un = @($script:C11Cfg['UnreachablePatterns'])
            $un.Count | Should -Be 2
            foreach ($p in $un) { $p['Provisional'] | Should -BeTrue }
            $ev = @($script:C11Cfg['EventLogUnreadablePatterns'])
            $ev.Count | Should -Be 1
            [string]$ev[0]['Source'] | Should -Match '^https://learn\.microsoft\.com/troubleshoot/windows-server/identity/dcdiag-commands-running-errors'
            $ad = @($script:C11Cfg['AccessDeniedPatterns'])
            $ad.Count | Should -Be 1
            [string]$ad[0]['Source'] | Should -Match 'system-error-codes--0-499-'
            # Which per-DC tests read an event log, and which may have partition parts for their DC.
            (@($script:C11Cfg['PerDcTests'] | Where-Object { $_['EventLog'] } | ForEach-Object { [string]$_['Test'] }) -join ',') | Should -Be 'DFSREvent,FrsEvent,KccEvent,SystemLog'
            (@($script:C11Cfg['PerDcTests'] | Where-Object { $_['PartitionParts'] } | ForEach-Object { [string]$_['Test'] }) -join ',') | Should -Be 'Replications,VerifyReplicas'
            # And which are enterprise tests whose verdict, in a /s:<dc> invocation, is the DC's own.
            (@($script:C11Cfg['PerDcTests'] | Where-Object { $_['EnterpriseParts'] } | ForEach-Object { [string]$_['Test'] }) -join ',') | Should -Be 'FsmoCheck,DNS'
            # Declared population: every one of the 21 per-DC entries states the flag.
            @($script:C11Cfg['PerDcTests'] | Where-Object { -not $_.ContainsKey('EnterpriseParts') }).Count | Should -Be 0
        }
        It 'never builds a repair, comprehensive, credential or enterprise switch for any configured test' {
            $all = @($script:C11Cfg['PerDcTests']) + @($script:C11Cfg['DomainTests']) + @($script:C11Cfg['ForestTests']) + @($script:C11Cfg['SiteTests'])
            $built = @($all | ForEach-Object { Get-AdfaDcdiagArgument -TestName ([string]$_['Test']) -DomainController $script:C11Dc1 })
            $built.Count | Should -Be 25
            @($built | Where-Object { $_ -match '(?i)/(fix|c|e|u:|p:|RecreateMachineAccount|FixMachineAccount|ReplSource|skip)(\s|:|$)' }).Count | Should -Be 0
            @($built | Where-Object { $_ -notmatch ('/s:{0}(\s|$)' -f [regex]::Escape($script:C11Dc1)) }).Count | Should -Be 0
            # Exactly one test takes /a (Intersite, which skips its testing without it) and one /DnsAll.
            @($built | Where-Object { $_ -match '\s/a$' }).Count | Should -Be 1
            @($built | Where-Object { $_ -match '/DnsAll' }).Count | Should -Be 1
        }
    }

    Context 'Parser: ConvertFrom-AdfaDcdiagOutput' {
        It 'attributes each verdict to its block, and reads a verdict whose test name wrapped onto the next line' {
            $out = (New-C11PartitionOutput -Dc 'DC1' -Test 'CrossRefValidation' -Failed @('Schema'))
            $p = ConvertFrom-AdfaDcdiagOutput -StdOut $out -Config $script:C11Cfg
            $p.Recognised | Should -BeTrue
            $parts = @($p.Parts | Where-Object { $_.Test -eq 'CrossRefValidation' })
            # Declared population: one part per partition block, the wrapped Configuration included.
            $parts.Count | Should -Be 5
            (@($parts | ForEach-Object { $_.ScopeName }) -join ',') | Should -Be ($script:C11Partitions -join ',')
            @($parts | Where-Object { $_.ScopeKind -ne 'Partition' }).Count | Should -Be 0
            @($parts | Where-Object { $_.ScopeName -eq 'Configuration' })[0].Verdict | Should -Be 'Pass'
            @($parts | Where-Object { $_.ScopeName -eq 'Schema' })[0].Verdict | Should -Be 'Fail'
            $conn = @($p.Parts | Where-Object { $_.Test -eq 'Connectivity' })
            $conn.Count | Should -Be 1
            $conn[0].ScopeKind | Should -Be 'Server'
            $conn[0].ScopeName | Should -Be 'DC1'
            $conn[0].Subject | Should -Be 'DC1'
        }
        It 'puts an enterprise result in its enterprise block' {
            $p = ConvertFrom-AdfaDcdiagOutput -StdOut (New-C11EnterpriseOutput -Dc 'DC1' -Test 'Intersite' -Verdict 'failed') -Config $script:C11Cfg
            $e = @($p.Parts | Where-Object { $_.Test -eq 'Intersite' })
            $e.Count | Should -Be 1
            $e[0].ScopeKind | Should -Be 'Enterprise'
            $e[0].ScopeName | Should -Be 'contoso.com'
            $e[0].Verdict | Should -Be 'Fail'
        }
        It 'reads a bare verdict outside any block as scope None, and strips the dots from a subject written against them' {
            $p = ConvertFrom-AdfaDcdiagOutput -StdOut "passed test Advertising`n.........................DC2 failed test Services" -Config $script:C11Cfg
            @($p.Parts).Count | Should -Be 2
            $p.Parts[0].ScopeKind | Should -Be 'None'
            $p.Parts[0].Subject | Should -Be ''
            $p.Parts[1].Subject | Should -Be 'DC2'
            $p.Parts[1].Verdict | Should -Be 'Fail'
        }
        It 'does not let a longer test name satisfy a shorter one' {
            $p = ConvertFrom-AdfaDcdiagOutput -StdOut '......................... DC1 passed test NetlogonsExtra' -Config $script:C11Cfg
            @($p.Parts | Where-Object { $_.Test -eq 'Netlogons' }).Count | Should -Be 0
        }
        It 'recognises nothing in empty or localised output, and reads no part from it' {
            $empty = ConvertFrom-AdfaDcdiagOutput -StdOut '' -Config $script:C11Cfg
            $empty.Empty | Should -BeTrue
            $empty.Recognised | Should -BeFalse
            $loc = ConvertFrom-AdfaDcdiagOutput -StdOut "Diagnostico do Servidor de Diretorio`nA testar o servidor: Default-First-Site-Name\DC1`n......................... DC1 passou no teste Advertising" -Config $script:C11Cfg
            $loc.Empty | Should -BeFalse
            $loc.Recognised | Should -BeFalse
            @($loc.Parts).Count | Should -Be 0
        }
        It 'keeps the unreachable, access-denied and event-log evidence apart' {
            $u = ConvertFrom-AdfaDcdiagOutput -StdOut "Directory Server Diagnosis`nLdap search capability attribute search failed on server DC1, return value = 81" -Config $script:C11Cfg
            @($u.UnreachableEvidence).Count | Should -Be 1
            @($u.AccessDeniedEvidence).Count | Should -Be 0
            $a = ConvertFrom-AdfaDcdiagOutput -StdOut "Directory Server Diagnosis`n[DC1] LDAP bind failed with error 5, Access is denied." -Config $script:C11Cfg
            @($a.AccessDeniedEvidence).Count | Should -Be 1
            @($a.UnreachableEvidence).Count | Should -Be 0
            $e = ConvertFrom-AdfaDcdiagOutput -StdOut "Starting test: SystemLog`nThe event log System on server dc1.contoso.com could not be queried, error 0x6ba ""The RPC server is unavailable.""`n......................... DC1 failed test SystemLog" -Config $script:C11Cfg
            @($e.EventLogUnreadableEvidence).Count | Should -Be 1
            @($e.UnreachableEvidence).Count | Should -Be 0
        }
    }

    Context 'Verdict: Resolve-AdfaDcdiagVerdict (pure)' {
        BeforeAll {
            function Resolve-C11 { param([string]$Out, [string]$Test, [string]$HostName = $script:C11Dc1, [bool]$PartitionParts = $false, [bool]$EventLog = $false, [string]$Mode = 'Dc', [bool]$Success = $true, [bool]$EnterpriseParts = $false)
                $p = ConvertFrom-AdfaDcdiagOutput -StdOut $Out -Config $script:C11Cfg
                Resolve-AdfaDcdiagVerdict -Parsed $p -TestName $Test -Mode $Mode -HostName $HostName -PartitionParts $PartitionParts -EnterpriseParts $EnterpriseParts -EventLog $EventLog -Success $Success -ExitCode 0 -ErrorText '' -StdOut $Out }
        }
        It 'grades the DC''s own passed and failed verdicts, a wrapped one included' {
            (Resolve-C11 (New-C11DcOutput -Dc 'DC1' -Test 'Advertising') 'Advertising').Status | Should -Be 'Pass'
            (Resolve-C11 (New-C11DcOutput -Dc 'DC1' -Test 'Advertising' -Wrap) 'Advertising').Status | Should -Be 'Pass'
            $f = Resolve-C11 (New-C11DcOutput -Dc 'DC1' -Test 'Advertising' -Verdict 'failed' -Lines @('Warning: DC1 is not advertising as a time server.')) 'Advertising'
            $f.Status | Should -Be 'Fail'
            $f.Detail | Should -Match '^Advertising: '
            $f.Detail | Should -Match 'not advertising as a time server'
        }
        It 'reads Fail when a DC has both a failed and a passed verdict for the test, in either order (the R2 false pass)' {
            $a = "......................... DC1 passed test Replications`n......................... DC1 failed test Replications"
            $b = "......................... DC1 failed test Replications`n......................... DC1 passed test Replications"
            (Resolve-C11 $a 'Replications').Status | Should -Be 'Fail'
            (Resolve-C11 $b 'Replications').Status | Should -Be 'Fail'
            Get-AdfaDcdiagTestOutcome -TestName 'Replications' -StdOut $a | Should -Be 'Fail'
            Get-AdfaDcdiagTestOutcome -TestName 'Replications' -StdOut $b | Should -Be 'Fail'
        }
        It 'never counts another DC''s verdict for this DC, and grades it for that DC' {
            $out = New-C11DcOutput -Dc 'DC2' -Test 'Services' -Verdict 'failed'
            $for1 = Resolve-C11 $out 'Services' $script:C11Dc1
            $for1.Status | Should -Be 'Not Assessed'
            $for1.Detail | Should -Match 'not counted'
            (Resolve-C11 $out 'Services' $script:C11Dc2).Status | Should -Be 'Fail'
        }
        It 'matches a host name longer than 15 characters to its NetBIOS form, and only that' {
            $long = 'maplewaffle-ws22.contoso.com'
            (Resolve-C11 (New-C11DcOutput -Dc 'MAPLEWAFFLE-WS2' -Test 'Advertising') 'Advertising' $long).Status | Should -Be 'Pass'
            Test-AdfaDcdiagSubject -Subject 'MAPLEWAFFLE-WS2' -HostName $long | Should -BeTrue
            Test-AdfaDcdiagSubject -Subject 'DC1' -HostName 'dc10.contoso.com' | Should -BeFalse
            Test-AdfaDcdiagSubject -Subject 'dc1' -HostName $script:C11Dc1 | Should -BeTrue
            Test-AdfaDcdiagSubject -Subject 'dc1.contoso.com' -HostName $script:C11Dc1 | Should -BeTrue
            Test-AdfaDcdiagSubject -Subject '' -HostName $script:C11Dc1 | Should -BeFalse
        }
        It 'never matches a shorter prefix of a long host name, only its exact 15-character NetBIOS form' {
            $long = 'maplewaffle-ws22.corp.contoso.com'
            Test-AdfaDcdiagSubject -Subject 'MAPLEWAFFLE-WS2' -HostName $long | Should -BeTrue
            # 11 and 14 characters: prefixes of the label, but not its NetBIOS form.
            Test-AdfaDcdiagSubject -Subject 'MAPLEWAFFLE' -HostName $long | Should -BeFalse
            Test-AdfaDcdiagSubject -Subject 'MAPLEWAFFLE-WS' -HostName $long | Should -BeFalse
            (Resolve-C11 (New-C11DcOutput -Dc 'MAPLEWAFFLE' -Test 'Advertising' -Verdict 'failed') 'Advertising' $long).Status | Should -Be 'Not Assessed'
        }
        It 'counts an enterprise verdict for a test with enterprise parts, and failed wins over the server block''s passed (DNS)' {
            $dnsFail = New-C11DnsOutput -Dc 'DC1' -EnterpriseVerdict 'failed'
            $r = Resolve-C11 $dnsFail 'DNS' -EnterpriseParts $true
            $r.Status | Should -Be 'Fail'
            $r.Detail | Should -Match 'failed in the enterprise tests on contoso\.com, which dcdiag ran from this domain controller'
            (Resolve-C11 (New-C11DnsOutput -Dc 'DC1') 'DNS' -EnterpriseParts $true).Status | Should -Be 'Pass'
            # Without the flag the enterprise summary is not counted: the server block alone would
            # read Pass, which is why DNS carries the flag.
            (Resolve-C11 $dnsFail 'DNS').Status | Should -Be 'Pass'
            (@($script:C11Cfg['PerDcTests'] | Where-Object { [string]$_['Test'] -eq 'DNS' })[0])['EnterpriseParts'] | Should -BeTrue
        }
        It 'grades FsmoCheck from its enterprise block for the DC asked: Pass when it passed, Fail when it failed' {
            (Resolve-C11 (New-C11EnterpriseOutput -Dc 'DC1' -Test 'FsmoCheck') 'FsmoCheck' -EnterpriseParts $true).Status | Should -Be 'Pass'
            $f = Resolve-C11 (New-C11EnterpriseOutput -Dc 'DC1' -Test 'FsmoCheck' -Verdict 'failed') 'FsmoCheck' -EnterpriseParts $true
            $f.Status | Should -Be 'Fail'
            $f.Detail | Should -Match 'enterprise tests on contoso\.com'
        }
        It 'does not count a bare verdict printed inside another DC''s server block for this DC' {
            $out = "Doing primary tests`r`n   Testing server: Default-First-Site-Name\DC2`r`n      Starting test: Advertising`r`n         ......................... passed test Advertising"
            $r = Resolve-C11 $out 'Advertising' $script:C11Dc1
            $r.Status | Should -Be 'Not Assessed'
            $r.Detail | Should -Match 'only for DC2'
            (Resolve-C11 $out 'Advertising' $script:C11Dc2).Status | Should -Be 'Pass'
        }
        It 'does not name a Connectivity failure that dcdiag printed for another DC as this DC''s cause' {
            $r = Resolve-C11 (New-C11DcOutput -Dc 'DC2' -Test 'Connectivity' -Verdict 'failed') 'Advertising' $script:C11Dc1
            $r.Status | Should -Be 'Not Assessed'
            $r.Detail | Should -Not -Match 'Connectivity test failed'
            (Resolve-C11 (New-C11DcOutput -Dc 'DC2' -Test 'Connectivity' -Verdict 'failed') 'Advertising' $script:C11Dc2).Detail | Should -Match 'Connectivity test failed'
        }
        It 'names the partition a DC''s failed Replications verdict was printed for' {
            $r = Resolve-C11 (New-C11PartitionOutput -Dc 'DC1' -Test 'Replications' -Failed @('Configuration')) 'Replications' -PartitionParts $true
            $r.Status | Should -Be 'Fail'
            $r.Detail | Should -Match '^Replications: failed for partition\(s\) Configuration: '
        }
        It 'reads English banner-only output as no verdict line, not as possibly localised' {
            $r = Resolve-C11 "Directory Server Diagnosis`r`n`r`nPerforming initial setup:`r`n   Trying to find home server...`r`n   Home Server = DC1" 'Advertising'
            $r.Status | Should -Be 'Not Assessed'
            $r.Detail | Should -Match "neither 'passed test Advertising' nor 'failed test Advertising'"
            $r.Detail | Should -Not -Match 'localised'
        }
        It 'never counts a partition or enterprise result against a DC test that does not have partition parts' {
            $r = Resolve-C11 (New-C11PartitionOutput -Dc 'DC1' -Test 'NCSecDesc' -Failed @('Schema')) 'NCSecDesc'
            $r.Status | Should -Be 'Not Assessed'
            $r.Detail | Should -Match 'not counted'
            $e = Resolve-C11 (New-C11EnterpriseOutput -Dc 'DC1' -Test 'KnowsOfRoleHolders' -Verdict 'failed') 'KnowsOfRoleHolders'
            $e.Status | Should -Be 'Not Assessed'
        }
        It 'counts partition parts for Replications and VerifyReplicas, and any failed part fails the DC' {
            $out = New-C11PartitionOutput -Dc 'DC1' -Test 'VerifyReplicas' -Failed @('DomainDnsZones')
            (Resolve-C11 $out 'VerifyReplicas' -PartitionParts $true).Status | Should -Be 'Fail'
            (Resolve-C11 (New-C11PartitionOutput -Dc 'DC1' -Test 'VerifyReplicas') 'VerifyReplicas' -PartitionParts $true).Status | Should -Be 'Pass'
        }
        It 'turns a failed event-log test whose log could not be queried into Not Assessed, and only an event-log test' {
            $lines = @('The event log System on server dc1.contoso.com could not be queried, error 0x6ba "The RPC server is unavailable."')
            $ev = Resolve-C11 (New-C11DcOutput -Dc 'DC1' -Test 'SystemLog' -Verdict 'failed' -Lines $lines) 'SystemLog' -EventLog $true
            $ev.Status | Should -Be 'Not Assessed'
            $ev.Detail | Should -Match 'could not be queried'
            $ev.Detail | Should -Match 'Remote Event Log Management'
            (Resolve-C11 (New-C11DcOutput -Dc 'DC1' -Test 'Replications' -Verdict 'failed' -Lines $lines) 'Replications').Status | Should -Be 'Fail'
        }
        It 'tells an unreachable DC from access denied when no verdict was printed' {
            $u = Resolve-C11 "Directory Server Diagnosis`nPerforming initial setup:`nLdap search capability attribute search failed on server DC1, return value = 81" 'Advertising'
            $u.Status | Should -Be 'Not Assessed'
            $u.Detail | Should -Match 'could not reach'
            $u.Detail | Should -Match 'provisional'
            $u.Detail | Should -Match 'return value = 81'
            $u.Detail | Should -Not -Match '(?i)access denied'
            $d = Resolve-C11 "Directory Server Diagnosis`n[DC1] An net use or LsaPolicy operation failed with error 5, Access is denied." 'NetLogons'
            $d.Status | Should -Be 'Not Assessed'
            $d.Detail | Should -Match 'access denied'
            $d.Detail | Should -Not -Match 'could not reach'
        }
        It 'keeps a failed verdict that also says Access is denied as Fail, and notes the possible cause' {
            $r = Resolve-C11 (New-C11DcOutput -Dc 'DC1' -Test 'Replications' -Verdict 'failed' -Lines @('The replication generated an error (5): Access is denied.')) 'Replications'
            $r.Status | Should -Be 'Fail'
            $r.Detail | Should -Match 'Access is denied'
            # The note itself, from a fixture whose "Access is denied." line is not one of the
            # diagnostic lines copied into the Detail (it holds no error/failed/could not word).
            $n = Resolve-C11 (New-C11DcOutput -Dc 'DC1' -Test 'NetLogons' -Verdict 'failed' -Lines @('Unable to connect to the NETLOGON share! (\\DC1\netlogon)', 'Access is denied.')) 'Netlogons'
            $n.Status | Should -Be 'Fail'
            $n.Detail | Should -Match 'KB 3073945'
            $n.Detail | Should -Match 'the rights of the account running dcdiag'
            # Worded so that it cannot choose the replication advice for a share-access failure.
            $n.Detail | Should -Not -Match '(?i)replication'
        }
        It 'never reads Pass from output it did not recognise, from no output, or from a tool that did not run' {
            $loc = Resolve-C11 "Diagnostico do Servidor de Diretorio`n......................... DC1 passou no teste Advertising" 'Advertising'
            $loc.Status | Should -Be 'Not Assessed'
            $loc.Detail | Should -Match 'not recognised'
            $loc.Detail | Should -Match 'localised'
            $none = Resolve-C11 '' 'Advertising'
            $none.Status | Should -Be 'Not Assessed'
            $none.Detail | Should -Match 'NO output'
            $tool = Resolve-C11 '' 'Advertising' -Success $false
            $tool.Status | Should -Be 'Not Assessed'
            $tool.Detail | Should -Match 'did not complete'
            $missing = Resolve-C11 (New-C11DcOutput -Dc 'DC1' -Test 'Connectivity') 'Advertising'
            $missing.Status | Should -Be 'Not Assessed'
            $missing.Detail | Should -Match 'Advertising: NOT ASSESSED'
        }
        It 'names the initial Connectivity failure when it is why a test printed no verdict' {
            $out = (New-C11DcOutput -Dc 'DC1' -Test 'Connectivity' -Verdict 'failed') + "`r`n   Skipping all tests, because server DC1 is not responding to directory service requests."
            $r = Resolve-C11 $out 'Advertising'
            $r.Status | Should -Be 'Not Assessed'
            $r.Detail | Should -Match 'Connectivity'
        }
        It 'in scope mode counts every part, and fails on one failed part' {
            (Resolve-C11 (New-C11PartitionOutput -Dc 'DC1' -Test 'CheckSDRefDom' -Failed @('contoso')) 'CheckSDRefDom' -Mode 'Scope').Status | Should -Be 'Fail'
            $ok = Resolve-C11 (New-C11PartitionOutput -Dc 'DC1' -Test 'CheckSDRefDom') 'CheckSDRefDom' -Mode 'Scope'
            $ok.Status | Should -Be 'Pass'
            @($ok.Parts).Count | Should -Be 5
            (Resolve-C11 (New-C11DcOutput -Dc 'DC1' -Test 'Connectivity') 'CheckSDRefDom' -Mode 'Scope').Status | Should -Be 'Not Assessed'
        }
        It 'falls back to a usable DC whose Connectivity was not assessed, writable first, when none passed it' {
            $na1 = [pscustomobject]@{ HostName = 'dc6.contoso.com'; IsReadOnly = $null; Usable = $true; Connectivity = 'Not Assessed' }
            $na2 = [pscustomobject]@{ HostName = 'dc7.contoso.com'; IsReadOnly = $false; Usable = $true; Connectivity = 'Not Assessed' }
            $ro = [pscustomobject]@{ HostName = 'rodc8.contoso.com'; IsReadOnly = $true; Usable = $true; Connectivity = 'Not Assessed' }
            [string](Select-AdfaDcdiagTarget -States @($ro, $na1, $na2)).HostName | Should -Be 'dc7.contoso.com'
            [string](Select-AdfaDcdiagTarget -States @($ro, $na1)).HostName | Should -Be 'dc6.contoso.com'
            $null -eq (Select-AdfaDcdiagTarget -States @($ro)) | Should -BeTrue
        }
    }

    Context 'Collector: the per-DC grid' {
        It 'gives every DC of every domain a grid row with its domain, 19 attempted tests and Connectivity first' {
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs
            $grid = Get-C11Grid $rows
            # Declared population: the three targets.
            $grid.Count | Should -Be 3
            foreach ($t in $script:C11ThreeDcs) {
                $row = @($grid | Where-Object { $_.DomainController -eq $t.HostName })
                $row.Count | Should -Be 1 -Because $t.HostName
                [string]$row[0].Scope | Should -Be $t.Scope
                [string]$row[0].Status | Should -Be 'Pass' -Because $t.HostName
                $calls = @(Get-C11CallsFor -Server $t.HostName | Where-Object { $_.Arguments -notmatch '/test:(Topology|CheckSDRefDom|CrossRefValidation)\b' })
                $calls.Count | Should -Be 19 -Because "$($t.HostName) runs 19 tests by default"
                $calls[0].Arguments | Should -Match '^/test:Connectivity '
                foreach ($name in $script:C11PerDc) {
                    $expect = 'Pass'
                    if (@('SystemLog', 'DNS') -contains $name) { $expect = 'Not Assessed' }
                    [string]$row[0].("DCDIAG_$name") | Should -Be $expect -Because "$($t.HostName) $name"
                }
                [string]$row[0].NotRun | Should -Match 'SystemLog'
                [string]$row[0].NotRun | Should -Match 'reading and writing'
                [string]$row[0].NotRun | Should -Not -Match 'Intersite'
            }
            $cells = @($grid[0].PSObject.Properties | Where-Object { $_.Name -like 'DCDIAG_*' } | ForEach-Object { $_.Name -replace '^DCDIAG_', '' })
            ($cells -join ',') | Should -Be ($script:C11PerDc -join ',')
            @($script:C11Calls | Where-Object { $_.Arguments -match '/test:(SystemLog|DNS|Intersite|LocatorCheck)\b' }).Count | Should -Be 0
        }
        It 'stops at a failed Connectivity on that DC only, keeps it as Fail with the ICMP caveat, and runs nothing more there' {
            $script:C11Answer = { param($Server, $Test)
                if ($Server -eq $script:C11Dc2 -and $Test -eq 'Connectivity') { return (New-C11Result (New-C11DcOutput -Dc 'DC2' -Test 'Connectivity' -Verdict 'failed' -Lines @('Ldap search capability attribute search failed on server DC2, return value = 81')) -Success $false -ExitCode 1) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $grid = Get-C11Grid (Invoke-C11Collector -Targets $script:C11ThreeDcs)
            $two = @($grid | Where-Object { $_.DomainController -eq $script:C11Dc2 })[0]
            [string]$two.DCDIAG_Connectivity | Should -Be 'Fail'
            [string]$two.Status | Should -Be 'Fail'
            @(Get-C11CallsFor -Server $script:C11Dc2).Count | Should -Be 1
            foreach ($name in @($script:C11PerDc | Where-Object { $_ -ne 'Connectivity' })) { [string]$two.("DCDIAG_$name") | Should -Be 'Not Assessed' -Because $name }
            [string]$two.Failures | Should -Match 'ICMP'
            # The tests not started are named in NotRun, never in Failures, the text the
            # recommendation is chosen from: their names would choose the replication advice.
            [string]$two.NotRun | Should -Match 'Not run after Connectivity failed: Replications'
            [string]$two.Failures | Should -Not -Match 'Not run after|Replications|SysVolCheck'
            $finding = ConvertTo-AdfaConsolidatedFinding -Section 'DC Diagnostics' -Row $two -StatusColumn 'Status'
            [string]$finding.Recommendation | Should -Be $script:C11DcdiagAdvice
            [string]$finding.Detail | Should -Match 'Not run after Connectivity failed'
            foreach ($other in @($script:C11Dc1, $script:C11Dc3)) {
                [string]@($grid | Where-Object { $_.DomainController -eq $other })[0].Status | Should -Be 'Pass' -Because $other
                @(Get-C11CallsFor -Server $other | Where-Object { $_.Arguments -notmatch '/test:(Topology|CheckSDRefDom|CrossRefValidation)\b' }).Count | Should -Be 19 -Because $other
            }
        }
        It 'gives a DC closed on RPC/135 Not Assessed cells and runs nothing against it, while the others run' {
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs -Down @($script:C11Dc3)
            $grid = Get-C11Grid $rows
            $three = @($grid | Where-Object { $_.DomainController -eq $script:C11Dc3 })[0]
            [string]$three.Ping | Should -Be 'Fail'
            [string]$three.Failures | Should -Match 'not reachable \(RPC/135\)'
            @(Get-C11CallsFor -Server $script:C11Dc3).Count | Should -Be 0
            foreach ($name in $script:C11PerDc) { [string]$three.("DCDIAG_$name") | Should -Be 'Not Assessed' -Because $name }
            @($grid | Where-Object { $_.DomainController -ne $script:C11Dc3 -and $_.Ping -eq 'Pass' -and $_.Status -eq 'Pass' }).Count | Should -Be 2
            # The domain whose only DC is unreachable has no Topology verdict.
            $topo = Get-C11Row $rows 'dcdiag Topology: north.contoso.com'
            $topo.Count | Should -Be 1
            [string]$topo[0].Status | Should -Be 'Not Assessed'
            @(Get-C11CallsFor -Server $script:C11Dc3 -Test 'Topology').Count | Should -Be 0
        }
        It 'reports access denied as its own cause, the DC row Not Assessed, never Fail and never unreachable' {
            $script:C11Answer = { param($Server, $Test)
                if ($Server -eq $script:C11Dc2) { return (New-C11Result ("Directory Server Diagnosis`r`nPerforming initial setup:`r`n[DC2] LDAP bind failed with error 5,`r`nAccess is denied.") -Success $false -ExitCode 1) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $grid = Get-C11Grid (Invoke-C11Collector -Targets $script:C11ThreeDcs)
            $two = @($grid | Where-Object { $_.DomainController -eq $script:C11Dc2 })[0]
            [string]$two.Status | Should -Be 'Not Assessed'
            [string]$two.Ping | Should -Be 'Pass'
            [string]$two.Failures | Should -Match 'access denied'
            [string]$two.Failures | Should -Not -Match 'could not reach|not reachable'
            @($script:C11PerDc | Where-Object { [string]$two.("DCDIAG_$_") -ne 'Not Assessed' }).Count | Should -Be 0
            [string]@($grid | Where-Object { $_.DomainController -eq $script:C11Dc1 })[0].Status | Should -Be 'Pass'
        }
        It 'grades a mixed result per DC: one DC''s failed partition fails that DC''s Replications only' {
            $script:C11Answer = { param($Server, $Test)
                if ($Server -eq $script:C11Dc1 -and $Test -eq 'Replications') { return (New-C11Result (New-C11PartitionOutput -Dc 'DC1' -Test 'Replications' -Failed @('Configuration')) -Success $false -ExitCode 1) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $grid = Get-C11Grid (Invoke-C11Collector -Targets $script:C11ThreeDcs)
            $one = @($grid | Where-Object { $_.DomainController -eq $script:C11Dc1 })[0]
            [string]$one.DCDIAG_Replications | Should -Be 'Fail'
            [string]$one.Status | Should -Be 'Fail'
            [string]$one.Failures | Should -Match '^Replications: failed for partition\(s\) Configuration: '
            @($grid | Where-Object { $_.DomainController -ne $script:C11Dc1 -and $_.DCDIAG_Replications -eq 'Pass' }).Count | Should -Be 2
        }
        It 'grades FsmoCheck from its enterprise block on every DC (declared population: three DCs), and fails only the DC whose run failed' {
            $script:C11Answer = { param($Server, $Test)
                if ($Server -eq $script:C11Dc3 -and $Test -eq 'FsmoCheck') { return (New-C11Result (New-C11EnterpriseOutput -Dc 'DC3' -Test 'FsmoCheck' -Verdict 'failed') -Success $false -ExitCode 1) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $grid = Get-C11Grid (Invoke-C11Collector -Targets $script:C11ThreeDcs)
            $grid.Count | Should -Be 3
            foreach ($dc in @($script:C11Dc1, $script:C11Dc2)) {
                $row = @($grid | Where-Object { $_.DomainController -eq $dc })[0]
                [string]$row.DCDIAG_FsmoCheck | Should -Be 'Pass' -Because $dc
                [string]$row.Status | Should -Be 'Pass' -Because $dc
            }
            $three = @($grid | Where-Object { $_.DomainController -eq $script:C11Dc3 })[0]
            [string]$three.DCDIAG_FsmoCheck | Should -Be 'Fail'
            [string]$three.Status | Should -Be 'Fail'
            [string]$three.Failures | Should -Match '^FsmoCheck: failed in the enterprise tests on contoso\.com'
        }
        It 'with the opt-in fails the DNS cell when the enterprise DNS summary failed, although the server block passed' {
            $script:C11Answer = { param($Server, $Test)
                if ($Server -eq $script:C11Dc2 -and $Test -eq 'DNS') { return (New-C11Result (New-C11DnsOutput -Dc 'DC2' -EnterpriseVerdict 'failed') -Success $false -ExitCode 1) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $grid = Get-C11Grid (Invoke-C11Collector -Targets $script:C11ThreeDcs -Active)
            [string]@($grid | Where-Object { $_.DomainController -eq $script:C11Dc2 })[0].DCDIAG_DNS | Should -Be 'Fail'
            [string]@($grid | Where-Object { $_.DomainController -eq $script:C11Dc2 })[0].Status | Should -Be 'Fail'
            foreach ($dc in @($script:C11Dc1, $script:C11Dc3)) { [string]@($grid | Where-Object { $_.DomainController -eq $dc })[0].DCDIAG_DNS | Should -Be 'Pass' -Because $dc }
        }
        It 'gives a failed share-access test that says Access is denied the dcdiag advice, not the replication advice' {
            $script:C11Answer = { param($Server, $Test)
                if ($Server -eq $script:C11Dc1 -and $Test -eq 'Netlogons') { return (New-C11Result (New-C11DcOutput -Dc 'DC1' -Test 'NetLogons' -Verdict 'failed' -Lines @('Unable to connect to the NETLOGON share! (\\DC1\netlogon)', '[DC1] An net use or LsaPolicy operation failed with error 5, Access is denied.')) -Success $false -ExitCode 1) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $grid = Get-C11Grid (Invoke-C11Collector -Targets $script:C11ThreeDcs)
            $one = @($grid | Where-Object { $_.DomainController -eq $script:C11Dc1 })[0]
            [string]$one.DCDIAG_Netlogons | Should -Be 'Fail'
            [string]$one.Failures | Should -Match 'KB 3073945'
            $finding = ConvertTo-AdfaConsolidatedFinding -Section 'DC Diagnostics' -Row $one -StatusColumn 'Status'
            [string]$finding.Recommendation | Should -Be $script:C11DcdiagAdvice
            [string]$finding.Recommendation | Should -Not -Be $script:C11ReplAdvice
        }
        It 'gives a row with one unrecognised (possibly localised) cell the dcdiag advice, not the event-log coverage advice' {
            $script:C11Answer = { param($Server, $Test)
                if ($Test -eq 'KccEvent') { return (New-C11Result ("Diagnostic du serveur d'annuaire`r`n......................... {0} a reussi le test KccEvent" -f (Get-C11Short $Server))) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $grid = Get-C11Grid (Invoke-C11Collector -Targets $script:C11ThreeDcs)
            # Declared population: the three DCs, each with its KccEvent cell unrecognised.
            $grid.Count | Should -Be 3
            foreach ($row in $grid) {
                [string]$row.DCDIAG_KccEvent | Should -Be 'Not Assessed' -Because $row.DomainController
                [string]$row.Status | Should -Be 'Warning' -Because $row.DomainController
                $finding = ConvertTo-AdfaConsolidatedFinding -Section 'DC Diagnostics' -Row $row -StatusColumn 'Status'
                [string]$finding.Recommendation | Should -Be $script:C11DcdiagAdvice -Because $row.DomainController
            }
        }
        It 'reports localised output as not recognised on every cell, and the row Not Assessed, never Pass' {
            $script:C11Answer = { param($Server, $Test) New-C11Result ("Diagnostico do Servidor de Diretorio`r`n......................... DC1 passou no teste {0}" -f $Test) }
            $rows = Invoke-C11Collector -Targets @($script:C11ThreeDcs[0])
            $one = (Get-C11Grid $rows)[0]
            [string]$one.Status | Should -Be 'Not Assessed'
            [string]$one.Failures | Should -Match 'not recognised'
            @($rows | Where-Object { $_.Status -eq 'Pass' }).Count | Should -Be 0
        }
        It 'reports no DC at all as Not Assessed rows, runs nothing, and names each scoped domain' {
            $rows = Invoke-C11Collector -Targets @() -InventoryFailures @([pscustomobject]@{ Domain = 'north.contoso.com'; Error = 'STUB: ADWS unreachable' })
            @($script:C11Calls).Count | Should -Be 0
            (Get-C11Row $rows 'dcdiag grid').Count | Should -Be 1
            foreach ($d in @('contoso.com', 'north.contoso.com')) {
                $cov = Get-C11Row $rows ("dcdiag coverage: {0}" -f $d)
                $cov.Count | Should -Be 1 -Because $d
                [string]$cov[0].Status | Should -Be 'Not Assessed'
                (Get-C11Row $rows ("dcdiag Topology: {0}" -f $d))[0].Status | Should -Be 'Not Assessed'
            }
            [string](Get-C11Row $rows 'dcdiag coverage: north.contoso.com')[0].Detail | Should -Match 'ADWS unreachable'
            @($rows | Where-Object { $_.Status -match '^(Pass|Fail|Warning)$' }).Count | Should -Be 0
        }
        It 'reports dcdiag.exe missing as Not Assessed everywhere' {
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs -HaveDcdiag $false
            @($script:C11Calls).Count | Should -Be 0
            @($rows | Where-Object { $_.Status -ne 'Not Assessed' -and $_.Status -ne 'Info' }).Count | Should -Be 0
            @((Get-C11Grid $rows) | Where-Object { $_.Failures -match 'dcdiag\.exe not available' }).Count | Should -Be 3
        }
        It 'uses the timeout and retries the config table supplies, and otherwise the parameters' {
            Invoke-C11Collector -Targets @($script:C11ThreeDcs[0]) | Out-Null
            @($script:C11Calls | Where-Object { $_.Timeout -ne 5 -or $_.Retries -ne 1 }).Count | Should -Be 0
            $cfg = Merge-AdfaDcDiagConfig -BaseConfig $script:Config.DcDiag -Override ('{ "TestTimeoutSeconds": 240, "Retries": 3 }' | ConvertFrom-Json) -OverrideSource 'C:\cfg\dcdiag.json'
            Invoke-C11Collector -Targets @($script:C11ThreeDcs[0]) -Config $cfg | Out-Null
            @($script:C11Calls).Count | Should -BeGreaterThan 0
            @($script:C11Calls | Where-Object { $_.Timeout -ne 240 -or $_.Retries -ne 3 }).Count | Should -Be 0
        }
        It 'names the time-out and where it came from in a timed-out cell, without the file path' {
            $script:C11Answer = { param($Server, $Test)
                if ($Test -eq 'Replications') { return (New-C11Result '' -Success $false -ExitCode $null -ErrorText 'Timeout after 240s') }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $cfg = Merge-AdfaDcDiagConfig -BaseConfig $script:Config.DcDiag -Override ('{ "TestTimeoutSeconds": 240 }' | ConvertFrom-Json) -OverrideSource 'C:\Backup\replication\dcdiag.json'
            $one = (Get-C11Grid (Invoke-C11Collector -Targets @($script:C11ThreeDcs[0]) -Config $cfg))[0]
            [string]$one.DCDIAG_Replications | Should -Be 'Not Assessed'
            [string]$one.Failures | Should -Match 'did not complete'
            [string]$one.Failures | Should -Match '240 s'
            [string]$one.Failures | Should -Match 'ConfigOverridePath'
            [string]$one.Failures | Should -Not -Match 'Backup'
        }
    }

    Context 'Collector: domain, forest and site tests' {
        It 'runs Topology once per scoped domain, against a writable DC of that domain' {
            $targets = @((New-C11Target $script:C11Ro 'north.contoso.com' 'HQ' $true)) + $script:C11ThreeDcs
            $rows = Invoke-C11Collector -Targets $targets
            $topoCalls = @($script:C11Calls | Where-Object { $_.Arguments -match '^/test:Topology ' })
            # Declared population: the two scoped domains.
            $topoCalls.Count | Should -Be 2
            @(Get-C11CallsFor -Server $script:C11Ro -Test 'Topology').Count | Should -Be 0
            @(Get-C11CallsFor -Server $script:C11Dc3 -Test 'Topology').Count | Should -Be 1
            @(Get-C11CallsFor -Server $script:C11Dc1 -Test 'Topology').Count | Should -Be 1
            foreach ($d in @('contoso.com', 'north.contoso.com')) {
                $r = Get-C11Row $rows ("dcdiag Topology: {0}" -f $d)
                $r.Count | Should -Be 1 -Because $d
                [string]$r[0].Status | Should -Be 'Pass'
                [string]$r[0].Scope | Should -Be $d
            }
        }
        Context 'a domain that is not scoped, whose only DC failed Connectivity' {
            BeforeEach {
                $script:C11Answer = { param($Server, $Test)
                    if ($Server -eq $script:C11Fab -and $Test -eq 'Connectivity') { return (New-C11Result (New-C11DcOutput -Dc 'DC9' -Test 'Connectivity' -Verdict 'failed') -Success $false -ExitCode 1) }
                    Get-C11DefaultAnswer -Server $Server -Test $Test }
                $targets = @($script:C11ThreeDcs[0], $script:C11ThreeDcs[1], (New-C11Target $script:C11Fab 'fabrikam.com' 'HQ'))
                $script:C11FabRows = Invoke-C11Collector -Targets $targets -Scoped @('contoso.com')
            }
            It 'still runs Topology for the domain known from a DC''s Scope (declared population: contoso.com and fabrikam.com)' {
                $topo = @($script:C11FabRows | Where-Object { $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -like 'dcdiag Topology: *' })
                (@($topo | ForEach-Object { [string]$_.Item } | Sort-Object) -join ',') | Should -Be 'dcdiag Topology: contoso.com,dcdiag Topology: fabrikam.com'
                [string](Get-C11Row $script:C11FabRows 'dcdiag Topology: contoso.com')[0].Status | Should -Be 'Pass'
            }
            It 'never chooses the DC whose Connectivity failed, and reports the domain''s Topology Not Assessed' {
                @(Get-C11CallsFor -Server $script:C11Fab -Test 'Topology').Count | Should -Be 0
                @(Get-C11CallsFor -Server $script:C11Fab).Count | Should -Be 1   # Connectivity only
                $r = Get-C11Row $script:C11FabRows 'dcdiag Topology: fabrikam.com'
                $r.Count | Should -Be 1
                [string]$r[0].Status | Should -Be 'Not Assessed'
                [string]$r[0].Detail | Should -Match 'None of the 1 domain controller\(s\) of this domain'
            }
        }
        It 'fails a domain''s Topology row on a failed verdict and leaves the other domain and the grid alone' {
            $script:C11Answer = { param($Server, $Test)
                if ($Test -eq 'Topology' -and $Server -eq $script:C11Dc3) { return (New-C11Result (New-C11DcOutput -Dc 'DC3' -Test 'Topology' -Verdict 'failed' -Lines @('Automatic intra-site topology generation is disabled.')) -Success $false -ExitCode 1) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs
            [string](Get-C11Row $rows 'dcdiag Topology: north.contoso.com')[0].Status | Should -Be 'Fail'
            [string](Get-C11Row $rows 'dcdiag Topology: contoso.com')[0].Status | Should -Be 'Pass'
            @((Get-C11Grid $rows) | Where-Object { $_.Status -ne 'Pass' }).Count | Should -Be 0
        }
        It 'runs CheckSDRefDom and CrossRefValidation once each, against the forest root, one row per partition and a roll-up' {
            $script:C11Answer = { param($Server, $Test)
                if ($Test -eq 'CrossRefValidation') { return (New-C11Result (New-C11PartitionOutput -Dc (Get-C11Short $Server) -Test $Test -Failed @('Configuration')) -Success $false -ExitCode 1) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $rows = Invoke-C11Collector -Targets @($script:C11ThreeDcs[2], $script:C11ThreeDcs[0], $script:C11ThreeDcs[1])
            foreach ($t in @('CheckSDRefDom', 'CrossRefValidation')) {
                $calls = @($script:C11Calls | Where-Object { $_.Arguments -match ('^/test:{0} ' -f $t) })
                $calls.Count | Should -Be 1 -Because "$t runs once per forest"
                $calls[0].Arguments | Should -Match ('/s:{0}$' -f [regex]::Escape($script:C11Dc1))
                foreach ($p in $script:C11Partitions) { (Get-C11Row $rows ("dcdiag {0}: {1}" -f $t, $p)).Count | Should -Be 1 -Because "$t $p" }
            }
            [string](Get-C11Row $rows 'dcdiag CrossRefValidation: Configuration')[0].Status | Should -Be 'Fail'
            @($script:C11Partitions | Where-Object { $_ -ne 'Configuration' } | Where-Object { [string](Get-C11Row $rows ("dcdiag CrossRefValidation: {0}" -f $_))[0].Status -ne 'Pass' }).Count | Should -Be 0
            [string](Get-C11Row $rows 'dcdiag CrossRefValidation: forest contoso.com')[0].Status | Should -Be 'Fail'
            [string](Get-C11Row $rows 'dcdiag CheckSDRefDom: forest contoso.com')[0].Status | Should -Be 'Pass'
            # A partition's failure is not a DC's failure.
            @((Get-C11Grid $rows) | Where-Object { $_.Status -ne 'Pass' }).Count | Should -Be 0
        }
        It 'reports the forest tests Not Assessed when no DC could run them' {
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs -Down @($script:C11Dc1, $script:C11Dc2, $script:C11Dc3)
            foreach ($t in @('CheckSDRefDom', 'CrossRefValidation')) {
                $r = Get-C11Row $rows ("dcdiag {0}: forest contoso.com" -f $t)
                $r.Count | Should -Be 1
                [string]$r[0].Status | Should -Be 'Not Assessed'
            }
            @($script:C11Calls).Count | Should -Be 0
        }
        It 'does not run Intersite by default, and says so in one Not Assessed row with the switch in NotRun' {
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs
            @($script:C11Calls | Where-Object { $_.Arguments -match '/test:Intersite' }).Count | Should -Be 0
            $r = Get-C11Row $rows 'dcdiag Intersite: not run'
            $r.Count | Should -Be 1
            [string]$r[0].Status | Should -Be 'Not Assessed'
            [string]$r[0].NotRun | Should -Match 'IncludeDcdiagActiveTests'
            [string]$r[0].NotRun | Should -Match 'triggers a replication'
            [string]$r[0].Detail | Should -BeNullOrEmpty
        }
        It 'with the opt-in runs Intersite once per site with /a, and SystemLog and DNS on every DC' {
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs -Active
            $inter = @($script:C11Calls | Where-Object { $_.Arguments -match '^/test:Intersite ' })
            # Declared population: the two sites that hold a DC (HQ: dc1 and dc3; Branch: dc2).
            $inter.Count | Should -Be 2
            @($inter | Where-Object { $_.Arguments -notmatch '\s/a$' }).Count | Should -Be 0
            foreach ($site in @('HQ', 'Branch')) {
                $r = Get-C11Row $rows ("dcdiag Intersite: {0}" -f $site)
                $r.Count | Should -Be 1 -Because $site
                [string]$r[0].Status | Should -Be 'Pass'
            }
            foreach ($t in $script:C11ThreeDcs) {
                @(Get-C11CallsFor -Server $t.HostName | Where-Object { $_.Arguments -notmatch '/test:(Topology|CheckSDRefDom|CrossRefValidation|Intersite)\b' }).Count | Should -Be 21 -Because $t.HostName
            }
            (Get-C11Row $rows 'dcdiag Intersite: not run').Count | Should -Be 0
        }
        It 'with the opt-in reports a DC with no known site, and a site whose DCs are all unreachable, as Not Assessed' {
            $targets = @($script:C11ThreeDcs) + @((New-C11Target 'dc5.contoso.com' 'contoso.com' ''))
            $rows = Invoke-C11Collector -Targets $targets -Active -Down @($script:C11Dc2)
            [string](Get-C11Row $rows 'dcdiag Intersite: Branch')[0].Status | Should -Be 'Not Assessed'
            [string](Get-C11Row $rows 'dcdiag Intersite: site unknown')[0].Status | Should -Be 'Not Assessed'
            [string](Get-C11Row $rows 'dcdiag Intersite: site unknown')[0].Detail | Should -Match 'dc5\.contoso\.com'
            [string](Get-C11Row $rows 'dcdiag Intersite: HQ')[0].Status | Should -Be 'Pass'
        }
        It 'never runs LocatorCheck and says why in one Not Assessed row' {
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs -Active
            @($script:C11Calls | Where-Object { $_.Arguments -match 'LocatorCheck' }).Count | Should -Be 0
            $r = Get-C11Row $rows 'dcdiag LocatorCheck: not run'
            $r.Count | Should -Be 1
            [string]$r[0].Status | Should -Be 'Not Assessed'
            [string]$r[0].NotRun | Should -Match 'known-tests table'
        }
        It 'gives every scoped domain a coverage row that counts its DCs, and a Not Assessed one to a domain with none' {
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs -Scoped @('contoso.com', 'north.contoso.com', 'south.contoso.com')
            $c = Get-C11Row $rows 'dcdiag coverage: contoso.com'
            $c.Count | Should -Be 1
            [string]$c[0].Status | Should -Be 'Info'
            [string]$c[0].Detail | Should -Match '^2 domain controller\(s\)'
            [string](Get-C11Row $rows 'dcdiag coverage: north.contoso.com')[0].Detail | Should -Match '^1 domain controller\(s\)'
            [string](Get-C11Row $rows 'dcdiag coverage: south.contoso.com')[0].Status | Should -Be 'Not Assessed'
            [string](Get-C11Row $rows 'dcdiag Topology: south.contoso.com')[0].Status | Should -Be 'Not Assessed'
        }
    }

    Context 'Config override: the DcDiag key' {
        It 'is registered with its own validator' {
            $entry = $script:ConfigOverrideSections['DcDiag']
            [string]$entry['ConfigKey'] | Should -Be 'DcDiag'
            [string]$entry['Section'] | Should -Be 'DcDiagnostics'
            [string]$entry['Merge'] | Should -Be 'Merge-AdfaDcDiagConfig'
            Get-Command -Name 'Merge-AdfaDcDiagConfig' -CommandType Function -ErrorAction SilentlyContinue | Should -Not -BeNullOrEmpty
        }
        It 'accepts the two numbers, and rewrites the provenance for the keys it supplied only' {
            $m = Merge-AdfaDcDiagConfig -BaseConfig $script:Config.DcDiag -Override ('{ "TestTimeoutSeconds": 180 }' | ConvertFrom-Json) -OverrideSource 'C:\cfg\dcdiag.json'
            [int]$m['TestTimeoutSeconds'] | Should -Be 180
            $null -eq $m['Retries'] | Should -BeTrue
            [string]$m['ThresholdSource'] | Should -Match 'C:\\cfg\\dcdiag\.json'
            [string]$m['ThresholdSource'] | Should -Match 'for TestTimeoutSeconds'
            [string]$m['ThresholdSource'] | Should -Match 'tool default, not a Microsoft value, for Retries'
            # The built-in table is not changed by a merge.
            $null -eq $script:Config.DcDiag['TestTimeoutSeconds'] | Should -BeTrue
            (@($m['PerDcTests'] | ForEach-Object { [string]$_['Test'] }) -join ',') | Should -Be ($script:C11PerDc -join ',')
        }
        It 'refuses <Name>' -ForEach @(
            @{ Name = 'an array'; Json = '[ { "Retries": 2 } ]'; Expect = 'single object' }
            @{ Name = 'an empty object'; Json = '{}'; Expect = 'empty object' }
            @{ Name = 'a test list'; Json = '{ "PerDcTests": [ "CutoffServers" ] }'; Expect = "unknown key 'PerDcTests'" }
            @{ Name = 'the opt-in list'; Json = '{ "ActiveTests": [] }'; Expect = "unknown key 'ActiveTests'" }
            @{ Name = 'a pattern'; Json = '{ "UnreachablePatterns": [] }'; Expect = "unknown key 'UnreachablePatterns'" }
            @{ Name = 'a null'; Json = '{ "Retries": null }'; Expect = 'null' }
            @{ Name = 'a quoted number'; Json = '{ "TestTimeoutSeconds": "120" }'; Expect = 'JSON number' }
            @{ Name = 'a fraction'; Json = '{ "TestTimeoutSeconds": 90.5 }'; Expect = 'whole number from 5 to 600' }
            @{ Name = 'a timeout below 5'; Json = '{ "TestTimeoutSeconds": 4 }'; Expect = 'whole number from 5 to 600' }
            @{ Name = 'a timeout above 600'; Json = '{ "TestTimeoutSeconds": 601 }'; Expect = 'whole number from 5 to 600' }
            @{ Name = 'retries of 0'; Json = '{ "Retries": 0 }'; Expect = 'whole number from 1 to 10' }
            @{ Name = 'retries of 11'; Json = '{ "Retries": 11 }'; Expect = 'whole number from 1 to 10' }
            @{ Name = 'a boolean'; Json = '{ "Retries": true }'; Expect = 'JSON number' }
        ) {
            # An array is built in memory: PowerShell 7 unrolls a one-object JSON array on the pipeline
            # and 5.1 does not (Import-AdfaConfigOverride refuses it from the text on both).
            if ($Name -eq 'an array') { $obj = @([pscustomobject]@{ Retries = 2 }) }
            else { $obj = $Json | ConvertFrom-Json }
            { Merge-AdfaDcDiagConfig -BaseConfig $script:Config.DcDiag -Override $obj -OverrideSource 'x.json' } | Should -Throw -ExpectedMessage ("*{0}*" -f $Expect)
        }
        It 'is reached through the generic override and named in its refusals' {
            $r = Resolve-AdfaConfigOverride -Override ('{ "DcDiag": { "Retries": 4 } }' | ConvertFrom-Json) -BaseConfig $script:Config -Sections $script:ConfigOverrideSections -OverrideSource 'C:\cfg\all.json'
            [int]$r['DcDiag']['Retries'] | Should -Be 4
            { Resolve-AdfaConfigOverride -Override ('{ "DcDiag": { "Retries": "x" } }' | ConvertFrom-Json) -BaseConfig $script:Config -Sections $script:ConfigOverrideSections } | Should -Throw -ExpectedMessage "*section 'DcDiag'*"
        }
        It 'refuses a key written twice in the file' {
            $path = Join-Path ([IO.Path]::GetTempPath()) ("adfa_c11_{0}.json" -f [guid]::NewGuid().ToString('N'))
            try {
                Set-Content -LiteralPath $path -Value '{ "DcDiag": { "Retries": 2, "Retries": 3 } }' -Encoding UTF8
                { Import-AdfaConfigOverride -Path $path -BaseConfig $script:Config -Sections $script:ConfigOverrideSections } | Should -Throw -ExpectedMessage '*more than once*'
            }
            finally { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue }
        }
    }

    Context 'Recommendations' {
        BeforeAll {
            $script:C11Hostile = 'C:\Backup\replication\sysvol-dfsr\stale.json event 1311 on dc1 global catalog delegation time sync port 389 not reachable does not resolve NOT a pass krbtgt pdc emulator dcdiag'
        }
        It 'gives each failing scoped family its own advice, whatever its Detail says' {
            $cases = @(
                @{ Item = 'dcdiag Topology: contoso.com'; Expect = 'automatic intra-site and inter-site topology generation' }
                @{ Item = 'dcdiag CheckSDRefDom: forest contoso.com'; Expect = 'msDS-SDReferenceDomain' }
                @{ Item = 'dcdiag CheckSDRefDom: DomainDnsZones'; Expect = 'msDS-SDReferenceDomain' }
                @{ Item = 'dcdiag CrossRefValidation: Configuration'; Expect = 'nETBIOSName' }
                @{ Item = 'dcdiag Intersite: HQ'; Expect = 'Intersite Topology Generator' }
            )
            $cases.Count | Should -Be 5
            foreach ($c in $cases) {
                $rec = Get-AdfaRecommendation -Section 'DC Diagnostics' -Item $c.Item -Detail $script:C11Hostile
                $rec | Should -Match ([regex]::Escape($c.Expect)) -Because $c.Item
                $rec | Should -Not -Match 'repadmin /replsummary|dfsrmig|wbadmin|New-KrbtgtKeys|w32tm' -Because $c.Item
            }
        }
        It 'gives coverage, LocatorCheck and not-run rows no advice' {
            foreach ($item in @('dcdiag coverage: contoso.com', 'dcdiag LocatorCheck: not run', 'dcdiag Intersite: not run', 'dcdiag Intersite: site unknown')) {
                Get-AdfaRecommendation -Section 'DC Diagnostics' -Item $item -Detail $script:C11Hostile | Should -Be '' -Because $item
            }
        }
        It 'leaves the grid rows on the unscoped advice they had' {
            (Get-AdfaRecommendation -Section 'DC Diagnostics' -Item $script:C11Dc1 -Detail 'SysVolCheck: no diagnostic lines captured') | Should -Match 'dfsrmig'
            (Get-AdfaRecommendation -Section 'DC Diagnostics' -Item $script:C11Dc1 -Detail 'Advertising: no diagnostic lines captured') | Should -Match 'raw\\dcdiag_'
        }
        It 'sits ahead of the first unscoped entry' {
            $map = @($script:RecommendationMap)
            $firstUnscoped = -1
            for ($i = 0; $i -lt $map.Count; $i++) { if (-not $map[$i].ContainsKey('Section')) { $firstUnscoped = $i; break } }
            $ours = @(for ($i = 0; $i -lt $map.Count; $i++) { if ($map[$i].ContainsKey('Section') -and [string]$map[$i].Section -eq '(?i)^dc diagnostics') { $i } })
            # Declared population: four families, the seven DNS test groups (since PORT-PLAN C12) and
            # the catch-all.
            $ours.Count | Should -Be 12
            @($ours | Where-Object { $_ -gt $firstUnscoped }).Count | Should -Be 0
            $firstUnscoped | Should -BeGreaterThan 0
        }
        It 'attaches advice only to Fail and Warning rows of a collected section' {
            $script:C11Answer = { param($Server, $Test)
                if ($Test -eq 'CheckSDRefDom') { return (New-C11Result (New-C11PartitionOutput -Dc (Get-C11Short $Server) -Test $Test -Failed @('Schema')) -Success $false -ExitCode 1) }
                Get-C11DefaultAnswer -Server $Server -Test $Test }
            $rows = Invoke-C11Collector -Targets $script:C11ThreeDcs
            $findings = @($rows | ForEach-Object { ConvertTo-AdfaConsolidatedFinding -Section 'DC Diagnostics' -Row $_ -StatusColumn 'Status' })
            $findings.Count | Should -Be $rows.Count
            @($findings | Where-Object { $_.Status -match '^(Pass|Info|Not Assessed)$' -and $_.Recommendation }).Count | Should -Be 0
            $fails = @($findings | Where-Object { $_.Status -eq 'Fail' })
            $fails.Count | Should -Be 2   # the Schema part and the roll-up
            @($fails | Where-Object { $_.Recommendation -notmatch 'msDS-SDReferenceDomain' }).Count | Should -Be 0
        }
    }

    Context 'Wiring' {
        BeforeAll {
            $script:C11Ast = [System.Management.Automation.Language.Parser]::ParseFile($script:Target, [ref]$null, [ref]$null)
            $script:C11Main = @($script:C11Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'Invoke-Main' }, $true))[0]
            $script:C11Branch = @($script:C11Main.FindAll({ param($n) $n -is [System.Management.Automation.Language.IfStatementAst] -and $n.Clauses[0].Item1.Extent.Text -match "Test-SectionSelected 'DcDiagnostics'" }, $true))
            function Get-C11Function { param([string]$Name) @($script:C11Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq $Name }, $true)) }
        }
        It 'has one Invoke-Main branch that passes the scoped targets, the config, the population and the forest root' {
            $script:C11Branch.Count | Should -Be 1
            $calls = @($script:C11Branch[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq 'Get-AdfaDcDiagnostic' }, $true))
            $calls.Count | Should -Be 1
            $named = @{}
            foreach ($e in @($calls[0].CommandElements | Where-Object { $_ -is [System.Management.Automation.Language.CommandParameterAst] })) {
                $arg = ''
                if ($null -ne $e.Argument) { $arg = $e.Argument.Extent.Text }
                else {
                    $i = [array]::IndexOf(@($calls[0].CommandElements), $e)
                    $arg = $calls[0].CommandElements[$i + 1].Extent.Text
                }
                $named[$e.ParameterName] = $arg
            }
            $named['DomainControllers'] | Should -Be '$dcDiagTargets'
            $named['Config'] | Should -Be '$dcDiagConfig'
            $named['InventoryFailures'] | Should -Be '$dcDiagFailures'
            $named['ScopedDomains'] | Should -Be '$targetDomains'
            $named['ForestRoot'] | Should -Be '$rootDomain'
            $named['EnumerationError'] | Should -Be '$script:DcEnumerationError'
            $named['IncludeActiveTests'] | Should -Be '$IncludeDcdiagActiveTests'
            $assign = @($script:C11Branch[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -eq '$dcDiagTargets' }, $true))
            (@($assign | ForEach-Object { $_.Right.Extent.Text }) -join ' | ') | Should -Be '@($allDcInventory) | @($dcDiagEnumeration.Targets) | @($dcNames)'
            $cfg = @($script:C11Branch[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -eq '$dcDiagConfig' }, $true))
            (@($cfg | ForEach-Object { $_.Right.Extent.Text }) -join ' | ') | Should -Be "`$script:Config.DcDiag | `$configOverrides['DcDiag']"
            # The override is taken exactly when the file supplied the DcDiag section.
            $guard = $cfg[1].Parent
            while ($null -ne $guard -and $guard -isnot [System.Management.Automation.Language.IfStatementAst]) { $guard = $guard.Parent }
            $guard | Should -Not -BeNullOrEmpty
            $guard.Clauses[0].Item1.Extent.Text | Should -Be "`$configOverrides.ContainsKey('DcDiag')"
        }
        It 'probes through the per-run cache, and runs dcdiag only with an argument from the builder' {
            $collector = @(Get-C11Function 'Get-AdfaDcDiagnostic')
            $collector.Count | Should -Be 1
            $names = @($collector[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true) | ForEach-Object { [string]$_.GetCommandName() })
            $names | Should -Contain 'Test-AdfaDcPort'
            $names | Should -Not -Contain 'Test-TcpPort'
            $runs = @()
            foreach ($f in @('Get-AdfaDcDiagnostic', 'Invoke-AdfaDcdiagTest')) {
                $runs += @((Get-C11Function $f)[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq 'Invoke-ExternalCommand' }, $true))
            }
            # Declared population: the one dcdiag invocation, in the seam the collector calls.
            $runs.Count | Should -Be 1
            $args0 = @($runs[0].CommandElements | Where-Object { $_ -is [System.Management.Automation.Language.CommandParameterAst] -and $_.ParameterName -eq 'Arguments' })
            $args0.Count | Should -Be 1
            $i = [array]::IndexOf(@($runs[0].CommandElements), $args0[0])
            $runs[0].CommandElements[$i + 1].Extent.Text | Should -Match '^\(Get-AdfaDcdiagArgument '
        }
        It 'carries the same version in the script and the manifest: 1.31.0 (bumped by PORT-PLAN C14)' {
            [string]$script:Config.Version | Should -Be '1.31.0'
            (Import-PowerShellDataFile -Path (Join-Path $script:RepoRoot 'src/ADForestAssessment/ADForestAssessment.psd1')).ModuleVersion | Should -Be '1.31.0'
        }
        It 'documents the override key, the opt-in tests and the per-scope rows in the help and the README' {
            $help = $script:C11Ast.GetHelpContent()
            ([string]$help.Parameters['CONFIGOVERRIDEPATH'] -replace '\s+', ' ') | Should -Match 'Sixteen sections can be named'
            [string]$help.Parameters['CONFIGOVERRIDEPATH'] | Should -Match 'TestTimeoutSeconds'
            ([string]$help.Parameters['INCLUDEDCDIAGACTIVETESTS'] -replace '\s+', ' ') | Should -Match 'SystemLog'
            ([string]$help.Parameters['INCLUDEDCDIAGACTIVETESTS'] -replace '\s+', ' ') | Should -Match 'once per site'
            $readme = @(Get-Content -LiteralPath (Join-Path $script:RepoRoot 'README.md'))
            $row = @($readme | Where-Object { $_ -match '^\| Diagnostics \|' })
            $row.Count | Should -Be 1
            foreach ($word in @('Topology', 'CheckSDRefDom', 'CrossRefValidation', 'LocatorCheck', 'SystemLog', 'per partition')) { $row[0] | Should -Match $word }
        }
    }
}

Describe 'dcdiag DNS summary per test group: Auth, Basc, Forw, Del, Dyn, RReg, Ext per DC and per domain (C12)' {
    # PORT-PLAN C12 (closes H15). The DNS test's summary table, which Microsoft shows once on Learn
    # (KB 2102154, "Active Directory replication error 1722", read 2026-11-16): a header row
    # "Auth Basc Forw Del  Dyn  RReg Ext" with uneven spacing, "Domain: <fqdn>" lines, one row per DC
    # with its short name and one cell per column (PASS, FAIL, n/a), then "Enterprise DNS
    # infrastructure test results:" and the overall verdict. The header is found by its tokens, the
    # cells are mapped to the columns by order, and every test group is graded on its own.
    BeforeAll {
        $script:C12Cfg = $script:Config.DcDiag
        $script:C12Tokens = @('Auth', 'Basc', 'Forw', 'Del', 'Dyn', 'RReg', 'Ext')
        $script:C12Six = @('Auth', 'Basc', 'Forw', 'Del', 'Dyn', 'RReg')
        $script:C12Dc1 = 'dc1.contoso.com'
        $script:C12Dc2 = 'dc2.contoso.com'
        $script:C12Dc3 = 'dc3.north.contoso.com'
        $script:C12Header = 'Auth Basc Forw Del  Dyn  RReg Ext'
        $script:C12LearnUrl = 'https://learn.microsoft.com/troubleshoot/windows-server/active-directory/replication-error-1722-rpc-server-unavailable'
        # Learn's sample, line for line, with the domain names replaced by fictional ones.
        $script:C12LearnSample = @('Auth Basc Forw Del  Dyn  RReg Ext', '', 'Domain: contoso.com', 'DC1 PASS PASS FAIL PASS PASS PASS n/a  ', 'Domain: child.contoso.com  ',
            'DC2 PASS PASS n/a  n/a  n/a  PASS n/a  ', '', 'Enterprise DNS infrastructure test results:  ', 'For parent domain contoso.com and subordinate domain child:  ',
            'Forwarders or root hints are not misconfigured from parent domain to subordinate domain  ',
            'Error: Forwarders are configured from subordinate to parent domain but some of them failed DNS server tests  ', '',
            '(See DNS servers section for error details)  ', 'Delegation is configured properly from parent to subordinate domain  ',
            '......................... contoso.com failed test DNS') -join "`r`n"
        function New-C12Target { param([string]$HostName, [string]$Scope, [string]$Site = 'HQ')
            [pscustomobject]@{ HostName = $HostName; Scope = $Scope; Site = $Site; IsReadOnly = $false } }
        function Get-C12Short { param([string]$HostName) $HostName.Split('.')[0].ToUpperInvariant() }
        # One "dcdiag /test:DNS /DnsAll /s:<dc>" answer: banner, Connectivity, the server block's verdict,
        # then the enterprise block with Learn's summary table in it and the overall verdict.
        function New-C12DnsOutput {
            param([string]$Dc, [string]$Cells = 'PASS PASS PASS PASS PASS PASS n/a', [string]$Domain = 'contoso.com', [string]$Header = $script:C12Header,
                [string]$RowName = '', [switch]$NoTable, [string[]]$ExtraRows = @())
            if ($RowName -eq '') { $RowName = $Dc }
            $verdict = 'passed'
            if ($Cells -match '(?i)FAIL') { $verdict = 'failed' }
            $b = New-Object System.Collections.Generic.List[string]
            foreach ($l in @('Directory Server Diagnosis', '', 'Performing initial setup:', ("   Home Server = {0}" -f $Dc), '', 'Doing initial required tests', '',
                    ("   Testing server: Default-First-Site-Name\{0}" -f $Dc), '      Starting test: Connectivity', ("         ......................... {0} passed test Connectivity" -f $Dc),
                    '', 'Doing primary tests', '', ("   Testing server: Default-First-Site-Name\{0}" -f $Dc), '      Starting test: DNS',
                    '         DNS Tests are running and not hung. Please wait a few minutes...', ("         ......................... {0} passed test DNS" -f $Dc),
                    '', '   Running enterprise tests on : contoso.com', '      Starting test: DNS', '         Test results for domain controllers:', ("            DC: {0}" -f $Dc))) { $b.Add($l) }
            if (-not $NoTable) {
                foreach ($l in @('', '         Summary of DNS test results:', '', ("                                            {0}" -f $Header), '', ("            Domain: {0}" -f $Domain), ("               {0,-25} {1}  " -f $RowName, $Cells))) { $b.Add($l) }
                foreach ($r in $ExtraRows) { $b.Add(("               {0}" -f $r)) }
                foreach ($l in @('', '         Enterprise DNS infrastructure test results:')) { $b.Add($l) }
            }
            $b.Add(("         ......................... contoso.com {0} test DNS" -f $verdict))
            return ($b -join "`r`n")
        }
        function New-C12Result { param([string]$StdOut, [bool]$Success = $true, $ExitCode = 0, $ErrorText = $null)
            [pscustomobject]@{ Success = $Success; ExitCode = $ExitCode; Attempt = 1; Error = $ErrorText; StdOut = $StdOut; OutFile = $null } }
        function Get-C12DefaultAnswer { param([string]$Server, [string]$Test)
            $short = Get-C12Short $Server
            if ($Test -eq 'DNS') { return (New-C12Result (New-C12DnsOutput -Dc $short)) }
            return (New-C12Result ("Directory Server Diagnosis`r`n   Testing server: Default-First-Site-Name\{0}`r`n      Starting test: {1}`r`n         ......................... {0} passed test {1}" -f $short, $Test))
        }
        function Invoke-C12Collector {
            param([object[]]$Targets, [switch]$Active, [string[]]$Scoped = @('contoso.com', 'north.contoso.com'), [string[]]$Down = @(), [bool]$HaveDcdiag = $true,
                [hashtable]$Config = $script:Config.DcDiag)
            $script:C12Calls = @()
            $script:C12Down = @($Down)
            $script:C12Have = $HaveDcdiag
            Clear-AdfaDcPortCache
            Mock Test-CommandAvailable { [bool]$script:C12Have }
            Mock Test-TcpPort { $script:C12Down -notcontains [string]$ComputerName }
            Mock Invoke-ExternalCommand {
                $script:C12Calls += [string]$Arguments
                $t = ([regex]::Match([string]$Arguments, '/test:(\S+)')).Groups[1].Value
                $s = ([regex]::Match([string]$Arguments, '/s:(\S+)')).Groups[1].Value
                & $script:C12Answer $s $t
            }
            return @(Get-AdfaDcDiagnostic -DomainControllers $Targets -IncludeActiveTests:$Active -TimeoutSeconds 5 -Retries 1 -RetryDelaySeconds 0 `
                    -Config $Config -ScopedDomains $Scoped -ForestRoot 'contoso.com')
        }
        # The comma keeps a one-row answer an array, so .Count works under StrictMode on Windows PowerShell 5.1.
        function Get-C12Row { param($Rows, [string]$Item) return , @($Rows | Where-Object { $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -eq $Item }) }
        function Get-C12DnsRows { param($Rows) return , @($Rows | Where-Object { $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -like 'dcdiag DNS *' }) }
        function Get-C12DcRows { param($Rows, [string]$HostName)
            return , @($Rows | Where-Object { $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -match ('^dcdiag DNS (Auth|Basc|Forw|Del|Dyn|RReg|Ext): {0}$' -f [regex]::Escape($HostName)) }) }
        function Resolve-C12 {
            param([string]$Out, [string]$Token, [string]$HostName = $script:C12Dc1, [string]$NotRunCause = '', [string]$RunCause = '', [string]$OverallStatus = '', [string]$OverallEvidence = '')
            $s = ConvertFrom-AdfaDcdiagDnsSummary -StdOut $Out -Config $script:C12Cfg
            Resolve-AdfaDcdiagDnsCategory -Summary $s -HostName $HostName -Token $Token -Config $script:C12Cfg -NotRunCause $NotRunCause -RunCause $RunCause `
                -OverallStatus $OverallStatus -OverallEvidence $OverallEvidence
        }
        $script:C12ThreeDcs = @((New-C12Target $script:C12Dc1 'contoso.com' 'HQ'), (New-C12Target $script:C12Dc2 'contoso.com' 'Branch'), (New-C12Target $script:C12Dc3 'north.contoso.com' 'HQ'))
        $script:C12Hostile = 'replication stale delegation secure dynamic zone transfer scavenging aging no a record does not resolve port 389 not reachable time sync w32tm dcdiag NOT a pass log coverage C:\Backup\stale.json'
    }
    BeforeEach {
        $script:C12Answer = { param($Server, $Test) Get-C12DefaultAnswer -Server $Server -Test $Test }
    }

    Context 'Config table (Learn, read 2026-11-16)' {
        It 'declares the seven test groups in Learn''s column order, each with its Learn name, and flags Ext as not named on Learn' {
            $ds = $script:C12Cfg['DnsSummary']
            $ds | Should -Not -BeNullOrEmpty
            $cats = @($ds['Categories'])
            # Declared population: the seven columns of Learn's sample header.
            (@($cats | ForEach-Object { [string]$_['Token'] }) -join ',') | Should -Be ($script:C12Tokens -join ',')
            foreach ($c in $cats) { [string]$c['Name'] | Should -Not -BeNullOrEmpty -Because ([string]$c['Token']) }
            (@($cats | Where-Object { -not $_['InLearn'] } | ForEach-Object { [string]$_['Token'] }) -join ',') | Should -Be 'Ext'
            [string]$ds['SourceUrl'] | Should -Be $script:C12LearnUrl
            [string]$ds['ReadDate'] | Should -Be '2026-11-16'
            [string]$script:C12Cfg['Version'] | Should -Be '1.29.0'
        }
        It 'maps PASS, FAIL and n/a as Learn shows them, and WARN from Learn''s prose, marked provisional' {
            $cells = @($script:C12Cfg['DnsSummary']['Cells'])
            # Declared population: the four cell values this build reads.
            (@($cells | ForEach-Object { "{0}={1}" -f $_['Token'], $_['Status'] }) -join ',') | Should -Be 'PASS=Pass,FAIL=Fail,WARN=Warning,n/a=Not Assessed'
            @($cells | Where-Object { $_['Provisional'] } | ForEach-Object { [string]$_['Token'] }) | Should -Be @('WARN')
        }
        It 'grades n/a Info only under Ext, and Not Assessed under the other six (the catalogue''s fail-closed rule)' {
            $cats = @($script:C12Cfg['DnsSummary']['Cells'])
            $cats.Count | Should -Be 4
            $byToken = @{}
            foreach ($c in @($script:C12Cfg['DnsSummary']['Categories'])) { $byToken[[string]$c['Token']] = $c }
            [string]$byToken['Ext']['NaStatus'] | Should -Be 'Info'
            foreach ($t in $script:C12Six) { $byToken[$t].ContainsKey('NaStatus') | Should -BeFalse -Because $t }
        }
        It 'needs at least four header tokens, a tool default it says is not a Microsoft value' {
            [int]$script:C12Cfg['DnsSummary']['HeaderMinTokens'] | Should -Be 4
            [string]$script:C12Cfg['DnsSummary']['HeaderMinTokensSource'] | Should -Match 'tool default, not a Microsoft value'
        }
        It 'adds no dcdiag switch: the DNS test is still asked with /DnsAll and /s: only, never /x, /v, /e, /fix or /DnsResolveExtName' {
            $a = Get-AdfaDcdiagArgument -TestName 'DNS' -DomainController $script:C12Dc1
            $a | Should -Be ('/test:DNS /DnsAll /s:{0}' -f $script:C12Dc1)
            $a | Should -Not -Match '(?i)/(x|v|e|fix|DnsResolveExtName)(:|\s|$)'
            # And it stays opt-in.
            @($script:Config.DcdiagActiveTests | Where-Object { $_.Test -eq 'DNS' }).Count | Should -Be 1
        }
    }

    Context 'Parser: ConvertFrom-AdfaDcdiagDnsSummary' {
        It 'reads Learn''s sample: the header by its tokens, two rows under their Domain lines, cells mapped by order' {
            $s = ConvertFrom-AdfaDcdiagDnsSummary -StdOut $script:C12LearnSample -Config $script:C12Cfg
            $s.HeaderFound | Should -BeTrue
            (@($s.Columns) -join ',') | Should -Be ($script:C12Tokens -join ',')
            $rows = @($s.Rows)
            # Declared population: the two DC rows of the sample.
            $rows.Count | Should -Be 2
            $rows[0].Name | Should -Be 'DC1'
            $rows[0].Domain | Should -Be 'contoso.com'
            (@($rows[0].Cells) -join ',') | Should -Be 'PASS,PASS,FAIL,PASS,PASS,PASS,n/a'
            $rows[0].Recognised | Should -BeTrue
            $rows[1].Name | Should -Be 'DC2'
            $rows[1].Domain | Should -Be 'child.contoso.com'
            (@($rows[1].Cells) -join ',') | Should -Be 'PASS,PASS,n/a,n/a,n/a,PASS,n/a'
        }
        It 'reads the same table from LF and CRLF output' {
            $lf = ConvertFrom-AdfaDcdiagDnsSummary -StdOut ($script:C12LearnSample -replace "`r`n", "`n") -Config $script:C12Cfg
            $crlf = ConvertFrom-AdfaDcdiagDnsSummary -StdOut $script:C12LearnSample -Config $script:C12Cfg
            @($lf.Rows).Count | Should -Be 2
            (@($lf.Rows | ForEach-Object { @($_.Cells) -join ' ' }) -join '|') | Should -Be (@($crlf.Rows | ForEach-Object { @($_.Cells) -join ' ' }) -join '|')
        }
        It 'finds a header with four of the tokens, in any case, but not one with three, nor one with an unknown token' {
            (ConvertFrom-AdfaDcdiagDnsSummary -StdOut "Auth Basc Forw Del`r`nDC1 PASS PASS PASS PASS" -Config $script:C12Cfg).HeaderFound | Should -BeTrue
            (ConvertFrom-AdfaDcdiagDnsSummary -StdOut "auth BASC forw del dyn rreg ext`r`nDC1 PASS PASS PASS PASS PASS PASS n/a" -Config $script:C12Cfg).HeaderFound | Should -BeTrue
            (ConvertFrom-AdfaDcdiagDnsSummary -StdOut "Auth Basc Forw`r`nDC1 PASS PASS PASS" -Config $script:C12Cfg).HeaderFound | Should -BeFalse
            (ConvertFrom-AdfaDcdiagDnsSummary -StdOut "Auth Basc Forw Del Dyn RReg Dele`r`nDC1 PASS PASS PASS PASS PASS PASS n/a" -Config $script:C12Cfg).HeaderFound | Should -BeFalse
            (ConvertFrom-AdfaDcdiagDnsSummary -StdOut "Auth Basc Auth Basc`r`nDC1 PASS PASS PASS PASS" -Config $script:C12Cfg).HeaderFound | Should -BeFalse
        }
        It 'stops at the enterprise block and at the verdict line, and skips separator lines' {
            $out = "Auth Basc Forw Del Dyn RReg Ext`r`n_______________________________`r`nDomain: contoso.com`r`nDC1 PASS PASS PASS PASS PASS PASS n/a`r`nEnterprise DNS infrastructure test results:`r`nDC2 FAIL FAIL FAIL FAIL FAIL FAIL FAIL"
            $s = ConvertFrom-AdfaDcdiagDnsSummary -StdOut $out -Config $script:C12Cfg
            (@($s.Rows | ForEach-Object { $_.Name }) -join ',') | Should -Be 'DC1'
            $v = ConvertFrom-AdfaDcdiagDnsSummary -StdOut "Auth Basc Forw Del Dyn RReg Ext`r`nDC1 PASS PASS PASS PASS PASS PASS n/a`r`n......................... contoso.com passed test DNS`r`nDC2 FAIL FAIL FAIL FAIL FAIL FAIL FAIL" -Config $script:C12Cfg
            (@($v.Rows | ForEach-Object { $_.Name }) -join ',') | Should -Be 'DC1'
        }
        It 'reads the LAST header in the output, so a later table replaces an earlier one' {
            # Found by an independent review of the diff: no test had two header lines.
            $out = "Auth Basc Forw Del Dyn RReg Ext`r`nDC1 FAIL FAIL FAIL FAIL FAIL FAIL FAIL`r`nEnterprise DNS infrastructure test results:`r`nAuth Basc Forw Del Dyn RReg Ext`r`nDC1 PASS PASS PASS PASS PASS PASS n/a"
            $s = ConvertFrom-AdfaDcdiagDnsSummary -StdOut $out -Config $script:C12Cfg
            $s.HeaderCount | Should -Be 2
            # Declared population: the one DC row of the second table.
            @($s.Rows).Count | Should -Be 1
            (@(@($s.Rows)[0].Cells) -join ',') | Should -Be 'PASS,PASS,PASS,PASS,PASS,PASS,n/a'
            (Resolve-C12 $out 'Auth').Status | Should -Be 'Pass'
        }
        It 'stops at a block header: <Name>' -ForEach @(
            @{ Name = 'server'; Line = 'Testing server: Default-First-Site-Name\DC2' }
            @{ Name = 'partition'; Line = 'Running partition tests on : DomainDnsZones' }
            @{ Name = 'enterprise'; Line = 'Running enterprise tests on : contoso.com' }
        ) {
            # Found by an independent review of the diff: only the enterprise end-marker and a verdict
            # line were pinned. A row from the next block must never be read as this table's.
            $s = ConvertFrom-AdfaDcdiagDnsSummary -StdOut ("Auth Basc Forw Del Dyn RReg Ext`r`nDC1 PASS PASS PASS PASS PASS PASS n/a`r`n{0}`r`nDC2 FAIL FAIL FAIL FAIL FAIL FAIL FAIL" -f $Line) -Config $script:C12Cfg
            # Declared population: DC1, the one row above the block header.
            (@($s.Rows | ForEach-Object { $_.Name }) -join ',') | Should -Be 'DC1'
        }
        It 'marks a row whose cell count is not the header''s as not recognised' {
            $s = ConvertFrom-AdfaDcdiagDnsSummary -StdOut "Auth Basc Forw Del Dyn RReg Ext`r`nDC1 PASS PASS PASS PASS PASS PASS`r`nDC2 PASS PASS PASS PASS PASS PASS n/a extra" -Config $script:C12Cfg
            @($s.Rows).Count | Should -Be 2
            @($s.Rows | Where-Object { $_.Recognised }).Count | Should -Be 0
        }
        It 'finds nothing in empty, banner-only or localised output' {
            foreach ($o in @('', "Directory Server Diagnosis`r`nPerforming initial setup:", "Resumo dos resultados do teste de DNS:`r`nAutent Basico Reencam Deleg Din RReg Ext`r`nDC1 APROV APROV APROV APROV APROV APROV n/d")) {
                $s = ConvertFrom-AdfaDcdiagDnsSummary -StdOut $o -Config $script:C12Cfg
                $s.HeaderFound | Should -BeFalse
                @($s.Rows).Count | Should -Be 0
            }
        }
    }

    Context 'Verdict: Resolve-AdfaDcdiagDnsCategory (pure)' {
        It 'grades PASS as Pass, FAIL as Fail and WARN as Warning, each in its own column' {
            $out = New-C12DnsOutput -Dc 'DC1' -Cells 'PASS FAIL WARN Warn fail pass n/a'
            $expect = @('Pass', 'Fail', 'Warning', 'Warning', 'Fail', 'Pass')
            for ($i = 0; $i -lt 6; $i++) {
                $r = Resolve-C12 $out $script:C12Six[$i]
                [string]$r.Status | Should -Be $expect[$i] -Because $script:C12Six[$i]
                [string]$r.Evidence | Should -Match 'Auth Basc Forw Del Dyn RReg Ext'
                [string]$r.Evidence | Should -Match 'DC1 PASS FAIL WARN Warn fail pass n/a'
            }
            (Resolve-C12 $out 'Basc').Detail | Should -Match 'Forwarders|network connectivity'
        }
        It 'grades n/a under Ext as Info, not requested by /DnsAll - never Pass' {
            $r = Resolve-C12 (New-C12DnsOutput -Dc 'DC1') 'Ext'
            $r.Status | Should -Be 'Info'
            $r.Detail | Should -Match 'DnsResolveExtName'
            $r.Detail | Should -Match 'not requested'
        }
        It 'grades n/a under each of the six other groups Not Assessed, saying Microsoft does not publish what n/a means' {
            $out = New-C12DnsOutput -Dc 'DC1' -Cells 'n/a n/a n/a n/a n/a n/a n/a'
            # Declared population: the six groups other than Ext.
            $graded = @(foreach ($t in $script:C12Six) { Resolve-C12 $out $t })
            $graded.Count | Should -Be 6
            @($graded | Where-Object { [string]$_.Status -ne 'Not Assessed' }).Count | Should -Be 0
            foreach ($g in $graded) { [string]$g.Detail | Should -Match 'does not publish what n/a means' }
        }
        It 'grades the DC''s own row only, by its short name or its 15-character NetBIOS form' {
            $out = New-C12DnsOutput -Dc 'DC2' -Cells 'PASS PASS PASS FAIL PASS PASS n/a'
            (Resolve-C12 $out 'Del' $script:C12Dc2).Status | Should -Be 'Fail'
            $other = Resolve-C12 $out 'Del' $script:C12Dc1
            $other.Status | Should -Be 'Not Assessed'
            $other.Detail | Should -Match 'no row for this domain controller'
            $long = 'maplewaffle-ws22.contoso.com'
            (Resolve-C12 (New-C12DnsOutput -Dc 'MAPLEWAFFLE-WS2' -Cells 'PASS PASS PASS PASS FAIL PASS n/a') 'Dyn' $long).Status | Should -Be 'Fail'
        }
        It 'reads Not Assessed, never Pass, for a missing row, two rows for one DC, an absent column, a short row or an unknown cell' {
            $two = Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -ExtraRows @('DC1 PASS PASS PASS PASS PASS PASS n/a')) 'Auth'
            $two.Status | Should -Be 'Not Assessed'
            $two.Detail | Should -Match '2 rows'
            $noExt = Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -Header 'Auth Basc Forw Del Dyn RReg' -Cells 'PASS PASS PASS PASS PASS PASS') 'Ext'
            $noExt.Status | Should -Be 'Not Assessed'
            $noExt.Detail | Should -Match 'no Ext column'
            (Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -Header 'Auth Basc Forw Del Dyn RReg' -Cells 'PASS PASS PASS PASS PASS PASS') 'RReg').Status | Should -Be 'Pass'
            $short = Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -Cells 'PASS PASS PASS PASS PASS PASS') 'Auth'
            $short.Status | Should -Be 'Not Assessed'
            $short.Detail | Should -Match 'row not recognised'
            $odd = Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -Cells 'PASS OK PASS PASS PASS PASS n/a') 'Basc'
            $odd.Status | Should -Be 'Not Assessed'
            $odd.Detail | Should -Match "cell value 'OK'"
            (Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -Cells 'PASS OK PASS PASS PASS PASS n/a') 'Auth').Status | Should -Be 'Pass'
        }
        It 'puts a cause that stopped the test ahead of any table, and passes no table it was not given' {
            $r = Resolve-C12 (New-C12DnsOutput -Dc 'DC1') 'Auth' -NotRunCause 'DC not reachable on RPC/135, so the DNS test was not run.'
            $r.Status | Should -Be 'Not Assessed'
            $r.Detail | Should -Match 'RPC/135'
            $none = Resolve-AdfaDcdiagDnsCategory -Summary $null -HostName $script:C12Dc1 -Token 'Auth' -Config $script:C12Cfg
            $none.Status | Should -Be 'Not Assessed'
        }
        It 'without a table, carries the run''s own cause, or says the overall verdict grades no group' {
            $cause = Resolve-C12 'Diagnostico do Servidor de Diretorio' 'Dyn' -RunCause 'DNS: NOT ASSESSED - the dcdiag output was not recognised (possibly a localised, non-English Windows)'
            $cause.Status | Should -Be 'Not Assessed'
            $cause.Detail | Should -Match 'no DNS summary table'
            $cause.Detail | Should -Match 'localised'
            $overall = Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -NoTable) 'Del' -OverallStatus 'Pass' -OverallEvidence 'DC1 passed test DNS'
            $overall.Status | Should -Be 'Not Assessed'
            $overall.Detail | Should -Match 'overall verdict'
            $overall.Detail | Should -Match 'DC1 passed test DNS'
        }
        It 'keeps every group Not Assessed when the overall verdict is Fail and there is no table' {
            # Found by an independent review of the diff: only an overall Pass was pinned.
            $graded = @(foreach ($t in $script:C12Tokens) { Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -NoTable) $t -OverallStatus 'Fail' -OverallEvidence 'contoso.com failed test DNS' })
            # Declared population: the seven groups.
            $graded.Count | Should -Be 7
            @($graded | Where-Object { [string]$_.Status -ne 'Not Assessed' }).Count | Should -Be 0
            foreach ($g in $graded) { [string]$g.Detail | Should -Match 'overall verdict for its DNS test on this domain controller was Fail' }
        }
        It 'grades Ext PASS, WARN and FAIL as catalogue DNSDIAG-007 says, with the proxy caveat on WARN and FAIL only' {
            # Found by an independent review of the diff: only n/a was ever fed under Ext.
            $fail = Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -Cells 'PASS PASS PASS PASS PASS PASS FAIL') 'Ext'
            $fail.Status | Should -Be 'Fail'
            $fail.Detail | Should -Match 'proxy server'
            $warn = Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -Cells 'PASS PASS PASS PASS PASS PASS WARN') 'Ext'
            $warn.Status | Should -Be 'Warning'
            $warn.Detail | Should -Match 'proxy server'
            $warn.Detail | Should -Match 'currently functional'
            $pass = Resolve-C12 (New-C12DnsOutput -Dc 'DC1' -Cells 'PASS PASS PASS PASS PASS PASS PASS') 'Ext'
            $pass.Status | Should -Be 'Pass'
            $pass.Detail | Should -Not -Match 'proxy server'
        }
        It 'adds the functional-warnings caveat to a WARN in any group, and the proxy caveat to no group but Ext' {
            $out = New-C12DnsOutput -Dc 'DC1' -Cells 'WARN FAIL PASS PASS PASS PASS n/a'
            $authWarn = Resolve-C12 $out 'Auth'
            $authWarn.Status | Should -Be 'Warning'
            $authWarn.Detail | Should -Match 'currently functional'
            $authWarn.Detail | Should -Not -Match 'proxy server'
            $bascFail = Resolve-C12 $out 'Basc'
            $bascFail.Status | Should -Be 'Fail'
            $bascFail.Detail | Should -Not -Match 'proxy server|currently functional'
        }
        It 'refuses a config cell map to a status this tool does not report: Not Assessed, never passed through' {
            # Found by an independent review of the diff: the allow-list was never exercised.
            $cfg = @{}
            foreach ($k in $script:C12Cfg.Keys) { $cfg[$k] = $script:C12Cfg[$k] }
            $ds = @{}
            foreach ($k in $script:C12Cfg['DnsSummary'].Keys) { $ds[$k] = $script:C12Cfg['DnsSummary'][$k] }
            $ds['Cells'] = @(@{ Token = 'PASS'; Status = 'Healthy'; Provisional = $false })
            $cfg['DnsSummary'] = $ds
            $s = ConvertFrom-AdfaDcdiagDnsSummary -StdOut (New-C12DnsOutput -Dc 'DC1') -Config $cfg
            $r = Resolve-AdfaDcdiagDnsCategory -Summary $s -HostName $script:C12Dc1 -Token 'Auth' -Config $cfg
            $r.Status | Should -Be 'Not Assessed'
            $r.Detail | Should -Match 'not a status this tool reports'
        }
    }

    Context 'Roll-up: Resolve-AdfaDcdiagDnsRollup (pure)' {
        BeforeAll {
            function New-C12Cell { param([string]$HostName, [string]$Status) [pscustomobject]@{ HostName = $HostName; Status = $Status } }
        }
        It 'is Fail when any DC failed, then Warning, then Not Assessed, then Pass, then Info' {
            $p = New-C12Cell $script:C12Dc1 'Pass'
            $w = New-C12Cell $script:C12Dc2 'Warning'
            $f = New-C12Cell 'dc4.contoso.com' 'Fail'
            $n = New-C12Cell 'dc5.contoso.com' 'Not Assessed'
            $i = New-C12Cell 'dc6.contoso.com' 'Info'
            (Resolve-AdfaDcdiagDnsRollup -Cells @($p, $w, $f, $n, $i) -Token 'Del').Status | Should -Be 'Fail'
            (Resolve-AdfaDcdiagDnsRollup -Cells @($p, $w, $n, $i) -Token 'Del').Status | Should -Be 'Warning'
            (Resolve-AdfaDcdiagDnsRollup -Cells @($p, $n, $i) -Token 'Del').Status | Should -Be 'Not Assessed'
            (Resolve-AdfaDcdiagDnsRollup -Cells @($p, $i) -Token 'Del').Status | Should -Be 'Pass'
            (Resolve-AdfaDcdiagDnsRollup -Cells @($i, (New-C12Cell 'dc7.contoso.com' 'Info')) -Token 'Ext').Status | Should -Be 'Info'
        }
        It 'counts every DC of the declared population, names the ones not assessed, and is Not Assessed with none' {
            $r = Resolve-AdfaDcdiagDnsRollup -Cells @((New-C12Cell $script:C12Dc1 'Pass'), (New-C12Cell $script:C12Dc2 'Not Assessed')) -Token 'Auth'
            $r.Status | Should -Be 'Not Assessed'
            $r.Detail | Should -Match '^2 domain controller\(s\) of this domain'
            $r.Detail | Should -Match '1 Pass, 0 Warning, 0 Fail, 1 Not Assessed, 0 Info'
            $r.Detail | Should -Match ([regex]::Escape($script:C12Dc2))
            $empty = Resolve-AdfaDcdiagDnsRollup -Cells @() -Token 'Auth'
            $empty.Status | Should -Be 'Not Assessed'
        }
        It 'is Not Assessed, never Info or Pass, when a DC''s status is one it does not read: <Name>' -ForEach @(
            @{ Name = 'an unknown status'; Value = 'Bogus' }
            @{ Name = 'an empty status'; Value = '' }
            @{ Name = 'a null status'; Value = $null }
        ) {
            # Found by an independent review of the diff: such a cell was counted nowhere and the
            # roll-up fell through to Info.
            $odd = [pscustomobject]@{ HostName = 'dc8.contoso.com'; Status = $Value }
            $alone = Resolve-AdfaDcdiagDnsRollup -Cells @($odd) -Token 'Auth'
            $alone.Status | Should -Be 'Not Assessed'
            $alone.Detail | Should -Match '^1 domain controller\(s\)'
            $alone.Detail | Should -Match '1 with a status this roll-up does not read'
            $alone.Detail | Should -Match 'dc8\.contoso\.com'
            (Resolve-AdfaDcdiagDnsRollup -Cells @((New-C12Cell $script:C12Dc1 'Pass'), $odd) -Token 'Auth').Status | Should -Be 'Not Assessed'
            (Resolve-AdfaDcdiagDnsRollup -Cells @((New-C12Cell $script:C12Dc1 'Info'), $odd) -Token 'Ext').Status | Should -Be 'Not Assessed'
            # A measured failure still outranks it.
            (Resolve-AdfaDcdiagDnsRollup -Cells @((New-C12Cell $script:C12Dc1 'Fail'), $odd) -Token 'Auth').Status | Should -Be 'Fail'
        }
    }

    Context 'Collector: with -IncludeDcdiagActiveTests' {
        It 'gives every DC seven rows from its own table, and every domain seven roll-ups (declared population: three DCs, two domains)' {
            $script:C12Answer = { param($Server, $Test)
                if ($Test -eq 'DNS') {
                    $short = Get-C12Short $Server
                    $cells = 'PASS PASS PASS PASS PASS PASS n/a'
                    if ($Server -eq $script:C12Dc2) { $cells = 'PASS PASS PASS FAIL PASS PASS n/a' }
                    if ($Server -eq $script:C12Dc3) { $cells = 'PASS PASS PASS PASS WARN PASS n/a' }
                    return (New-C12Result (New-C12DnsOutput -Dc $short -Cells $cells))
                }
                Get-C12DefaultAnswer -Server $Server -Test $Test }
            $rows = Invoke-C12Collector -Targets $script:C12ThreeDcs -Active
            # No new dcdiag invocation: one DNS run per DC, with the C11 arguments.
            $dnsCalls = @($script:C12Calls | Where-Object { $_ -match '/test:DNS' })
            $dnsCalls.Count | Should -Be 3
            foreach ($t in $script:C12ThreeDcs) {
                @($dnsCalls | Where-Object { $_ -eq ('/test:DNS /DnsAll /s:{0}' -f $t.HostName) }).Count | Should -Be 1 -Because $t.HostName
                $mine = Get-C12DcRows $rows $t.HostName
                $mine.Count | Should -Be 7 -Because $t.HostName
                @($mine | Where-Object { [string]$_.Scope -ne $t.Scope -or [string]$_.Target -ne $t.HostName -or [string]$_.Area -ne 'DcDiagnostics' }).Count | Should -Be 0 -Because $t.HostName
                [string](Get-C12Row $rows ("dcdiag DNS Ext: {0}" -f $t.HostName))[0].Status | Should -Be 'Info' -Because $t.HostName
            }
            [string](Get-C12Row $rows ("dcdiag DNS Del: {0}" -f $script:C12Dc2))[0].Status | Should -Be 'Fail'
            [string](Get-C12Row $rows ("dcdiag DNS Dyn: {0}" -f $script:C12Dc3))[0].Status | Should -Be 'Warning'
            [string](Get-C12Row $rows ("dcdiag DNS Del: {0}" -f $script:C12Dc1))[0].Status | Should -Be 'Pass'
            [string](Get-C12Row $rows ("dcdiag DNS Dyn: {0}" -f $script:C12Dc1))[0].Status | Should -Be 'Pass'
            [string](Get-C12Row $rows ("dcdiag DNS Del: {0}" -f $script:C12Dc3))[0].Status | Should -Be 'Pass'
            # Roll-ups: seven per domain.
            foreach ($d in @('contoso.com', 'north.contoso.com')) {
                $roll = @($rows | Where-Object { $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -match ('^dcdiag DNS (Auth|Basc|Forw|Del|Dyn|RReg|Ext): domain {0}$' -f [regex]::Escape($d)) })
                $roll.Count | Should -Be 7 -Because $d
                @($roll | Where-Object { [string]$_.Scope -ne $d }).Count | Should -Be 0 -Because $d
            }
            [string](Get-C12Row $rows 'dcdiag DNS Del: domain contoso.com')[0].Status | Should -Be 'Fail'
            [string](Get-C12Row $rows 'dcdiag DNS Del: domain contoso.com')[0].Detail | Should -Match '^2 domain controller\(s\)'
            [string](Get-C12Row $rows 'dcdiag DNS Dyn: domain contoso.com')[0].Status | Should -Be 'Pass'
            [string](Get-C12Row $rows 'dcdiag DNS Dyn: domain north.contoso.com')[0].Status | Should -Be 'Warning'
            [string](Get-C12Row $rows 'dcdiag DNS Del: domain north.contoso.com')[0].Status | Should -Be 'Pass'
            [string](Get-C12Row $rows 'dcdiag DNS Ext: domain contoso.com')[0].Status | Should -Be 'Info'
            (Get-C12Row $rows 'dcdiag DNS not run: contoso.com').Count | Should -Be 0
            # The grid's DNS cell is still C11's overall verdict.
            [string]@($rows | Where-Object { $null -ne $_.PSObject.Properties['DomainController'] -and $_.DomainController -eq $script:C12Dc2 })[0].DCDIAG_DNS | Should -Be 'Fail'
        }
        It 'reads a DC closed on RPC/135 as unreachable in all seven rows, and its domain''s roll-ups Not Assessed' {
            $rows = Invoke-C12Collector -Targets $script:C12ThreeDcs -Active -Down @($script:C12Dc3)
            $three = Get-C12DcRows $rows $script:C12Dc3
            $three.Count | Should -Be 7
            @($three | Where-Object { [string]$_.Status -ne 'Not Assessed' -or [string]$_.Detail -notmatch 'RPC/135' }).Count | Should -Be 0
            @($script:C12Calls | Where-Object { $_ -match ('/s:{0}$' -f [regex]::Escape($script:C12Dc3)) }).Count | Should -Be 0
            foreach ($t in $script:C12Six) { [string](Get-C12Row $rows ("dcdiag DNS {0}: domain north.contoso.com" -f $t))[0].Status | Should -Be 'Not Assessed' -Because $t }
            foreach ($t in $script:C12Six) { [string](Get-C12Row $rows ("dcdiag DNS {0}: {1}" -f $t, $script:C12Dc1))[0].Status | Should -Be 'Pass' -Because $t }
        }
        It 'reports access denied as its own cause, not as unreachable' {
            $script:C12Answer = { param($Server, $Test)
                if ($Server -eq $script:C12Dc2 -and $Test -eq 'DNS') { return (New-C12Result ("Directory Server Diagnosis`r`nPerforming initial setup:`r`n[DC2] LDAP bind failed with error 5,`r`nAccess is denied.") -Success $false -ExitCode 1) }
                Get-C12DefaultAnswer -Server $Server -Test $Test }
            $rows = Invoke-C12Collector -Targets $script:C12ThreeDcs -Active
            $two = Get-C12DcRows $rows $script:C12Dc2
            $two.Count | Should -Be 7
            foreach ($r in $two) {
                [string]$r.Status | Should -Be 'Not Assessed'
                [string]$r.Detail | Should -Match 'access denied'
                [string]$r.Detail | Should -Not -Match 'RPC/135|could not reach'
            }
            [string](Get-C12Row $rows 'dcdiag DNS Auth: domain contoso.com')[0].Status | Should -Be 'Not Assessed'
        }
        It 'names a time-out, a localised output and a failed Connectivity as three more causes' {
            $script:C12Answer = { param($Server, $Test)
                if ($Server -eq $script:C12Dc1 -and $Test -eq 'DNS') { return (New-C12Result '' -Success $false -ExitCode $null -ErrorText 'Timeout after 5s') }
                if ($Server -eq $script:C12Dc2 -and $Test -eq 'DNS') { return (New-C12Result "Diagnostico do Servidor de Diretorio`r`n......................... DC2 passou no teste DNS") }
                if ($Server -eq $script:C12Dc3 -and $Test -eq 'Connectivity') { return (New-C12Result "   Testing server: Default-First-Site-Name\DC3`r`n      Starting test: Connectivity`r`n         ......................... DC3 failed test Connectivity" -Success $false -ExitCode 1) }
                Get-C12DefaultAnswer -Server $Server -Test $Test }
            $rows = Invoke-C12Collector -Targets $script:C12ThreeDcs -Active
            $one = Get-C12DcRows $rows $script:C12Dc1
            @($one | Where-Object { [string]$_.Status -ne 'Not Assessed' -or [string]$_.Detail -notmatch 'did not complete' -or [string]$_.Detail -notmatch 'time-out' }).Count | Should -Be 0
            $two = Get-C12DcRows $rows $script:C12Dc2
            @($two | Where-Object { [string]$_.Status -ne 'Not Assessed' -or [string]$_.Detail -notmatch 'not recognised' }).Count | Should -Be 0
            $three = Get-C12DcRows $rows $script:C12Dc3
            @($three | Where-Object { [string]$_.Status -ne 'Not Assessed' -or [string]$_.Detail -notmatch 'Connectivity' }).Count | Should -Be 0
            @($script:C12Calls | Where-Object { $_ -match ('^/test:DNS .*/s:{0}$' -f [regex]::Escape($script:C12Dc3)) }).Count | Should -Be 0
            # Declared population: 21 rows, three DCs, none Pass.
            @($one + $two + $three).Count | Should -Be 21
        }
        It 'reports dcdiag.exe missing in every row and runs nothing' {
            $rows = Invoke-C12Collector -Targets $script:C12ThreeDcs -Active -HaveDcdiag $false
            @($script:C12Calls).Count | Should -Be 0
            $dns = Get-C12DnsRows $rows
            # Declared population: 3 DCs x 7 + 2 domains x 7.
            $dns.Count | Should -Be 35
            @($dns | Where-Object { [string]$_.Status -ne 'Not Assessed' }).Count | Should -Be 0
            $one = Get-C12DcRows $rows $script:C12Dc1
            $one.Count | Should -Be 7
            @($one | Where-Object { [string]$_.Detail -notmatch 'dcdiag\.exe' }).Count | Should -Be 0
        }
        It 'with no DC at all reports each domain''s seven roll-ups Not Assessed and nothing else' {
            $rows = Invoke-C12Collector -Targets @() -Active
            $dns = Get-C12DnsRows $rows
            $dns.Count | Should -Be 14
            @($dns | Where-Object { [string]$_.Status -ne 'Not Assessed' }).Count | Should -Be 0
            @($script:C12Calls).Count | Should -Be 0
        }
        It 'grades a DC whose summary table is missing Not Assessed with the overall verdict, never Pass' {
            $script:C12Answer = { param($Server, $Test)
                if ($Test -eq 'DNS') { return (New-C12Result (New-C12DnsOutput -Dc (Get-C12Short $Server) -NoTable)) }
                Get-C12DefaultAnswer -Server $Server -Test $Test }
            $rows = Invoke-C12Collector -Targets $script:C12ThreeDcs -Active
            $dns = Get-C12DnsRows $rows
            $dns.Count | Should -Be 35
            @($dns | Where-Object { [string]$_.Status -ne 'Not Assessed' }).Count | Should -Be 0
            [string](Get-C12Row $rows ("dcdiag DNS Auth: {0}" -f $script:C12Dc1))[0].Detail | Should -Match 'overall verdict'
        }
        It 'rolls a DC whose domain is not known up under "(domain not known)", never dropping it' {
            # Found by an independent review of the diff: no test had a target with an empty Scope.
            $orphan = 'dc9.contoso.com'
            $script:C12Answer = { param($Server, $Test)
                if ($Test -eq 'DNS' -and $Server -eq 'dc9.contoso.com') { return (New-C12Result (New-C12DnsOutput -Dc 'DC9' -Cells 'PASS PASS PASS FAIL PASS PASS n/a')) }
                Get-C12DefaultAnswer -Server $Server -Test $Test }
            $rows = Invoke-C12Collector -Targets @($script:C12ThreeDcs + @(New-C12Target $orphan '')) -Active
            (Get-C12DcRows $rows $orphan).Count | Should -Be 7
            $roll = @($rows | Where-Object { $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -match '^dcdiag DNS (Auth|Basc|Forw|Del|Dyn|RReg|Ext): domain \(domain not known\)$' })
            # Declared population: seven groups for the one DC whose domain is not known.
            $roll.Count | Should -Be 7
            @($roll | Where-Object { [string]$_.Scope -ne '' -or [string]$_.Detail -notmatch '^1 domain controller\(s\)' }).Count | Should -Be 0
            $del = Get-C12Row $rows 'dcdiag DNS Del: domain (domain not known)'
            [string]$del[0].Status | Should -Be 'Fail'
            [string]$del[0].Detail | Should -Match ([regex]::Escape($orphan))
            # It is not counted in a known domain either.
            [string](Get-C12Row $rows 'dcdiag DNS Del: domain contoso.com')[0].Detail | Should -Match '^2 domain controller\(s\)'
        }
        It 'names a DC with no host name in all seven rows, runs nothing against it, and counts it in its domain' {
            # Found by an independent review of the diff: the named cause of an unnamed DC was not pinned.
            $rows = Invoke-C12Collector -Targets @($script:C12ThreeDcs + @(New-C12Target '' 'contoso.com')) -Active
            $unnamed = Get-C12DcRows $rows '(unnamed)'
            # Declared population: the seven groups of the one DC with no host name.
            $unnamed.Count | Should -Be 7
            @($unnamed | Where-Object { [string]$_.Status -ne 'Not Assessed' -or [string]$_.Detail -notmatch 'no host name' }).Count | Should -Be 0
            @($script:C12Calls | Where-Object { $_ -match '/s:(\s|$)' }).Count | Should -Be 0
            $auth = Get-C12Row $rows 'dcdiag DNS Auth: domain contoso.com'
            [string]$auth[0].Status | Should -Be 'Not Assessed'
            [string]$auth[0].Detail | Should -Match '^3 domain controller\(s\)'
        }
        It 'keeps the DNS summary when the DcDiag key of the file sets the time-out' {
            $cfg = Merge-AdfaDcDiagConfig -BaseConfig $script:Config.DcDiag -Override ('{ "TestTimeoutSeconds": 240 }' | ConvertFrom-Json) -OverrideSource 'C:\cfg\dcdiag.json'
            $rows = Invoke-C12Collector -Targets $script:C12ThreeDcs -Active -Config $cfg
            (Get-C12DnsRows $rows).Count | Should -Be 35
            [string](Get-C12Row $rows ("dcdiag DNS RReg: {0}" -f $script:C12Dc3))[0].Status | Should -Be 'Pass'
        }
    }

    Context 'Collector: default run, without the opt-in' {
        It 'runs no DNS test and reports one Not Assessed "not run" row per domain, the reason in NotRun' {
            $rows = Invoke-C12Collector -Targets $script:C12ThreeDcs
            @($script:C12Calls | Where-Object { $_ -match '/test:DNS' }).Count | Should -Be 0
            $dns = Get-C12DnsRows $rows
            # Declared population: the two scoped domains.
            $dns.Count | Should -Be 2
            foreach ($d in @('contoso.com', 'north.contoso.com')) {
                $r = Get-C12Row $rows ("dcdiag DNS not run: {0}" -f $d)
                $r.Count | Should -Be 1 -Because $d
                [string]$r[0].Status | Should -Be 'Not Assessed'
                [string]$r[0].Scope | Should -Be $d
                [string]$r[0].NotRun | Should -Match 'IncludeDcdiagActiveTests'
                [string]$r[0].NotRun | Should -Match 'test record'
                [string]$r[0].Detail | Should -BeNullOrEmpty
            }
        }
        It 'says the same for a scoped domain with no DC, and for no DC at all' {
            $rows = Invoke-C12Collector -Targets @() -Scoped @('contoso.com', 'north.contoso.com', 'south.contoso.com')
            $dns = Get-C12DnsRows $rows
            $dns.Count | Should -Be 3
            @($dns | Where-Object { [string]$_.Status -ne 'Not Assessed' -or [string]$_.Item -notlike 'dcdiag DNS not run: *' }).Count | Should -Be 0
        }
    }

    Context 'Config override: the DcDiag key is not widened' {
        It 'refuses <Name>' -ForEach @(
            @{ Name = 'the DNS summary table'; Json = '{ "DnsSummary": {} }'; Expect = "unknown key 'DnsSummary'" }
            @{ Name = 'a category list'; Json = '{ "Categories": [ "Auth" ] }'; Expect = "unknown key 'Categories'" }
            @{ Name = 'a cell map'; Json = '{ "Cells": [] }'; Expect = "unknown key 'Cells'" }
            @{ Name = 'the header threshold'; Json = '{ "HeaderMinTokens": 3 }'; Expect = "unknown key 'HeaderMinTokens'" }
            @{ Name = 'a test list'; Json = '{ "PerDcTests": [ "DNS" ] }'; Expect = "unknown key 'PerDcTests'" }
        ) {
            { Merge-AdfaDcDiagConfig -BaseConfig $script:Config.DcDiag -Override ($Json | ConvertFrom-Json) -OverrideSource 'x.json' } | Should -Throw -ExpectedMessage ("*{0}*" -f $Expect)
        }
        It 'names the DNS summary table among what a file cannot set' {
            { Merge-AdfaDcDiagConfig -BaseConfig $script:Config.DcDiag -Override ('{ "DnsSummary": {} }' | ConvertFrom-Json) } | Should -Throw -ExpectedMessage '*DNS summary table*'
        }
        It 'passes the built-in DNS summary table through a valid override unchanged' {
            $m = Merge-AdfaDcDiagConfig -BaseConfig $script:Config.DcDiag -Override ('{ "Retries": 3 }' | ConvertFrom-Json) -OverrideSource 'C:\cfg\dcdiag.json'
            [object]::ReferenceEquals($m['DnsSummary'], $script:Config.DcDiag['DnsSummary']) | Should -BeTrue
        }
    }

    Context 'Recommendations' {
        BeforeAll {
            $script:C12Expect = @{ Auth = 'Enterprise Admins'; Basc = 'service availability, and zone existence'; Forw = 'configuration of forwarders'; Del = 'proper delegations'
                Dyn = 'secure dynamic updates'; RReg = 'well-known service \(SRV\)'; Ext = 'proxy server' }
        }
        It 'gives each test group its own advice, per DC and per domain, whatever its Detail says' {
            # Non-vacuity: the hostile Detail does reach unscoped advice on a row with no scoped entry.
            $baseline = Get-AdfaRecommendation -Section 'DC Diagnostics' -Item $script:C12Dc1 -Detail $script:C12Hostile
            $baseline | Should -Not -BeNullOrEmpty
            # Declared population: seven groups, two Item forms each.
            $n = 0
            foreach ($t in $script:C12Tokens) {
                foreach ($item in @(("dcdiag DNS {0}: {1}" -f $t, $script:C12Dc1), ("dcdiag DNS {0}: domain contoso.com" -f $t))) {
                    $rec = Get-AdfaRecommendation -Section 'DC Diagnostics' -Item $item -Detail $script:C12Hostile
                    $rec | Should -Match $script:C12Expect[$t] -Because $item
                    $rec | Should -Not -Be $baseline -Because $item
                    $rec | Should -Match 'changes nothing' -Because $item
                    $n++
                }
            }
            $n | Should -Be 14
        }
        It 'puts the AAAA caveat under Dyn, where Learn gives it, and not under RReg, where it does not' {
            # Found by an independent review of the diff. Learn's "Verify DNS functionality" page (re-read
            # 2026-11-16) gives the AAAA caveat in the /DnsDynamicUpdate step and after reruns of the
            # whole DNS test; its /DnsRecordRegistration section lists CNAME, A, LDAP SRV, GC SRV and
            # PDC SRV with no AAAA caveat.
            $dyn = Get-AdfaRecommendation -Section 'DC Diagnostics' -Item ("dcdiag DNS Dyn: {0}" -f $script:C12Dc1) -Detail 'x'
            $rreg = Get-AdfaRecommendation -Section 'DC Diagnostics' -Item ("dcdiag DNS RReg: {0}" -f $script:C12Dc1) -Detail 'x'
            $dyn | Should -Match 'AAAA'
            $dyn | Should -Match 'IPv6'
            $rreg | Should -Not -Match 'AAAA|IPv6'
            $rreg | Should -Match 'DNSAvoidRegisterRecord'
        }
        It 'gives the not-run and no-domain rows no advice' {
            foreach ($item in @('dcdiag DNS not run: contoso.com', 'dcdiag DNS not run: (no domain known)')) {
                Get-AdfaRecommendation -Section 'DC Diagnostics' -Item $item -Detail $script:C12Hostile | Should -Be '' -Because $item
            }
        }
        It 'sits ahead of the first unscoped entry, with DNS in the section''s catch-all' {
            $map = @($script:RecommendationMap)
            $firstUnscoped = -1
            for ($i = 0; $i -lt $map.Count; $i++) { if (-not $map[$i].ContainsKey('Section')) { $firstUnscoped = $i; break } }
            $dns = @(for ($i = 0; $i -lt $map.Count; $i++) { if ($map[$i].ContainsKey('Section') -and [string]$map[$i].Match -match 'dcdiag DNS ') { $i } })
            # Declared population: the seven test groups.
            $dns.Count | Should -Be 7
            @($dns | Where-Object { $_ -gt $firstUnscoped }).Count | Should -Be 0
            $catch = @($map | Where-Object { $_.ContainsKey('Section') -and [string]$_.Section -eq '(?i)^dc diagnostics' -and [string]$_.Text -eq '' })
            $catch.Count | Should -Be 1
            [string]$catch[0].Match | Should -Match '\|DNS\)'
        }
        It 'gives a failed group the advice of that group, and a Not Assessed row none, through the consolidated finding' {
            $script:C12Answer = { param($Server, $Test)
                if ($Test -eq 'DNS' -and $Server -eq $script:C12Dc2) { return (New-C12Result (New-C12DnsOutput -Dc 'DC2' -Cells 'PASS PASS PASS FAIL PASS PASS n/a')) }
                Get-C12DefaultAnswer -Server $Server -Test $Test }
            $rows = Invoke-C12Collector -Targets $script:C12ThreeDcs -Active -Down @($script:C12Dc3)
            $dnsRows = Get-C12DnsRows $rows
            # Declared population: 3 DCs x 7 + 2 domains x 7.
            $dnsRows.Count | Should -Be 35
            $findings = @(foreach ($r in $dnsRows) { ConvertTo-AdfaConsolidatedFinding -Section 'DC Diagnostics' -Row $r -StatusColumn 'Status' })
            $fails = @($findings | Where-Object { $_.Status -eq 'Fail' })
            # Declared population: DC2's Del row and the contoso.com Del roll-up.
            $fails.Count | Should -Be 2
            @($fails | Where-Object { $_.Recommendation -notmatch 'proper delegations' }).Count | Should -Be 0
            @($findings | Where-Object { $_.Status -match '^(Pass|Info|Not Assessed)$' -and $_.Recommendation }).Count | Should -Be 0
        }
    }

    Context 'Wiring' {
        BeforeAll {
            $script:C12Ast = [System.Management.Automation.Language.Parser]::ParseFile($script:Target, [ref]$null, [ref]$null)
            function Get-C12Function { param([string]$Name) @($script:C12Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq $Name }, $true)) }
        }
        It 'parses and grades in the collector, with no dcdiag invocation of its own' {
            $collector = @(Get-C12Function 'Get-AdfaDcDiagnostic')
            $collector.Count | Should -Be 1
            $names = @($collector[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true) | ForEach-Object { [string]$_.GetCommandName() })
            foreach ($f in @('ConvertFrom-AdfaDcdiagDnsSummary', 'Resolve-AdfaDcdiagDnsCategory', 'Resolve-AdfaDcdiagDnsRollup')) {
                @($names | Where-Object { $_ -eq $f }).Count | Should -Be 1 -Because $f
                @(Get-C12Function $f).Count | Should -Be 1 -Because $f
            }
            # Declared population: the one per-DC invocation C11 already makes.
            @($names | Where-Object { $_ -eq 'Invoke-AdfaDcdiagTest' }).Count | Should -Be 1
            foreach ($f in @('ConvertFrom-AdfaDcdiagDnsSummary', 'Resolve-AdfaDcdiagDnsCategory', 'Resolve-AdfaDcdiagDnsRollup')) {
                $inner = @((Get-C12Function $f)[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true) | ForEach-Object { [string]$_.GetCommandName() })
                @($inner | Where-Object { $_ -match '^(Invoke-ExternalCommand|Invoke-AdfaDcdiagTest|Test-TcpPort|Test-AdfaDcPort)$' }).Count | Should -Be 0 -Because "$f is pure"
            }
        }
        It 'adds no -Sections value and no /x switch' {
            $p = @($script:C12Ast.ParamBlock.Parameters | Where-Object { $_.Name.VariablePath.UserPath -eq 'Sections' })
            $p.Count | Should -Be 1
            $vs = @($p[0].Attributes | Where-Object { $_.TypeName.Name -eq 'ValidateSet' })
            $vs.Count | Should -Be 1
            $values = @($vs[0].PositionalArguments | ForEach-Object { [string]$_.Value })
            $values | Should -Contain 'DcDiagnostics'
            @($values | Where-Object { $_ -match '(?i)dns.*diag|diag.*dns' }).Count | Should -Be 0
            $strings = @($script:C12Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.StringConstantExpressionAst] -or $n -is [System.Management.Automation.Language.ExpandableStringExpressionAst] }, $true))
            @($strings | Where-Object { $_.Extent.Text -match '(?i)(^|[\s''"])/x:' }).Count | Should -Be 0
        }
        It 'carries the same version in the script and the manifest: 1.31.0 (bumped by PORT-PLAN C14)' {
            [string]$script:Config.Version | Should -Be '1.31.0'
            (Import-PowerShellDataFile -Path (Join-Path $script:RepoRoot 'src/ADForestAssessment/ADForestAssessment.psd1')).ModuleVersion | Should -Be '1.31.0'
        }
        It 'documents the per-group rows in the help and the README' {
            $help = $script:C12Ast.GetHelpContent()
            ([string]$help.Parameters['INCLUDEDCDIAGACTIVETESTS'] -replace '\s+', ' ') | Should -Match 'Auth, Basc, Forw, Del, Dyn, RReg, Ext'
            ([string]$help.Description -replace '\s+', ' ') | Should -Match 'summary table'
            $readme = @(Get-Content -LiteralPath (Join-Path $script:RepoRoot 'README.md'))
            $row = @($readme | Where-Object { $_ -match '^\| Diagnostics \|' })
            $row.Count | Should -Be 1
            $row[0] | Should -Match 'Auth, Basc, Forw, Del, Dyn, RReg, Ext'
        }
    }
}

Describe 'DNS: dynamic update, aging and scavenging, locator records, DC A records, records naming no DC, zone and record inventory, DC DNS client (C13)' {
    # PORT-PLAN C13: catalogue ADA-DNS-001..005, ADA-INV-013, 014, 016. Sections Dns ('DNS Health'),
    # DnsAdConsistency ('DNS vs AD Consistency'), DomainControllers ('DC DNS Client') and the opt-in
    # DnsRecordExport ('DNS Record Export'). Every name and address below is fictional (contoso,
    # fabrikam, 192.0.2.0/24) and held in a variable (PSAvoidUsingComputerNameHardcoded).
    BeforeAll {
        $script:C13Cfg = $script:Config.Dns
        $script:C13Dc1 = 'dc1.contoso.com'
        $script:C13Dc2 = 'dc2.contoso.com'
        $script:C13Dc3 = 'dc3.north.contoso.com'
        $script:C13Old = 'old-dc.contoso.com'
        $script:C13Ip1 = '192.0.2.11'
        $script:C13Ip2 = '192.0.2.12'
        $script:C13Ip3 = '192.0.2.13'
        $script:C13IpX = '192.0.2.99'
        $script:C13Hostile = 'replication stale delegation secure dynamic zone transfer scavenging aging no a record does not resolve global catalog backup dcdiag NOT a pass log coverage pdc emulator missing from dns time sync C:\Backup\stale.json'
        function New-C13Target { param([string]$HostName, [string]$Scope, [string]$Ip = '')
            [pscustomobject]@{ HostName = $HostName; Scope = $Scope; Site = 'HQ'; IsReadOnly = $false; IPv4Address = $Ip } }
        # The comma keeps a one-row answer an array, so .Count works under StrictMode on Windows PowerShell 5.1.
        function Get-C13Row { param($Rows, [string]$Item) return , @($Rows | Where-Object { $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -eq $Item }) }
        function Get-C13Like { param($Rows, [string]$Pattern) return , @($Rows | Where-Object { $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -like $Pattern }) }
        # One zone as Get-DnsServerZone returns it (property names provisional, see the config table).
        function New-C13Zone { param([string]$Name, [string]$Dyn = 'Secure', [bool]$Ds = $true, [string]$Type = 'Primary', [bool]$Auto = $false, [bool]$Reverse = $false, [string]$Scope = 'Domain')
            [pscustomobject]@{ ZoneName = $Name; ZoneType = $Type; IsAutoCreated = $Auto; IsDsIntegrated = $Ds; IsReverseLookupZone = $Reverse
                DynamicUpdate = $Dyn; ReplicationScope = $Scope; SecureSecondaries = 'NoTransfer' } }
        # One Get-AdfaDnsServerRaw result, in the shape it returns.
        function New-C13ServerRaw { param($Zones, $Interval = [timespan]::FromDays(7), [bool]$Aging = $true, [string[]]$Forwarders = @())
            $agingMap = @{}
            foreach ($z in @($Zones)) {
                if ($z.ZoneType -eq 'Primary' -and -not $z.IsAutoCreated) {
                    $agingMap[([string]$z.ZoneName).ToLowerInvariant()] = [pscustomobject]@{ Ok = $true; AgingEnabled = $Aging; NoRefreshInterval = [timespan]::FromDays(7)
                        RefreshInterval = [timespan]::FromDays(7); ScavengeServers = @(); Error = '' }
                }
            }
            [pscustomobject]@{ Ok = $true; Error = ''; ErrorCode = ''; Zones = @($Zones); ScavengingOk = $true; ScavengingInterval = $Interval; ScavengingState = $false
                ScavengingError = ''; Aging = $agingMap; ForwardersOk = $true; Forwarders = @($Forwarders); ForwarderError = '' } }
        function New-C13FailedRaw { param([string]$Message, [string]$Code = '')
            [pscustomobject]@{ Ok = $false; Error = $Message; ErrorCode = $Code; Zones = @(); ScavengingOk = $false; ScavengingInterval = $null; ScavengingState = $null
                ScavengingError = ''; Aging = @{}; ForwardersOk = $false; Forwarders = @(); ForwarderError = '' } }
        function New-C13Obs { param([string]$Server, [bool]$Read = $true, $Ds = $true, [string]$Dyn = 'Secure', $Scav = $true, $Aging = $true, [string]$Cause = '')
            [pscustomobject]@{ Server = $Server; Read = $Read; IsDsIntegrated = $Ds; DynamicUpdate = $Dyn; ServerScavenging = $Scav; AgingEnabled = $Aging; Cause = $Cause; ZoneType = 'Primary' } }
        function New-C13Check { param([string]$Record, [string]$Server, [string]$State, [string]$Cause = '')
            [pscustomobject]@{ Record = $Record; Server = $Server; State = $State; Cause = $Cause } }
        function New-C13Adapter { param([string[]]$Ip, $Dns)
            [pscustomobject]@{ IPEnabled = $true; IPAddress = @($Ip); DNSServerSearchOrder = $Dns; Description = 'Fictional adapter'; InterfaceIndex = [uint32]4 } }
        function New-C13NetRaw { param($Adapters, [bool]$Ok = $true, [string]$Message = '', [string]$Code = '')
            [pscustomobject]@{ Ok = $Ok; Protocol = 'Wsman'; Error = $Message; ErrorCode = $Code; Adapters = @($Adapters) } }
        # DnsServer cmdlets, defined so the raw seams can be exercised on a host without the module.
        function Get-DnsServerZone { param([string]$ComputerName, [string]$Name, $ErrorAction) & $script:C13ZoneAnswer $ComputerName }
        function Get-DnsServerScavenging { param([string]$ComputerName, $ErrorAction) & $script:C13ScavAnswer $ComputerName }
        function Get-DnsServerZoneAging { param([string]$Name, [string]$ComputerName, $ErrorAction) $script:C13AgingCalls += $Name; & $script:C13AgingAnswer $Name }
        function Get-DnsServerForwarder { param([string]$ComputerName, $ErrorAction) [pscustomobject]@{ IPAddress = @($script:C13IpX) } }
        function Get-DnsServerResourceRecord { param([string]$ComputerName, [string]$ZoneName, [string]$Name, [string]$RRType, $ErrorAction)
            $script:C13RecordCalls += [pscustomobject]@{ ComputerName = $ComputerName; ZoneName = $ZoneName; Name = $Name; RRType = $RRType }
            & $script:C13RecordAnswer $ComputerName $ZoneName $Name $RRType }
        function Get-ADDomainController { param([Parameter(ValueFromRemainingArguments)]$a) $script:C13AdDcs }
        function Get-ADDomain { param([Parameter(ValueFromRemainingArguments)]$a) throw 'STUB: not used by these tests' }
        function New-C13Srv { param([string]$HostName, [string]$Target)
            [pscustomobject]@{ HostName = $HostName; RecordType = 'SRV'; RecordClass = 'IN'; TimeToLive = [timespan]::FromMinutes(10); Timestamp = $null
                RecordData = [pscustomobject]@{ DomainName = ($Target + '.'); Port = [uint16]389; Priority = [uint16]0; Weight = [uint16]100 } } }
        function New-C13A { param([string]$HostName, [string]$Ip)
            [pscustomobject]@{ HostName = $HostName; RecordType = 'A'; RecordClass = 'IN'; TimeToLive = [timespan]::FromMinutes(20); Timestamp = [datetime]'2026-11-10'
                RecordData = [pscustomobject]@{ IPv4Address = $Ip } } }
        function New-C13Cname { param([string]$HostName, [string]$Alias)
            [pscustomobject]@{ HostName = $HostName; RecordType = 'CNAME'; RecordClass = 'IN'; TimeToLive = [timespan]::FromMinutes(10); Timestamp = $null
                RecordData = [pscustomobject]@{ HostNameAlias = ($Alias + '.') } } }
        $script:C13Ast = [System.Management.Automation.Language.Parser]::ParseFile($script:Target, [ref]$null, [ref]$null)
        $script:C13Main = @($script:C13Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'Invoke-Main' }, $true))
        function Get-C13Function { param([string]$Name) @($script:C13Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq $Name }, $true)) }
        function Get-C13Parameter { param($Call, [string]$Name)
            $elements = @($Call.CommandElements)
            for ($i = 0; $i -lt $elements.Count; $i++) {
                $e = $elements[$i]
                if ($e -is [System.Management.Automation.Language.CommandParameterAst] -and $e.ParameterName -eq $Name) {
                    if ($null -ne $e.Argument) { return $e.Argument }
                    if (($i + 1) -lt $elements.Count) { return $elements[$i + 1] }
                }
            }
            return $null
        }
        function Get-C13Branch { param([string]$Condition)
            @($script:C13Main[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.IfStatementAst] -and $n.Clauses[0].Item1.Extent.Text -eq $Condition }, $true)) }
        # The read-only guard over a parsed script: a DnsServer/DnsClient cmdlet that writes; dnscmd or
        # ipconfig named as a command or as a string argument of ANY command (the script starts console
        # tools through Invoke-ExternalCommand -FilePath '<tool>.exe'); and a registration or cache
        # switch (/registerdns, /dsregdns, /dsderegdns, /flushdns, /release, /renew) in any string
        # literal outside the recommendation map, whose advice names them for the operator to run.
        # What it cannot see: a switch assembled at run time from pieces.
        function Get-C13WriteHit { param($Ast)
            $hits = @()
            $cmds = @($Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true))
            $cmdletRx = '(?i)^(Set|Add|Remove|Start|Stop|Clear|Register|Sync|Restore|Import|Export|Reset|Resume|Suspend|Invoke|Update|Enable|Disable|Step|Test)-DnsServer|^Register-DnsClient|^Set-DnsClient|^Clear-DnsClientCache'
            $toolRx = '(?i)(^|\\)(dnscmd|ipconfig)(\.exe)?$'
            foreach ($c in $cmds) {
                $name = [string]$c.GetCommandName()
                if ($name -match $cmdletRx) { $hits += ("cmdlet: {0}" -f $c.Extent.Text) }
                $words = @($name) + @(@($c.CommandElements) | ForEach-Object { @($_.FindAll({ param($n) $n -is [System.Management.Automation.Language.StringConstantExpressionAst] -or $n -is [System.Management.Automation.Language.ExpandableStringExpressionAst] }, $true)) } | ForEach-Object { [string]$_.Value })
                if (@($words | Where-Object { $_ -match $toolRx }).Count -gt 0) { $hits += ("tool: {0}" -f $c.Extent.Text) }
            }
            $switchRx = '(?i)(^|[\s"''])/(dsregdns|dsderegdns|registerdns|flushdns|release|renew)\b'
            $map = @($Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -eq '$script:RecommendationMap' }, $true))
            foreach ($s in @($Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.StringConstantExpressionAst] -or $n -is [System.Management.Automation.Language.ExpandableStringExpressionAst] }, $true))) {
                if ([string]$s.Value -notmatch $switchRx) { continue }
                $inMap = $false
                $p = $s.Parent
                while ($null -ne $p) { if ($map -contains $p) { $inMap = $true; break }; $p = $p.Parent }
                if (-not $inMap) { $hits += ("switch: {0}" -f $s.Extent.Text) }
            }
            return , @($hits)
        }
    }
    BeforeEach {
        Clear-AdfaDcPortCache
        $script:C13AgingCalls = @()
        $script:C13RecordCalls = @()
        $script:C13ZoneAnswer = { param($c) @((New-C13Zone 'contoso.com'), (New-C13Zone '_msdcs.contoso.com'), (New-C13Zone '0.in-addr.arpa' -Auto $true -Ds $false -Dyn 'None'), (New-C13Zone 'fabrikam.com' -Type 'Forwarder' -Dyn 'None' -Ds $false)) }
        $script:C13ScavAnswer = { param($c) [pscustomobject]@{ ScavengingInterval = [timespan]::FromDays(7); ScavengingState = $true } }
        $script:C13AgingAnswer = { param($n) [pscustomobject]@{ ZoneName = $n; AgingEnabled = $true; NoRefreshInterval = [timespan]::FromDays(7); RefreshInterval = [timespan]::FromDays(7); ScavengeServers = @() } }
        $script:C13RecordAnswer = { param($c, $z, $n, $t) @() }
    }

    Context 'Config table (Learn, read 2026-11-17)' {
        It 'declares the graded locator records, the dynamic update values and the tool defaults, labelled as tool defaults' {
            $script:C13Cfg | Should -Not -BeNullOrEmpty
            [string]$script:C13Cfg['ReadDate'] | Should -Be '2026-11-17'
            [string]$script:C13Cfg['ThresholdSource'] | Should -Match 'tool defaults, not Microsoft values'
            # Declared population: the two SRV records of reference decision 61, Dc and Kdc.
            (@($script:C13Cfg['LocatorRecords'] | ForEach-Object { [string]$_['Mnemonic'] }) -join ',') | Should -Be 'Dc,Kdc'
            (@($script:C13Cfg['LocatorRecords'] | ForEach-Object { [string]$_['Name'] }) -join ',') | Should -Be '_ldap._tcp.dc._msdcs.{0},_kerberos._tcp.dc._msdcs.{0}'
            (@($script:C13Cfg['DynamicUpdateValues']) -join ',') | Should -Be 'None,Secure,NonsecureAndSecure'
            $expected = [ordered]@{ NonsecureStatus = 'Fail'; ScavengingOffStatus = 'Warning'; AgingOffStatus = 'Warning'; ARecordStatus = 'Warning'; StaleRecordStatus = 'Warning'; OneInstrumentStatus = 'Warning'; SingleServerStatus = 'Warning' }
            # Declared population: the seven statuses a file can set.
            @($expected.Keys).Count | Should -Be 7
            foreach ($k in @($expected.Keys)) { [string]$script:C13Cfg[$k] | Should -Be $expected[$k] -Because $k }
            [int]$script:C13Cfg['RecordExportCap'] | Should -Be 50000
            [int]$script:C13Cfg['RpcPort'] | Should -Be 135
        }
        It 'carries version 1.31.0 in the script and the manifest (bumped by PORT-PLAN C14)' {
            [string]$script:Config.Version | Should -Be '1.31.0'
            (Import-PowerShellDataFile -Path (Join-Path $script:RepoRoot 'src/ADForestAssessment/ADForestAssessment.psd1')).ModuleVersion | Should -Be '1.31.0'
        }
    }

    Context 'Verdict: zone dynamic update (DNS-001, pure)' {
        It 'fails a zone that one hosting server reports NonsecureAndSecure on an AD-integrated zone' {
            $v = Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1), (New-C13Obs $script:C13Dc2 -Dyn 'NonsecureAndSecure')) -Config $script:C13Cfg
            $v.Status | Should -Be 'Fail'
            $v.Detail | Should -Match 'Nonsecure and secure'
            $v.Detail | Should -Match '1 of 2'
        }
        It 'passes Secure and None, read on every hosting server' {
            (Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1), (New-C13Obs $script:C13Dc2)) -Config $script:C13Cfg).Status | Should -Be 'Pass'
            (Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Dyn 'None')) -Config $script:C13Cfg).Status | Should -Be 'Pass'
        }
        It 'is Not Assessed, never Pass, when a hosting server was not read, and names the cause' {
            $v = Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1), (New-C13Obs $script:C13Dc2 -Read $false -Cause 'Unreachable: RPC (135) did not answer')) -Config $script:C13Cfg
            $v.Status | Should -Be 'Not Assessed'
            $v.Detail | Should -Match '1 of 2'
            $v.Evidence | Should -Match 'Unreachable'
        }
        It 'keeps a measured Fail when another server was not read' {
            (Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Dyn 'NonsecureAndSecure'), (New-C13Obs $script:C13Dc2 -Read $false -Cause 'x')) -Config $script:C13Cfg).Status | Should -Be 'Fail'
        }
        It 'reads a value it does not know, or an absent property, as not measured' {
            $odd = Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Dyn 'Bogus')) -Config $script:C13Cfg
            $odd.Status | Should -Be 'Not Assessed'
            $odd.Detail | Should -Match 'not recognised'
            (Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Dyn '')) -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
            (Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Ds $null)) -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
            (Get-AdfaDnsDynamicUpdateVerdict -Observations @() -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
        }
        It 'reports a zone that is not AD-integrated as Info: secure updates exist only for AD-integrated zones' {
            $v = Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Ds $false -Dyn 'NonsecureAndSecure')) -Config $script:C13Cfg
            $v.Status | Should -Be 'Info'
            $v.Detail | Should -Match 'only for AD-integrated zones'
        }
        It 'grades NonsecureStatus from the config, so an override to Warning is honoured' {
            $cfg = Merge-AdfaDnsConfig -BaseConfig $script:C13Cfg -Override @{ NonsecureStatus = 'Warning' } -OverrideSource 'C:\cfg\dns.json'
            (Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Dyn 'NonsecureAndSecure')) -Config $cfg).Status | Should -Be 'Warning'
        }
    }

    Context 'Verdict: zone aging and server scavenging (DNS-002, pure)' {
        It 'warns when every hosting server was read and none scavenges' {
            $v = Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $false), (New-C13Obs $script:C13Dc2 -Scav $false)) -Config $script:C13Cfg
            $v.Status | Should -Be 'Warning'
            $v.Detail | Should -Match 'no hosting DNS server has scavenging enabled'
            $v.Detail | Should -Match 'tool default'
        }
        It 'passes when one hosting server scavenges and the zone ages its records' {
            (Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $false), (New-C13Obs $script:C13Dc2 -Scav $true)) -Config $script:C13Cfg).Status | Should -Be 'Pass'
        }
        It 'warns when a server scavenges but the zone has aging off (Learn: scavenging skips that zone)' {
            $v = Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $true -Aging $false)) -Config $script:C13Cfg
            $v.Status | Should -Be 'Warning'
            $v.Detail | Should -Match 'aging is not enabled'
        }
        It 'is Not Assessed, never Pass or Warning, when a hosting server or a value was not read' {
            (Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $false), (New-C13Obs $script:C13Dc2 -Read $false -Cause 'Access denied')) -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
            (Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $null)) -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
            (Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Aging $null)) -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
            (Get-AdfaDnsScavengingVerdict -Observations @() -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
        }
        It 'treats a scavenging interval of zero as off and any longer one as on (Learn: 0 disables scavenging)' {
            Test-AdfaDnsServerScavenges -Interval ([timespan]::Zero) | Should -BeFalse
            Test-AdfaDnsServerScavenges -Interval ([timespan]::FromSeconds(1)) | Should -BeTrue
            Test-AdfaDnsServerScavenges -Interval ([timespan]::FromDays(7)) | Should -BeTrue
            Test-AdfaDnsServerScavenges -Interval '7.00:00:00' | Should -BeTrue
            Test-AdfaDnsServerScavenges -Interval '00:00:00' | Should -BeFalse
            $null -eq (Test-AdfaDnsServerScavenges -Interval $null) | Should -BeTrue
            $null -eq (Test-AdfaDnsServerScavenges -Interval 'seven days') | Should -BeTrue
            $null -eq (Test-AdfaDnsServerScavenges -Interval 168) | Should -BeTrue
        }
        It 'keeps a measured "aging off" as AgingOffStatus when another hosting server was not read' {
            $v = Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $true -Aging $false), (New-C13Obs $script:C13Dc2 -Read $false -Cause 'Unreachable: RPC (135) did not answer')) -Config $script:C13Cfg
            $v.Status | Should -Be 'Warning'
            $v.Detail | Should -Match 'aging is not enabled for this zone on 1 of 2'
        }
        It 'does not assert "no hosting server scavenges" when the hosting set is not complete, and still grades aging off' {
            $obs = @((New-C13Obs $script:C13Dc1 -Scav $false), (New-C13Obs $script:C13Dc2 -Scav $false))
            $v = Get-AdfaDnsScavengingVerdict -Observations $obs -Config $script:C13Cfg -HostSetComplete $false -HostSetCause 'its replication scope (Forest) reaches DNS servers in every domain'
            $v.Status | Should -Be 'Not Assessed'
            $v.Detail | Should -Match 'replication scope \(Forest\)'
            $v.Detail | Should -Not -Match 'Every one of the'
            (Get-AdfaDnsScavengingVerdict -Observations $obs -Config $script:C13Cfg -HostSetComplete $true).Status | Should -Be 'Warning'
            (Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $true)) -Config $script:C13Cfg -HostSetComplete $false).Status | Should -Be 'Pass'
            (Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $false -Aging $false)) -Config $script:C13Cfg -HostSetComplete $false).Status | Should -Be 'Warning'
        }
        It 'honours ScavengingOffStatus and AgingOffStatus from an override' {
            $cfg = Merge-AdfaDnsConfig -BaseConfig $script:C13Cfg -Override @{ ScavengingOffStatus = 'Info'; AgingOffStatus = 'Info' } -OverrideSource 'C:\cfg\dns.json'
            (Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $false)) -Config $cfg).Status | Should -Be 'Info'
            (Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Aging $false)) -Config $cfg).Status | Should -Be 'Info'
        }
    }

    Context 'Verdict: two instruments and the DC locator records (DNS-003, pure)' {
        It 'combines the server read and the resolver into one state: <Server> + <Resolver> = <Expect>' -ForEach @(
            @{ Server = 'Present'; Resolver = 'Absent'; Expect = 'Present' }
            @{ Server = 'Absent'; Resolver = 'Present'; Expect = 'Present' }
            @{ Server = 'Absent'; Resolver = 'Absent'; Expect = 'AbsentBoth' }
            @{ Server = 'Absent'; Resolver = 'Unread'; Expect = 'AbsentOne' }
            @{ Server = 'Unread'; Resolver = 'Absent'; Expect = 'AbsentOne' }
            @{ Server = 'Unread'; Resolver = 'Unread'; Expect = 'Unread' }
            @{ Server = 'Present'; Resolver = 'Present'; Expect = 'Present' }
        ) {
            Get-AdfaDnsEvidenceState -ServerOutcome $Server -ResolverOutcome $Resolver | Should -Be $Expect
        }
        It 'passes a DC every record names on every DNS server' {
            $checks = @((New-C13Check 'Dc' $script:C13Dc1 'Present'), (New-C13Check 'Kdc' $script:C13Dc1 'Present'), (New-C13Check 'Dc' $script:C13Dc2 'Present'), (New-C13Check 'Kdc' $script:C13Dc2 'Present'))
            (Get-AdfaDcLocatorVerdict -IsReadOnly $false -Checks $checks -Config $script:C13Cfg).Status | Should -Be 'Pass'
        }
        It 'fails a DC only when both instruments agree a record is absent' {
            $v = Get-AdfaDcLocatorVerdict -IsReadOnly $false -Checks @((New-C13Check 'Dc' $script:C13Dc1 'Present'), (New-C13Check 'Kdc' $script:C13Dc1 'AbsentBoth')) -Config $script:C13Cfg
            $v.Status | Should -Be 'Fail'
            $v.Detail | Should -Match 'both instruments'
        }
        It 'grades an absence seen by one instrument only as OneInstrumentStatus, and says so' {
            $v = Get-AdfaDcLocatorVerdict -IsReadOnly $false -Checks @((New-C13Check 'Dc' $script:C13Dc1 'AbsentOne')) -Config $script:C13Cfg
            $v.Status | Should -Be 'Warning'
            $v.Detail | Should -Match 'one instrument'
            $cfg = Merge-AdfaDnsConfig -BaseConfig $script:C13Cfg -Override @{ OneInstrumentStatus = 'Not Assessed' } -OverrideSource 'x.json'
            (Get-AdfaDcLocatorVerdict -IsReadOnly $false -Checks @((New-C13Check 'Dc' $script:C13Dc1 'AbsentOne')) -Config $cfg).Status | Should -Be 'Not Assessed'
        }
        It 'is Not Assessed, never Pass, when a server was not read or there is nothing to check' {
            $v = Get-AdfaDcLocatorVerdict -IsReadOnly $false -Checks @((New-C13Check 'Dc' $script:C13Dc1 'Present'), (New-C13Check 'Dc' $script:C13Dc2 'Unread' 'no answer')) -Config $script:C13Cfg
            $v.Status | Should -Be 'Not Assessed'
            (Get-AdfaDcLocatorVerdict -IsReadOnly $false -Checks @() -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
        }
        It 'excludes a read-only DC as Info: RODCs register site-specific records by default' {
            $v = Get-AdfaDcLocatorVerdict -IsReadOnly $true -Checks @((New-C13Check 'Dc' $script:C13Dc1 'AbsentBoth')) -Config $script:C13Cfg
            $v.Status | Should -Be 'Info'
            $v.Detail | Should -Match 'read-only'
        }
    }

    Context 'Verdict: DC A records (DNS-004, pure)' {
        It 'passes when every A record is a configured IPv4 address of the DC' {
            $a = @([pscustomobject]@{ Server = $script:C13Dc1; State = 'Present'; Addresses = @($script:C13Ip1) }, [pscustomobject]@{ Server = $script:C13Dc2; State = 'Present'; Addresses = @($script:C13Ip1) })
            (Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers $a -Config $script:C13Cfg).Status | Should -Be 'Pass'
        }
        It 'warns on an A record for an address the DC does not have, and on an A record absent on both instruments' {
            $wrong = Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers @([pscustomobject]@{ Server = $script:C13Dc1; State = 'Present'; Addresses = @($script:C13Ip1, $script:C13IpX) }) -Config $script:C13Cfg
            $wrong.Status | Should -Be 'Warning'
            $wrong.Detail | Should -Match 'not configured on'
            $wrong.Detail | Should -Not -Match ([regex]::Escape($script:C13IpX))
            $wrong.Evidence | Should -Match ([regex]::Escape($script:C13IpX))
            (Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers @([pscustomobject]@{ Server = $script:C13Dc1; State = 'AbsentBoth'; Addresses = @() }) -Config $script:C13Cfg).Status | Should -Be 'Warning'
        }
        It 'is Not Assessed when the adapters were not read, or a server did not answer' {
            $na = Get-AdfaDcARecordVerdict -ConfiguredIPv4 $null -ConfiguredCause 'Access denied' -Answers @([pscustomobject]@{ Server = $script:C13Dc1; State = 'Present'; Addresses = @($script:C13Ip1) }) -Config $script:C13Cfg
            $na.Status | Should -Be 'Not Assessed'
            $na.Detail | Should -Match 'Access denied'
            (Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers @([pscustomobject]@{ Server = $script:C13Dc1; State = 'Unread'; Addresses = @() }) -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
            (Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers @() -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
        }
        It 'grades an A record absent on one instrument only as OneInstrumentStatus, never Pass' {
            $one = @([pscustomobject]@{ Server = $script:C13Dc1; State = 'AbsentOne'; Addresses = @() }, [pscustomobject]@{ Server = $script:C13Dc2; State = 'Present'; Addresses = @($script:C13Ip1) })
            $v = Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers $one -Config $script:C13Cfg
            $v.Status | Should -Be 'Warning'
            $v.Detail | Should -Match 'one instrument only'
            $cfg = Merge-AdfaDnsConfig -BaseConfig $script:C13Cfg -Override @{ OneInstrumentStatus = 'Not Assessed' } -OverrideSource 'x.json'
            (Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers $one -Config $cfg).Status | Should -Be 'Not Assessed'
        }
        It 'is Not Assessed, never Pass, when a record was returned but no address could be read from it' {
            $v = Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers @([pscustomobject]@{ Server = $script:C13Dc1; State = 'Present'; Addresses = @() }) -Config $script:C13Cfg
            $v.Status | Should -Be 'Not Assessed'
            $v.Detail | Should -Match 'could not read, so it was not compared'
            (Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers @([pscustomobject]@{ Server = $script:C13Dc1; State = 'Present'; Addresses = @('', ' ') }) -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
            # A measured mismatch on another server still stands.
            (Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers @([pscustomobject]@{ Server = $script:C13Dc1; State = 'Present'; Addresses = @() }, [pscustomobject]@{ Server = $script:C13Dc2; State = 'Present'; Addresses = @($script:C13IpX) }) -Config $script:C13Cfg).Status | Should -Be 'Warning'
        }
    }

    Context 'Grade provenance: a grade a file set names the file, a built-in grade says tool default' {
        It 'names the override file in every graded family whose status it set: <Family>' -ForEach @(
            @{ Family = 'zone dynamic update'; Key = 'NonsecureStatus'; Value = 'Warning' }
            @{ Family = 'zone scavenging'; Key = 'ScavengingOffStatus'; Value = 'Info' }
            @{ Family = 'zone aging'; Key = 'AgingOffStatus'; Value = 'Info' }
            @{ Family = 'locator, one instrument'; Key = 'OneInstrumentStatus'; Value = 'Not Assessed' }
            @{ Family = 'A record'; Key = 'ARecordStatus'; Value = 'Info' }
            @{ Family = 'stale record'; Key = 'StaleRecordStatus'; Value = 'Info' }
            @{ Family = 'DNS client'; Key = 'SingleServerStatus'; Value = 'Info' }
        ) {
            $path = 'C:\cfg\backup-stale-replication.json'
            $cfg = Merge-AdfaDnsConfig -BaseConfig $script:C13Cfg -Override @{ $Key = $Value } -OverrideSource $path
            $v = switch ($Family) {
                'zone dynamic update' { Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Dyn 'NonsecureAndSecure')) -Config $cfg }
                'zone scavenging' { Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Scav $false)) -Config $cfg }
                'zone aging' { Get-AdfaDnsScavengingVerdict -Observations @((New-C13Obs $script:C13Dc1 -Aging $false)) -Config $cfg }
                'locator, one instrument' { Get-AdfaDcLocatorVerdict -IsReadOnly $false -Checks @((New-C13Check 'Dc' $script:C13Dc1 'AbsentOne')) -Config $cfg }
                'A record' { Get-AdfaDcARecordVerdict -ConfiguredIPv4 @($script:C13Ip1) -Answers @([pscustomobject]@{ Server = $script:C13Dc1; State = 'Present'; Addresses = @($script:C13IpX) }) -Config $cfg }
                'stale record' { Get-AdfaStaleDnsRecordVerdict -Candidates @([pscustomobject]@{ Name = '_ldap._tcp.dc._msdcs.contoso.com'; Type = 'SRV'; Target = $script:C13Old; Server = $script:C13Dc1 }) -KnownDcHosts @($script:C13Dc1) -Config $cfg }
                'DNS client' { Get-AdfaDcDnsClientVerdict -DnsServers @('127.0.0.1') -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @($script:C13Ip1, $script:C13Ip2) -DcCount 2 -Config $cfg }
            }
            [string]$v.Status | Should -Be $Value
            $v.Detail | Should -Match ("Graded {0}: {1} \(loaded [0-9-]+\) for {2}" -f [regex]::Escape($Value), [regex]::Escape($path), $Key)
            $v.Detail | Should -Not -Match 'The grade is a tool default'
        }
        It 'says tool defaults, not Microsoft values, when no file set the grade' {
            $v = Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Dyn 'NonsecureAndSecure')) -Config $script:C13Cfg
            $v.Detail | Should -Match 'Graded Fail: tool defaults, not Microsoft values'
        }
        It 'keeps each graded row on its own advice when the provenance names a file whose path says backup, stale and replication' {
            $cfg = Merge-AdfaDnsConfig -BaseConfig $script:C13Cfg -Override @{ NonsecureStatus = 'Warning'; StaleRecordStatus = 'Warning' } -OverrideSource 'C:\cfg\backup-stale-replication.json'
            $dyn = Get-AdfaDnsDynamicUpdateVerdict -Observations @((New-C13Obs $script:C13Dc1 -Dyn 'NonsecureAndSecure')) -Config $cfg
            $row = New-AdfaDnsRow -Scope 'contoso.com' -Item 'Zone dynamic update: contoso.com' -Status ([string]$dyn.Status) -Detail ([string]$dyn.Detail)
            (ConvertTo-AdfaConsolidatedFinding -Section 'DNS Health' -Row $row -StatusColumn 'Status').Recommendation | Should -Match 'Secure only'
            $st = Get-AdfaStaleDnsRecordVerdict -Candidates @([pscustomobject]@{ Name = '_ldap._tcp.dc._msdcs.contoso.com'; Type = 'SRV'; Target = $script:C13Old; Server = $script:C13Dc1 }) -KnownDcHosts @($script:C13Dc1) -Config $cfg
            $row2 = New-AdfaDnsRow -Area 'DnsAdConsistency' -Scope 'contoso.com' -Item ("Stale DC record: {0}" -f $script:C13Old) -Status ([string]$st.Status) -Detail ([string]$st.Detail)
            $rec = (ConvertTo-AdfaConsolidatedFinding -Section 'DNS vs AD Consistency' -Row $row2 -StatusColumn 'Status').Recommendation
            $rec | Should -Match 'stale domain controllers'
            $rec | Should -Not -Match 'Disable first|repadmin'
        }
    }

    Context 'Verdict: records that name no DC (DNS-005, pure)' {
        It 'lists an SRV target that matches no known DC, and no record of a known DC, an RODC included' {
            $cand = @([pscustomobject]@{ Name = '_ldap._tcp.dc._msdcs.contoso.com'; Type = 'SRV'; Target = $script:C13Old; Server = $script:C13Dc1 },
                [pscustomobject]@{ Name = '_ldap._tcp.dc._msdcs.contoso.com'; Type = 'SRV'; Target = 'RODC1.contoso.com.'; Server = $script:C13Dc1 })
            $v = Get-AdfaStaleDnsRecordVerdict -Candidates $cand -KnownDcHosts @($script:C13Dc1, 'rodc1.contoso.com') -KnownDsaGuids @() -Config $script:C13Cfg
            # Declared population: the one target that is no DC.
            @($v.Stale).Count | Should -Be 1
            [string]@($v.Stale)[0].Target | Should -Be $script:C13Old
            $v.Status | Should -Be 'Warning'
            $v.Detail | Should -Not -Match ([regex]::Escape($script:C13Old))
        }
        It 'lists a GUID._msdcs CNAME whose GUID is no NTDS Settings object, only when the DSA GUIDs were read' {
            $g1 = '11111111-2222-3333-4444-555555555555'
            $g2 = '99999999-8888-7777-6666-555555555555'
            $cand = @([pscustomobject]@{ Name = ("{0}._msdcs.contoso.com" -f $g1); Type = 'CNAME'; Target = $script:C13Dc1; Server = $script:C13Dc1 },
                [pscustomobject]@{ Name = ("{0}._msdcs.contoso.com" -f $g2); Type = 'CNAME'; Target = $script:C13Old; Server = $script:C13Dc1 })
            $v = Get-AdfaStaleDnsRecordVerdict -Candidates $cand -KnownDcHosts @($script:C13Dc1) -KnownDsaGuids @($g1.ToUpperInvariant()) -Config $script:C13Cfg
            (@($v.Stale | ForEach-Object { [string]$_.Name }) -join ',') | Should -Be ("{0}._msdcs.contoso.com" -f $g2)
            $noGuids = Get-AdfaStaleDnsRecordVerdict -Candidates $cand -KnownDcHosts @($script:C13Dc1) -KnownDsaGuids @() -DsaError 'STUB: configuration partition unreadable' -Config $script:C13Cfg
            @($noGuids.Stale).Count | Should -Be 0
            $noGuids.Status | Should -Be 'Not Assessed'
            $noGuids.Detail | Should -Match 'configuration partition unreadable'
        }
        It 'passes when everything was read and nothing is stale, and is Not Assessed when a server was not read' {
            (Get-AdfaStaleDnsRecordVerdict -Candidates @() -KnownDcHosts @($script:C13Dc1) -KnownDsaGuids @() -Config $script:C13Cfg).Status | Should -Be 'Pass'
            $na = Get-AdfaStaleDnsRecordVerdict -Candidates @() -KnownDcHosts @($script:C13Dc1) -KnownDsaGuids @() -Unread @('dc2.contoso.com: no answer') -Config $script:C13Cfg
            $na.Status | Should -Be 'Not Assessed'
            (Get-AdfaStaleDnsRecordVerdict -Candidates @() -KnownDcHosts @() -KnownDsaGuids @() -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
        }
        It 'lists nothing as stale when no DC is known, whatever the records name' {
            $cand = @([pscustomobject]@{ Name = '_ldap._tcp.dc._msdcs.contoso.com'; Type = 'SRV'; Target = $script:C13Dc1; Server = $script:C13Dc1 },
                [pscustomobject]@{ Name = '_ldap._tcp.dc._msdcs.contoso.com'; Type = 'SRV'; Target = $script:C13Dc2; Server = $script:C13Dc1 })
            foreach ($known in @(, @()) + @(, $null)) {
                $v = Get-AdfaStaleDnsRecordVerdict -Candidates $cand -KnownDcHosts $known -KnownDsaGuids @() -Config $script:C13Cfg
                $v.Status | Should -Be 'Not Assessed'
                @($v.Stale).Count | Should -Be 0
                $v.Detail | Should -Match 'No domain controller is known'
            }
        }
        It 'judges no GUID._msdcs CNAME when no DSA GUID is known and no error was given' {
            $cand = @([pscustomobject]@{ Name = '11111111-2222-3333-4444-555555555555._msdcs.contoso.com'; Type = 'CNAME'; Target = $script:C13Dc1; Server = $script:C13Dc1 })
            $v = Get-AdfaStaleDnsRecordVerdict -Candidates $cand -KnownDcHosts @($script:C13Dc1) -KnownDsaGuids @() -Config $script:C13Cfg
            @($v.Stale).Count | Should -Be 0
            $v.Status | Should -Be 'Not Assessed'
            $v.Detail | Should -Match 'no DSA GUID is known'
        }
    }

    Context 'Verdict: DC DNS client settings (INV-016, pure)' {
        It 'is Not Assessed with the cause when the adapters were not read' {
            $v = Get-AdfaDcDnsClientVerdict -DnsServers $null -Cause 'Access denied: x' -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @() -DcCount 2 -Config $script:C13Cfg
            $v.Status | Should -Be 'Not Assessed'
            $v.Detail | Should -Match 'Access denied'
        }
        It 'warns on a single DNS server when more than one DC is known (KB 4013), and is Info in a single-DC forest' {
            (Get-AdfaDcDnsClientVerdict -DnsServers @('127.0.0.1') -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @($script:C13Ip1, $script:C13Ip2) -DcCount 2 -Config $script:C13Cfg).Status | Should -Be 'Warning'
            (Get-AdfaDcDnsClientVerdict -DnsServers @($script:C13Ip2) -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @($script:C13Ip1, $script:C13Ip2) -DcCount 2 -Config $script:C13Cfg).Status | Should -Be 'Warning'
            $one = Get-AdfaDcDnsClientVerdict -DnsServers @('127.0.0.1') -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @($script:C13Ip1) -DcCount 1 -DcCountIsForest $true -Config $script:C13Cfg
            $one.Status | Should -Be 'Info'
            $one.Detail | Should -Match 'tolerable'
        }
        It 'does not call a single DNS server tolerable when the one DC known is not the forest''s only DC (the run did not cover the forest)' {
            $v = Get-AdfaDcDnsClientVerdict -DnsServers @('127.0.0.1') -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @($script:C13Ip1) -DcCount 1 -Config $script:C13Cfg
            $v.Status | Should -Be 'Not Assessed'
            $v.Detail | Should -Match 'did not count the domain controllers of the whole forest'
            (Get-AdfaDcDnsClientVerdict -DnsServers @('127.0.0.1') -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @($script:C13Ip1) -DcCount 1 -DcCountIsForest $false -Config $script:C13Cfg).Status | Should -Be 'Not Assessed'
        }
        It 'warns on a DNS server list that was returned empty, and is Not Assessed on one that was not returned' {
            (Get-AdfaDcDnsClientVerdict -DnsServers @() -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @() -DcCount 1 -Config $script:C13Cfg).Status | Should -Be 'Warning'
            $na = Get-AdfaDcDnsClientVerdict -DnsServers $null -Cause 'Not returned: x' -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @() -DcCount 2 -Config $script:C13Cfg
            $na.Status | Should -Be 'Not Assessed'
            $na.Detail | Should -Match '^Not returned'
        }
        It 'reports loopback first, no other DC and unknown resolvers as Info only (Learn publishes no rule for them)' {
            $v = Get-AdfaDcDnsClientVerdict -DnsServers @('127.0.0.1', $script:C13IpX) -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @($script:C13Ip1, $script:C13Ip2) -DcCount 2 -Config $script:C13Cfg
            $v.Status | Should -Be 'Info'
            $v.Detail | Should -Match 'itself or loopback first'
            $v.Detail | Should -Match 'no other domain controller'
            $v.Detail | Should -Match 'ISP'
            $v.Detail | Should -Not -Match ([regex]::Escape($script:C13IpX))
            $good = Get-AdfaDcDnsClientVerdict -DnsServers @($script:C13Ip2, '127.0.0.1') -SelfAddresses @($script:C13Ip1) -KnownDcAddresses @($script:C13Ip1, $script:C13Ip2) -DcCount 2 -Config $script:C13Cfg
            $good.Status | Should -Be 'Info'
            $good.Detail | Should -Not -Match 'itself or loopback first|no other domain controller|ISP'
        }
    }

    Context 'Config override: the Dns key' {
        It 'merges the statuses and the cap and rewrites provenance for exactly those keys' {
            $m = Merge-AdfaDnsConfig -BaseConfig $script:C13Cfg -Override ('{ "NonsecureStatus": "Warning", "RecordExportCap": 10 }' | ConvertFrom-Json) -OverrideSource 'C:\cfg\dns.json'
            [string]$m['NonsecureStatus'] | Should -Be 'Warning'
            [int]$m['RecordExportCap'] | Should -Be 10
            [string]$m['ThresholdSource'] | Should -Match 'dns\.json'
            [string]$m['ThresholdSource'] | Should -Match 'NonsecureStatus, RecordExportCap'
            [string]$m['ScavengingOffStatus'] | Should -Be 'Warning'
            [object]::ReferenceEquals($m['LocatorRecords'], $script:C13Cfg['LocatorRecords']) | Should -BeTrue
            [string]$script:C13Cfg['NonsecureStatus'] | Should -Be 'Fail'
        }
        It 'refuses <Name>' -ForEach @(
            @{ Name = 'an array'; Json = '[ 1, 2 ]'; Expect = 'single object' }
            @{ Name = 'a string'; Json = '"Warning"'; Expect = 'single object' }
            @{ Name = 'an empty object'; Json = '{ }'; Expect = 'empty object' }
            @{ Name = 'an unknown key'; Json = '{ "LocatorRecords": [] }'; Expect = "unknown key 'LocatorRecords'" }
            @{ Name = 'a pattern'; Json = '{ "NoRecordPattern": "." }'; Expect = "unknown key 'NoRecordPattern'" }
            @{ Name = 'a null'; Json = '{ "NonsecureStatus": null }'; Expect = 'null' }
            @{ Name = 'a status outside its set'; Json = '{ "NonsecureStatus": "Pass" }'; Expect = 'Fail, Warning' }
            @{ Name = 'Not Assessed where it is not allowed'; Json = '{ "StaleRecordStatus": "Not Assessed" }'; Expect = 'Warning, Info' }
            @{ Name = 'a status that is a number'; Json = '{ "AgingOffStatus": 1 }'; Expect = 'string' }
            @{ Name = 'a cap of zero'; Json = '{ "RecordExportCap": 0 }'; Expect = '1 to 1000000' }
            @{ Name = 'a cap above the range'; Json = '{ "RecordExportCap": 1000001 }'; Expect = '1 to 1000000' }
            @{ Name = 'a fractional cap'; Json = '{ "RecordExportCap": 1.5 }'; Expect = '1 to 1000000' }
            @{ Name = 'a quoted cap'; Json = '{ "RecordExportCap": "10" }'; Expect = 'JSON number' }
        ) {
            { Merge-AdfaDnsConfig -BaseConfig $script:C13Cfg -Override ($Json | ConvertFrom-Json) -OverrideSource 'x.json' } | Should -Throw -ExpectedMessage ("*{0}*" -f $Expect)
        }
        It 'is registered for -ConfigOverridePath, used by the four DNS sections' {
            @($script:ConfigOverrideSections.Keys) | Should -Contain 'Dns'
            $def = $script:ConfigOverrideSections['Dns']
            [string]$def['Merge'] | Should -Be 'Merge-AdfaDnsConfig'
            [string]$def['Section'] | Should -Be 'Dns'
            (@($def['AlsoUsedBy']) -join ',') | Should -Be 'DnsAdConsistency,DomainControllers,DnsRecordExport'
            $r = Resolve-AdfaConfigOverride -Override ('{ "Dns": { "OneInstrumentStatus": "Not Assessed" } }' | ConvertFrom-Json) -BaseConfig $script:Config -Sections $script:ConfigOverrideSections -OverrideSource 'x.json'
            [string]$r['Dns']['OneInstrumentStatus'] | Should -Be 'Not Assessed'
            { Resolve-AdfaConfigOverride -Override ('{ "Dns": { "RecordExportCap": -1 } }' | ConvertFrom-Json) -BaseConfig $script:Config -Sections $script:ConfigOverrideSections } | Should -Throw -ExpectedMessage "*section 'Dns'*"
        }
    }

    Context 'Raw seams: the DnsServer reads, the record read, the adapter read' {
        It 'reads the zones, ages only the primary zones that were not auto-created, and reads scavenging and forwarders' {
            $r = Get-AdfaDnsServerRaw -ComputerName $script:C13Dc1
            $r.Ok | Should -BeTrue
            # Declared population: the four zones the stub server holds.
            @($r.Zones).Count | Should -Be 4
            (@($r.Zones | ForEach-Object { [string]$_.ZoneName }) -join ',') | Should -Be 'contoso.com,_msdcs.contoso.com,0.in-addr.arpa,fabrikam.com'
            @($r.Zones)[0].IsDsIntegrated | Should -BeTrue
            [string]@($r.Zones)[0].DynamicUpdate | Should -Be 'Secure'
            (@($script:C13AgingCalls) -join ',') | Should -Be 'contoso.com,_msdcs.contoso.com'
            $r.Aging['contoso.com'].AgingEnabled | Should -BeTrue
            $r.ScavengingOk | Should -BeTrue
            Test-AdfaDnsServerScavenges -Interval $r.ScavengingInterval | Should -BeTrue
            (@($r.Forwarders) -join ',') | Should -Be $script:C13IpX
        }
        It 'returns the error and its code, not an exception, when the zone list cannot be read' {
            $script:C13ZoneAnswer = { param($c) $e = New-Object System.Exception 'Acesso negado.'; $e | Add-Member -NotePropertyName NativeErrorCode -NotePropertyValue 'AccessDenied'; throw $e }
            $r = Get-AdfaDnsServerRaw -ComputerName $script:C13Dc1
            $r.Ok | Should -BeFalse
            $r.ErrorCode | Should -Be 'AccessDenied'
            Get-AdfaDnsReadErrorClass -Message $r.Error -ErrorCode $r.ErrorCode -Config $script:C13Cfg | Should -Be 'AccessDenied'
        }
        It 'keeps the zones when only the scavenging read fails, and marks a zone whose aging read failed' {
            $script:C13ScavAnswer = { param($c) throw 'The operation has timed out.' }
            $script:C13AgingAnswer = { param($n) if ($n -eq 'contoso.com') { throw 'RPC server unavailable' }; [pscustomobject]@{ ZoneName = $n; AgingEnabled = $false } }
            $r = Get-AdfaDnsServerRaw -ComputerName $script:C13Dc1
            $r.Ok | Should -BeTrue
            $r.ScavengingOk | Should -BeFalse
            $r.ScavengingError | Should -Match 'timed out'
            $r.Aging['contoso.com'].Ok | Should -BeFalse
            $r.Aging['_msdcs.contoso.com'].AgingEnabled | Should -BeFalse
        }
        It 'tells apart access denied, no provider, time-out, no such record and any other error' {
            Get-AdfaDnsReadErrorClass -Message 'Access is denied.' -ErrorCode '' -Config $script:C13Cfg | Should -Be 'AccessDenied'
            Get-AdfaDnsReadErrorClass -Message 'Invalid namespace' -ErrorCode 'InvalidNamespace' -Config $script:C13Cfg | Should -Be 'NoProvider'
            Get-AdfaDnsReadErrorClass -Message 'The operation has timed out.' -ErrorCode '' -Config $script:C13Cfg | Should -Be 'Timeout'
            Get-AdfaDnsReadErrorClass -Message 'Failed to get the record: WIN32 9714' -ErrorCode '' -Config $script:C13Cfg | Should -Be 'NotFound'
            Get-AdfaDnsReadErrorClass -Message 'DNS record does not exist.' -ErrorCode '' -Config $script:C13Cfg | Should -Be 'NotFound'
            # A CIM NotFound code does not say what was not found: a failed read, not an absence.
            Get-AdfaDnsReadErrorClass -Message 'x' -ErrorCode 'NotFound' -Config $script:C13Cfg | Should -Be 'Error'
            Get-AdfaDnsReadErrorClass -Message 'The RPC server is unavailable.' -ErrorCode '' -Config $script:C13Cfg | Should -Be 'Error'
        }
        It 'reads a transport or domain failure that says "was not found" or "does not exist" as a failed read, never as no such record: <Message>' -ForEach @(
            @{ Message = 'The network path was not found.' }
            @{ Message = 'The specified domain either does not exist or could not be contacted.' }
            @{ Message = 'The zone contoso.com was not found on server dc1.' }
            @{ Message = 'ObjectNotFound' }
        ) {
            Get-AdfaDnsReadErrorClass -Message $Message -ErrorCode '' -Config $script:C13Cfg | Should -Be 'Error'
            $script:C13Thrown = $Message
            $script:C13RecordAnswer = { param($c, $z, $n, $t) throw $script:C13Thrown }
            $r = Get-AdfaDnsRecordSetRaw -ComputerName $script:C13Dc1 -ZoneName 'contoso.com' -Name 'dc9' -RRType 'A'
            $r.Outcome | Should -Be 'Error'
            $r.Ok | Should -BeFalse
        }
        It 'caps a record read, keeps the real count, and reads the SRV target from RecordData' {
            $script:C13RecordAnswer = { param($c, $z, $n, $t) @(1..5 | ForEach-Object { New-C13Srv '_ldap._tcp.dc' ("dc{0}.contoso.com" -f $_) }) }
            $r = Get-AdfaDnsRecordSetRaw -ComputerName $script:C13Dc1 -ZoneName '_msdcs.contoso.com' -Cap 3
            $r.Outcome | Should -Be 'Resolved'
            @($r.Records).Count | Should -Be 3
            $r.RealCount | Should -Be 5
            $r.Truncated | Should -BeTrue
            [string]@($r.Records)[0].Target | Should -Be 'dc1.contoso.com'
            [string]@($r.Records)[0].RecordData | Should -Match 'DomainName=dc1\.contoso\.com'
            $exact = Get-AdfaDnsRecordSetRaw -ComputerName $script:C13Dc1 -ZoneName '_msdcs.contoso.com' -Cap 5
            $exact.Truncated | Should -BeFalse
            @($exact.Records).Count | Should -Be 5
        }
        It 'reads a missing record as NoRecord and any other failure as Error' {
            $script:C13RecordAnswer = { param($c, $z, $n, $t) throw 'Failed to get dc9 record in contoso.com zone on server: WIN32 9714' }
            (Get-AdfaDnsRecordSetRaw -ComputerName $script:C13Dc1 -ZoneName 'contoso.com' -Name 'dc9' -RRType 'A').Outcome | Should -Be 'NoRecord'
            $script:C13RecordAnswer = { param($c, $z, $n, $t) throw 'The RPC server is unavailable.' }
            $e = Get-AdfaDnsRecordSetRaw -ComputerName $script:C13Dc1 -ZoneName 'contoso.com' -Name 'dc9' -RRType 'A'
            $e.Outcome | Should -Be 'Error'
            $e.Ok | Should -BeFalse
            $script:C13RecordAnswer = { param($c, $z, $n, $t) @() }
            (Get-AdfaDnsRecordSetRaw -ComputerName $script:C13Dc1 -ZoneName 'contoso.com' -Name 'dc9' -RRType 'A').Outcome | Should -Be 'NoRecord'
        }
        It 'finds the zone that holds a name, longest suffix first' {
            $z = Resolve-AdfaDnsZoneForName -Name '_ldap._tcp.dc._msdcs.contoso.com' -ZoneNames @('contoso.com', '_msdcs.contoso.com')
            $z.Zone | Should -Be '_msdcs.contoso.com'
            $z.Relative | Should -Be '_ldap._tcp.dc'
            (Resolve-AdfaDnsZoneForName -Name 'contoso.com' -ZoneNames @('contoso.com')).Relative | Should -Be '@'
            $null -eq (Resolve-AdfaDnsZoneForName -Name 'fabrikam.com' -ZoneNames @('contoso.com')) | Should -BeTrue
            $null -eq (Resolve-AdfaDnsZoneForName -Name 'xcontoso.com' -ZoneNames @('contoso.com')) | Should -BeTrue
        }
        It 'reads the adapters with the IPEnabled filter, the five properties and no method, and closes the session' {
            $script:C13Closed = 0
            $script:C13Cim = @()
            function New-CimSessionOption { param([string]$Protocol) [pscustomobject]@{ Protocol = $Protocol } }
            function New-CimSession { param([string]$ComputerName, $SessionOption, [uint32]$OperationTimeoutSec, [pscredential]$Credential, $ErrorAction) [pscustomobject]@{ ComputerName = $ComputerName } }
            function Remove-CimSession { param([Parameter(ValueFromRemainingArguments)]$a) $script:C13Closed++ }
            function Get-CimInstance { param($CimSession, [string]$Namespace, [string]$ClassName, [string[]]$Property, [string]$Filter, [uint32]$OperationTimeoutSec, $ErrorAction)
                $script:C13Cim += [pscustomobject]@{ ClassName = $ClassName; Filter = $Filter; Property = (@($Property) -join ',') }
                @((New-C13Adapter -Ip @($script:C13Ip1, 'fe80::1') -Dns @($script:C13Ip2, '127.0.0.1'))) }
            function Invoke-CimMethod { param([Parameter(ValueFromRemainingArguments)]$a) throw 'STUB: no method may be called' }
            $r = Get-AdfaDcNetworkRaw -ComputerName $script:C13Dc1 -Protocol 'Wsman' -OperationTimeoutSec 30
            $r.Ok | Should -BeTrue
            @($script:C13Cim).Count | Should -Be 1
            $script:C13Cim[0].ClassName | Should -Be 'Win32_NetworkAdapterConfiguration'
            $script:C13Cim[0].Filter | Should -Be 'IPEnabled = TRUE'
            $script:C13Cim[0].Property | Should -Be 'IPEnabled,IPAddress,DNSServerSearchOrder,Description,InterfaceIndex'
            (@(@($r.Adapters)[0].DNSServerSearchOrder) -join ',') | Should -Be ("{0},127.0.0.1" -f $script:C13Ip2)
            $script:C13Closed | Should -Be 1
        }
    }

    Context 'Collector: DNS Health (Get-AdfaDnsHealth)' {
        BeforeEach {
            $script:C13Raw = @{}
            $script:C13Down = @()
            $script:C13RawCalls = @()
            $script:C13Module = $true
            Mock Test-ModuleAvailable { [bool]$script:C13Module }
            Mock Test-TcpPort { $script:C13Down -notcontains [string]$ComputerName }
            Mock Get-AdfaDnsServerRaw {
                $script:C13RawCalls += [string]$ComputerName
                if ($script:C13Raw.ContainsKey([string]$ComputerName)) { return $script:C13Raw[[string]$ComputerName] }
                New-C13ServerRaw -Zones @((New-C13Zone 'contoso.com'), (New-C13Zone '_msdcs.contoso.com'))
            }
        }
        It 'grades every primary zone over the domain''s DNS servers, with one inventory row per zone per server' {
            $script:C13Raw[$script:C13Dc2] = New-C13ServerRaw -Zones @((New-C13Zone 'contoso.com' -Dyn 'NonsecureAndSecure'), (New-C13Zone '_msdcs.contoso.com'), (New-C13Zone 'fabrikam.com' -Type 'Forwarder' -Dyn 'None' -Ds $false)) -Interval ([timespan]::Zero)
            $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc2 'contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com'))
            # Declared population: two DNS servers.
            (Get-C13Like $rows 'DNS server: *').Count | Should -Be 2
            @((Get-C13Like $rows 'DNS server: *') | Where-Object { $_.Status -ne 'Info' }).Count | Should -Be 0
            $dyn = Get-C13Row $rows 'Zone dynamic update: contoso.com'
            $dyn.Count | Should -Be 1
            $dyn[0].Status | Should -Be 'Fail'
            $dyn[0].Scope | Should -Be 'contoso.com'
            $dyn[0].Zone | Should -Be 'contoso.com'
            (Get-C13Row $rows 'Zone dynamic update: _msdcs.contoso.com')[0].Status | Should -Be 'Pass'
            # dc1 scavenges, dc2 does not: one hosting server is enough.
            (Get-C13Row $rows 'Zone scavenging: contoso.com')[0].Status | Should -Be 'Pass'
            # A forwarder zone is inventoried, not graded.
            (Get-C13Row $rows 'Zone dynamic update: fabrikam.com').Count | Should -Be 0
            # Declared population: 2 zones on dc1 + 3 on dc2.
            (Get-C13Like $rows 'Zone configuration: *').Count | Should -Be 5
            @((Get-C13Like $rows 'Zone configuration: *') | Where-Object { $_.Status -ne 'Info' }).Count | Should -Be 0
            $pop = Get-C13Row $rows 'DNS zones (population): contoso.com'
            $pop[0].Status | Should -Be 'Info'
            $pop[0].Detail | Should -Match '2 of 2 DNS server'
            # The legacy rows that stay, and the two that are replaced.
            (Get-C13Like $rows '*: forwarders').Count | Should -Be 2
            (Get-C13Like $rows '*: scavenging').Count | Should -Be 0
            (Get-C13Like $rows '*: zones').Count | Should -Be 0
        }
        It 'warns when no hosting server scavenges' {
            foreach ($dc in @($script:C13Dc1, $script:C13Dc2)) { $script:C13Raw[$dc] = New-C13ServerRaw -Zones @((New-C13Zone 'contoso.com')) -Interval ([timespan]::Zero) }
            $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc2 'contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com'))
            (Get-C13Row $rows 'Zone scavenging: contoso.com')[0].Status | Should -Be 'Warning'
        }
        It 'with no DC reports Not Assessed, a row for each scoped domain, and reads nothing' {
            $rows = @(Get-AdfaDnsHealth -DomainControllers @() -Config $script:C13Cfg -ScopedDomains @('contoso.com') -EnumerationError 'STUB: ADWS unreachable')
            (Get-C13Row $rows 'DNS health')[0].Status | Should -Be 'Not Assessed'
            (Get-C13Row $rows 'DNS health')[0].Detail | Should -Match 'ADWS unreachable'
            (Get-C13Row $rows 'DNS server - contoso.com')[0].Status | Should -Be 'Not Assessed'
            @($rows | Where-Object { $_.Status -ne 'Not Assessed' }).Count | Should -Be 0
            @($script:C13RawCalls).Count | Should -Be 0
        }
        It 'reports an unreachable DC as Unreachable, reads nothing from it, and grades no zone it might host as Pass' {
            $script:C13Down = @($script:C13Dc2)
            $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc2 'contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com'))
            $two = Get-C13Row $rows ("DNS server: {0}" -f $script:C13Dc2)
            $two[0].Status | Should -Be 'Not Assessed'
            $two[0].Detail | Should -Match '^Unreachable'
            @($script:C13RawCalls) | Should -Not -Contain $script:C13Dc2
            (Get-C13Row $rows 'Zone dynamic update: contoso.com')[0].Status | Should -Be 'Not Assessed'
            (Get-C13Row $rows 'Zone scavenging: contoso.com')[0].Status | Should -Be 'Not Assessed'
        }
        It 'reports access denied as access denied, not unreachable, and a missing provider and a time-out as their own causes' {
            $script:C13Raw[$script:C13Dc1] = New-C13FailedRaw -Message 'Acesso negado.' -Code 'AccessDenied'
            $script:C13Raw[$script:C13Dc2] = New-C13FailedRaw -Message 'Invalid namespace' -Code 'InvalidNamespace'
            $script:C13Raw[$script:C13Dc3] = New-C13FailedRaw -Message 'The operation has timed out.'
            $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc2 'contoso.com'), (New-C13Target $script:C13Dc3 'north.contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com', 'north.contoso.com'))
            $one = (Get-C13Row $rows ("DNS server: {0}" -f $script:C13Dc1))[0]
            $one.Status | Should -Be 'Not Assessed'
            $one.Detail | Should -Match '^Access denied'
            $one.Detail | Should -Not -Match 'Unreachable'
            (Get-C13Row $rows ("DNS server: {0}" -f $script:C13Dc2))[0].Detail | Should -Match '^DNS provider did not answer'
            (Get-C13Row $rows ("DNS server: {0}" -f $script:C13Dc3))[0].Detail | Should -Match '^Timed out'
            (Get-C13Row $rows 'DNS zones (population): contoso.com')[0].Status | Should -Be 'Not Assessed'
            @($rows | Where-Object { $_.Status -eq 'Pass' }).Count | Should -Be 0
        }
        It 'reports the DnsServer module missing on every DC and reads nothing' {
            $script:C13Module = $false
            $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc2 'contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com'))
            $srv = Get-C13Like $rows 'DNS server: *'
            $srv.Count | Should -Be 2
            @($srv | Where-Object { $_.Status -ne 'Not Assessed' -or $_.Detail -notmatch 'DnsServer PowerShell module' }).Count | Should -Be 0
            @($script:C13RawCalls).Count | Should -Be 0
        }
        It 'reads every DC of every domain, each zone graded under its own domain (mixed: one DC denied)' {
            $script:C13Raw[$script:C13Dc2] = New-C13FailedRaw -Message 'Access is denied.'
            $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc2 'contoso.com'), (New-C13Target $script:C13Dc3 'north.contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com', 'north.contoso.com'))
            (@($script:C13RawCalls) -join ',') | Should -Be (@($script:C13Dc1, $script:C13Dc2, $script:C13Dc3) -join ',')
            $dyn = Get-C13Row $rows 'Zone dynamic update: contoso.com'
            # Declared population: the zone under each of the two domains.
            $dyn.Count | Should -Be 2
            (@($dyn | Where-Object { $_.Scope -eq 'contoso.com' }))[0].Status | Should -Be 'Not Assessed'
            (@($dyn | Where-Object { $_.Scope -eq 'north.contoso.com' }))[0].Status | Should -Be 'Pass'
            (Get-C13Row $rows 'DNS zones (population): north.contoso.com')[0].Detail | Should -Match '1 of 1 DNS server'
        }
        It 'keeps names in display columns only: a hostile zone name reaches no Detail' {
            $script:C13Raw[$script:C13Dc1] = New-C13ServerRaw -Zones @((New-C13Zone 'replication-stale.contoso.com' -Dyn 'NonsecureAndSecure'))
            $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com'))
            $r = (Get-C13Row $rows 'Zone dynamic update: replication-stale.contoso.com')[0]
            $r.Status | Should -Be 'Fail'
            $r.Detail | Should -Not -Match 'replication-stale'
            $f = ConvertTo-AdfaConsolidatedFinding -Section 'DNS Health' -Row $r -StatusColumn 'Status'
            $f.Recommendation | Should -Match 'Secure only'
            $f.Recommendation | Should -Not -Match 'repadmin'
        }
        It 'writes the zone configuration columns (INV-013) as each server reported them' {
            $script:C13Raw[$script:C13Dc1] = New-C13ServerRaw -Zones @((New-C13Zone 'contoso.com' -Dyn 'Secure' -Scope 'Domain'), (New-C13Zone '_msdcs.contoso.com' -Dyn 'NonsecureAndSecure' -Scope 'Forest'), (New-C13Zone 'legacy.contoso.com' -Ds $false -Dyn 'None' -Scope 'Legacy'))
            $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com'))
            $expected = @(
                @{ Zone = 'contoso.com'; ZoneType = 'Primary'; ReplicationScope = 'Domain'; DsIntegrated = 'True'; DynamicUpdate = 'Secure' }
                @{ Zone = '_msdcs.contoso.com'; ZoneType = 'Primary'; ReplicationScope = 'Forest'; DsIntegrated = 'True'; DynamicUpdate = 'NonsecureAndSecure' }
                @{ Zone = 'legacy.contoso.com'; ZoneType = 'Primary'; ReplicationScope = 'Legacy'; DsIntegrated = 'False'; DynamicUpdate = 'None' }
            )
            # Declared population: the three zones the one server holds.
            (Get-C13Like $rows 'Zone configuration: *').Count | Should -Be 3
            foreach ($e in $expected) {
                $r = Get-C13Row $rows ("Zone configuration: {0} on {1}" -f $e.Zone, $script:C13Dc1)
                $r.Count | Should -Be 1 -Because $e.Zone
                foreach ($col in @('Zone', 'ZoneType', 'ReplicationScope', 'DsIntegrated', 'DynamicUpdate')) { [string]$r[0].$col | Should -Be $e[$col] -Because ("{0} {1}" -f $e.Zone, $col) }
                [string]$r[0].Server | Should -Be $script:C13Dc1
                [string]$r[0].Aging | Should -Match '^AgingEnabled=True; NoRefresh=7\.00:00:00; Refresh=7\.00:00:00'
            }
        }
        It 'grades a forest-wide zone once over the DNS servers of every domain: a root DC that scavenges covers a child DC that does not' {
            $script:C13Raw[$script:C13Dc1] = New-C13ServerRaw -Zones @((New-C13Zone 'contoso.com'), (New-C13Zone '_msdcs.contoso.com' -Scope 'Forest')) -Interval ([timespan]::FromDays(7))
            $script:C13Raw[$script:C13Dc3] = New-C13ServerRaw -Zones @((New-C13Zone 'north.contoso.com'), (New-C13Zone '_msdcs.contoso.com' -Scope 'Forest')) -Interval ([timespan]::Zero)
            $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc3 'north.contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com', 'north.contoso.com'))
            $f = Get-C13Row $rows 'Zone scavenging: _msdcs.contoso.com'
            # Declared population: one row for the forest-wide zone, not one per domain.
            $f.Count | Should -Be 1
            $f[0].Status | Should -Be 'Pass'
            $f[0].Evidence | Should -Match ([regex]::Escape($script:C13Dc3))
            $f[0].ReplicationScope | Should -Be 'Forest'
            (Get-C13Row $rows 'Zone dynamic update: _msdcs.contoso.com').Count | Should -Be 1
            # The child domain's own zone is still graded under the child domain, over its server alone.
            $child = Get-C13Row $rows 'Zone scavenging: north.contoso.com'
            $child[0].Scope | Should -Be 'north.contoso.com'
            $child[0].Status | Should -Be 'Warning'
        }
        It 'does not warn "no hosting server scavenges" on a forest-wide zone unless the run covered the forest' {
            $script:C13Raw[$script:C13Dc3] = New-C13ServerRaw -Zones @((New-C13Zone '_msdcs.contoso.com' -Scope 'Forest')) -Interval ([timespan]::Zero)
            $one = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc3 'north.contoso.com')) -Config $script:C13Cfg -ScopedDomains @('north.contoso.com'))
            $r = (Get-C13Row $one 'Zone scavenging: _msdcs.contoso.com')[0]
            $r.Status | Should -Be 'Not Assessed'
            $r.Detail | Should -Match 'replication scope \(Forest\)'
            $all = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc3 'north.contoso.com')) -Config $script:C13Cfg -ScopedDomains @('north.contoso.com') -ForestComplete $true)
            (Get-C13Row $all 'Zone scavenging: _msdcs.contoso.com')[0].Status | Should -Be 'Warning'
            $failed = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc3 'north.contoso.com')) -Config $script:C13Cfg -ScopedDomains @('north.contoso.com') -ForestComplete $true -InventoryFailures @([pscustomobject]@{ Domain = 'contoso.com'; Error = 'STUB: ADWS unreachable' }))
            (Get-C13Row $failed 'Zone scavenging: _msdcs.contoso.com')[0].Status | Should -Be 'Not Assessed'
        }
        It 'never warns "no hosting server scavenges" on a zone whose replication scope does not name its servers (Legacy, or not returned)' {
            foreach ($scope in @('Legacy', '')) {
                $script:C13Raw[$script:C13Dc1] = New-C13ServerRaw -Zones @((New-C13Zone 'contoso.com' -Scope $scope)) -Interval ([timespan]::Zero)
                $rows = @(Get-AdfaDnsHealth -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com')) -Config $script:C13Cfg -ScopedDomains @('contoso.com') -ForestComplete $true)
                (Get-C13Row $rows 'Zone scavenging: contoso.com')[0].Status | Should -Be 'Not Assessed' -Because ("scope '{0}'" -f $scope)
            }
        }
    }

    Context 'Collector: DNS vs AD Consistency, the per-DC rows (Get-AdfaDnsAdConsistency)' {
        BeforeEach {
            $script:C13AdDcs = @(
                [pscustomobject]@{ HostName = $script:C13Dc1; IsReadOnly = $false; IPv4Address = $script:C13Ip1 }
                [pscustomobject]@{ HostName = $script:C13Dc2; IsReadOnly = $false; IPv4Address = $script:C13Ip2 })
            $script:C13Srv = @{ '_ldap._tcp.dc._msdcs.contoso.com' = @($script:C13Dc1, $script:C13Dc2); '_kerberos._tcp.dc._msdcs.contoso.com' = @($script:C13Dc1, $script:C13Dc2) }
            $script:C13A = @{ $script:C13Dc1 = @($script:C13Ip1); $script:C13Dc2 = @($script:C13Ip2) }
            $script:C13Resolver = 'Answer'
            $script:C13ZoneFail = @{}
            $script:C13Module = $true
            $script:C13Down = @()
            $script:C13Nics = @{ $script:C13Dc1 = @($script:C13Ip1); $script:C13Dc2 = @($script:C13Ip2) }
            $script:C13Cnames = @()
            Mock Test-ModuleAvailable { [bool]$script:C13Module }
            Mock Test-TcpPort { $script:C13Down -notcontains [string]$ComputerName }
            # The zones each server holds, with their types, in the shape Get-AdfaDnsServerZoneNames
            # returns; the NS owner names below each zone's apex (its delegations).
            $script:C13ZoneList = @{ 'contoso.com' = 'Primary'; '_msdcs.contoso.com' = 'Primary' }
            $script:C13Delegations = @{}
            $script:C13NsFail = ''
            Mock Get-AdfaDnsServerZoneNames { [pscustomobject]@{ Ok = $true; Names = @($script:C13ZoneList.Keys); Types = $script:C13ZoneList; Error = ''; ErrorCode = '' } }
            Mock Get-AdfaDnsRecordSetRaw {
                $srv = [string]$ComputerName
                if ($script:C13ZoneFail.ContainsKey($srv)) { return [pscustomobject]@{ Ok = $false; Outcome = 'Error'; Records = @(); RealCount = 0; Truncated = $false; Error = $script:C13ZoneFail[$srv]; ErrorCode = ''; ErrorId = '' } }
                if ($RRType -eq 'Ns') {
                    if ($script:C13NsFail -ne '') { return [pscustomobject]@{ Ok = $false; Outcome = 'Error'; Records = @(); RealCount = 0; Truncated = $false; Error = $script:C13NsFail; ErrorCode = ''; ErrorId = '' } }
                    $owners = @('@') + @($script:C13Delegations[[string]$ZoneName] | Where-Object { $null -ne $_ })
                    $ns = @($owners | ForEach-Object { [pscustomobject]@{ HostName = $_; RecordType = 'NS'; Target = $script:C13Dc1; RecordData = ''; TimeToLive = ''; Timestamp = '' } })
                    return [pscustomobject]@{ Ok = $true; Outcome = 'Resolved'; Records = $ns; RealCount = $ns.Count; Truncated = $false; Error = ''; ErrorCode = ''; ErrorId = '' }
                }
                $fqdn = ("{0}.{1}" -f $Name, $ZoneName)
                $recs = @()
                if ($RRType -eq 'Srv' -and $script:C13Srv.ContainsKey($fqdn)) { $recs = @($script:C13Srv[$fqdn] | ForEach-Object { [pscustomobject]@{ HostName = $Name; RecordType = 'SRV'; Target = $_; RecordData = ''; TimeToLive = ''; Timestamp = '' } }) }
                if ($RRType -eq 'A' -and $script:C13A.ContainsKey($fqdn)) { $recs = @($script:C13A[$fqdn] | ForEach-Object { [pscustomobject]@{ HostName = $Name; RecordType = 'A'; Target = $_; RecordData = ''; TimeToLive = ''; Timestamp = '' } }) }
                if ($RRType -eq 'CName') { $recs = @($script:C13Cnames | ForEach-Object { [pscustomobject]@{ HostName = $_; RecordType = 'CNAME'; Target = $script:C13Old; RecordData = ''; TimeToLive = ''; Timestamp = '' } }) }
                $outcome = 'NoRecord'
                if (@($recs).Count -gt 0) { $outcome = 'Resolved' }
                [pscustomobject]@{ Ok = $true; Outcome = $outcome; Records = @($recs); RealCount = @($recs).Count; Truncated = $false; Error = ''; ErrorCode = '' }
            }
            Mock Resolve-AdfaDnsRecord {
                if ($script:C13Resolver -eq 'NoTool') { return [pscustomobject]@{ Available = $false; Targets = @(); Error = 'Neither Resolve-DnsName nor nslookup.exe is available on this host.'; Outcome = 'NoTool' } }
                if ($script:C13Resolver -eq 'NoAnswer') { return [pscustomobject]@{ Available = $true; Targets = @(); Error = 'timeout'; Outcome = 'NoAnswer' } }
                $t = @()
                if ($Type -eq 'SRV' -and $script:C13Srv.ContainsKey($Name)) { $t = @($script:C13Srv[$Name]) }
                if ($Type -eq 'A' -and $script:C13A.ContainsKey($Name)) { $t = @($script:C13A[$Name]) }
                if (@($t).Count -gt 0) { return [pscustomobject]@{ Available = $true; Targets = $t; Error = ''; Outcome = 'Resolved' } }
                [pscustomobject]@{ Available = $true; Targets = @(); Error = 'DNS name does not exist'; Outcome = 'NoRecord' }
            }
            Mock Get-AdfaDcNetworkRaw {
                $ips = $script:C13Nics[[string]$ComputerName]
                if ($null -eq $ips) { return (New-C13NetRaw -Ok $false -Message 'Access is denied.' -Adapters @()) }
                New-C13NetRaw -Adapters @((New-C13Adapter -Ip $ips -Dns @('127.0.0.1')))
            }
            function Invoke-C13Dac { param([string[]]$Servers = @($script:C13Dc1, $script:C13Dc2), [string]$DsaError = '', $Dsa = $null, [hashtable]$Config = $script:C13Cfg)
                if ($null -eq $Dsa) { $Dsa = @([pscustomobject]@{ DsaGuid = '11111111-2222-3333-4444-555555555555'; DnsHostName = $script:C13Dc1 }, [pscustomobject]@{ DsaGuid = '21111111-2222-3333-4444-555555555555'; DnsHostName = $script:C13Dc2 }) }
                @(Get-AdfaDnsAdConsistency -DomainName 'contoso.com' -AdParams @{} -DnsServers $Servers -Config $Config -ForestRoot 'contoso.com' -DsaInventory $Dsa -DsaError $DsaError -PortTimeoutMs 50 -OperationTimeoutSec 5)
            }
        }
        It 'passes each writable DC that both instruments see on every DNS server, and its A record' {
            $rows = Invoke-C13Dac
            foreach ($dc in @($script:C13Dc1, $script:C13Dc2)) {
                (Get-C13Row $rows ("DC locator records: {0}" -f $dc))[0].Status | Should -Be 'Pass' -Because $dc
                (Get-C13Row $rows ("DC A record: {0}" -f $dc))[0].Status | Should -Be 'Pass' -Because $dc
            }
            (Get-C13Row $rows 'Stale DC records (population): contoso.com')[0].Status | Should -Be 'Pass'
            (Get-C13Like $rows 'Stale DC record: *').Count | Should -Be 0
        }
        It 'fails a DC both instruments agree is missing, and only that DC' {
            $script:C13Srv['_kerberos._tcp.dc._msdcs.contoso.com'] = @($script:C13Dc1)
            $rows = Invoke-C13Dac
            (Get-C13Row $rows ("DC locator records: {0}" -f $script:C13Dc2))[0].Status | Should -Be 'Fail'
            (Get-C13Row $rows ("DC locator records: {0}" -f $script:C13Dc1))[0].Status | Should -Be 'Pass'
        }
        It 'grades a missing record seen by the server read alone as one instrument only, never Fail' {
            $script:C13Resolver = 'NoTool'
            $script:C13Srv['_kerberos._tcp.dc._msdcs.contoso.com'] = @($script:C13Dc1)
            $rows = Invoke-C13Dac
            $two = (Get-C13Row $rows ("DC locator records: {0}" -f $script:C13Dc2))[0]
            $two.Status | Should -Be 'Warning'
            $two.Detail | Should -Match 'one instrument'
        }
        It 'excludes an RODC as Info and never lists its records as naming no DC' {
            $script:C13AdDcs = @($script:C13AdDcs + @([pscustomobject]@{ HostName = 'rodc1.contoso.com'; IsReadOnly = $true; IPv4Address = $script:C13Ip3 }))
            $script:C13Srv['_ldap._tcp.dc._msdcs.contoso.com'] = @($script:C13Dc1, $script:C13Dc2, 'rodc1.contoso.com')
            $rows = Invoke-C13Dac
            (Get-C13Row $rows 'DC locator records: rodc1.contoso.com')[0].Status | Should -Be 'Info'
            (Get-C13Like $rows 'Stale DC record: *').Count | Should -Be 0
        }
        It 'lists an SRV target that names no DC as a stale record, shown in the record columns only' {
            $script:C13Srv['_ldap._tcp.dc._msdcs.contoso.com'] = @($script:C13Dc1, $script:C13Dc2, $script:C13Old)
            $rows = Invoke-C13Dac
            $stale = Get-C13Row $rows ("Stale DC record: {0}" -f $script:C13Old)
            $stale.Count | Should -Be 1
            $stale[0].Status | Should -Be 'Warning'
            $stale[0].RecordData | Should -Be $script:C13Old
            $stale[0].Detail | Should -Not -Match ([regex]::Escape($script:C13Old))
            (Get-C13Row $rows 'Stale DC records (population): contoso.com')[0].Status | Should -Be 'Warning'
        }
        It 'lists a GUID._msdcs CNAME of no NTDS Settings object in the forest root, and judges none when no NTDS Settings object was returned' {
            $script:C13Cnames = @('11111111-2222-3333-4444-555555555555', '99999999-8888-7777-6666-555555555555')
            $rows = Invoke-C13Dac
            $stale = Get-C13Like $rows 'Stale DC record: *'
            # Declared population: the one CNAME whose GUID is no DSA (the other is dc1's).
            $stale.Count | Should -Be 1
            $stale[0].Item | Should -Be 'Stale DC record: 99999999-8888-7777-6666-555555555555._msdcs.contoso.com'
            $empty = Invoke-C13Dac -Dsa @()
            (Get-C13Like $empty 'Stale DC record: *').Count | Should -Be 0
            $pop = (Get-C13Row $empty 'Stale DC records (population): contoso.com')[0]
            $pop.Status | Should -Be 'Not Assessed'
            $pop.Detail | Should -Match 'no NTDS Settings object'
        }
        It 'is Not Assessed, never Pass, when no DNS server answered either instrument' {
            $script:C13Down = @($script:C13Dc1, $script:C13Dc2)
            $script:C13Resolver = 'NoAnswer'
            $rows = Invoke-C13Dac
            $new = @($rows | Where-Object { [string]$_.Item -match '^(DC locator records|DC A record|Stale DC records \(population\)): ' })
            # Declared population: two DCs x two rows + one population row.
            $new.Count | Should -Be 5
            @($new | Where-Object { $_.Status -ne 'Not Assessed' }).Count | Should -Be 0
            (Get-C13Row $rows ("DC locator records: {0}" -f $script:C13Dc1))[0].Evidence | Should -Match 'Unreachable'
        }
        It 'names access denied on the zone read as access denied, not as unreachable' {
            $script:C13ZoneFail[$script:C13Dc1] = 'Access is denied.'
            $script:C13ZoneFail[$script:C13Dc2] = 'Access is denied.'
            $script:C13Resolver = 'NoAnswer'
            $rows = Invoke-C13Dac
            $r = (Get-C13Row $rows ("DC locator records: {0}" -f $script:C13Dc1))[0]
            $r.Status | Should -Be 'Not Assessed'
            $r.Evidence | Should -Match 'Access denied'
            $r.Evidence | Should -Not -Match 'Unreachable'
        }
        It 'warns on an A record for an address the DC''s adapters do not hold, and is Not Assessed where the adapters were not read' {
            $script:C13A[$script:C13Dc1] = @($script:C13Ip1, $script:C13IpX)
            $script:C13Nics.Remove($script:C13Dc2)
            $rows = Invoke-C13Dac
            (Get-C13Row $rows ("DC A record: {0}" -f $script:C13Dc1))[0].Status | Should -Be 'Warning'
            $two = (Get-C13Row $rows ("DC A record: {0}" -f $script:C13Dc2))[0]
            $two.Status | Should -Be 'Not Assessed'
            $two.Detail | Should -Match 'Access denied'
        }
        It 'without any DNS server to ask, reports every per-DC row Not Assessed' {
            $rows = Invoke-C13Dac -Servers @()
            @($rows | Where-Object { [string]$_.Item -match '^(DC locator records|DC A record): ' -and $_.Status -ne 'Not Assessed' }).Count | Should -Be 0
            (Get-C13Like $rows 'DC locator records: *').Count | Should -Be 2
        }
        It 'gives the per-DC families their own advice whatever the Detail says' {
            $script:C13Srv['_kerberos._tcp.dc._msdcs.contoso.com'] = @($script:C13Dc1)
            $script:C13Srv['_ldap._tcp.dc._msdcs.contoso.com'] = @($script:C13Dc1, $script:C13Dc2, $script:C13Old)
            $rows = Invoke-C13Dac
            $loc = ConvertTo-AdfaConsolidatedFinding -Section 'DNS vs AD Consistency' -Row (Get-C13Row $rows ("DC locator records: {0}" -f $script:C13Dc2))[0] -StatusColumn 'Status'
            $loc.Recommendation | Should -Match 'Netlogon\.dns'
            $stale = ConvertTo-AdfaConsolidatedFinding -Section 'DNS vs AD Consistency' -Row (Get-C13Row $rows ("Stale DC record: {0}" -f $script:C13Old))[0] -StatusColumn 'Status'
            $stale.Recommendation | Should -Match 'stale domain controllers'
            $stale.Recommendation | Should -Not -Match 'Disable first'
        }
        It 'finds the delegation a name sits below, on a label boundary only' {
            Get-AdfaDnsDelegationPoint -Relative '_ldap._tcp.dc._msdcs.north' -Delegations @('north') | Should -Be 'north'
            Get-AdfaDnsDelegationPoint -Relative 'dc3.north' -Delegations @('_msdcs', 'north') | Should -Be 'north'
            Get-AdfaDnsDelegationPoint -Relative 'north' -Delegations @('north') | Should -Be 'north'
            Get-AdfaDnsDelegationPoint -Relative 'dc1' -Delegations @('north') | Should -Be ''
            Get-AdfaDnsDelegationPoint -Relative 'dc1.xnorth' -Delegations @('north') | Should -Be ''
            Get-AdfaDnsDelegationPoint -Relative '@' -Delegations @('north') | Should -Be ''
            Get-AdfaDnsDelegationPoint -Relative 'dc1' -Delegations @() | Should -Be ''
        }
        It 'never reads a parent zone for a name below a delegation: a child domain asked of a root DNS server is Not Assessed, not a measured absence' {
            $script:C13AdDcs = @([pscustomobject]@{ HostName = $script:C13Dc3; IsReadOnly = $false; IPv4Address = $script:C13Ip3 })
            $script:C13Nics[$script:C13Dc3] = @($script:C13Ip3)
            $script:C13Delegations['contoso.com'] = @('north')
            $script:C13Resolver = 'NoAnswer'
            $rows = @(Get-AdfaDnsAdConsistency -DomainName 'north.contoso.com' -AdParams @{} -DnsServers @($script:C13Dc1, $script:C13Dc2) -Config $script:C13Cfg -ForestRoot 'contoso.com' -DsaInventory @() -PortTimeoutMs 50 -OperationTimeoutSec 5)
            $loc = (Get-C13Row $rows ("DC locator records: {0}" -f $script:C13Dc3))[0]
            $loc.Status | Should -Be 'Not Assessed'
            $loc.Evidence | Should -Match 'below a delegation'
            (Get-C13Row $rows ("DC A record: {0}" -f $script:C13Dc3))[0].Status | Should -Be 'Not Assessed'
            (Get-C13Row $rows 'Stale DC records (population): north.contoso.com')[0].Status | Should -Be 'Not Assessed'
            Should -Invoke Get-AdfaDnsRecordSetRaw -Times 0 -Exactly -ParameterFilter { $RRType -ne 'Ns' -and $ZoneName -eq 'contoso.com' }
            # With a resolver answer "no such record", one instrument only: never Fail.
            $script:C13Resolver = 'Answer'
            Clear-AdfaDcPortCache
            $two = @(Get-AdfaDnsAdConsistency -DomainName 'north.contoso.com' -AdParams @{} -DnsServers @($script:C13Dc1, $script:C13Dc2) -Config $script:C13Cfg -ForestRoot 'contoso.com' -DsaInventory @() -PortTimeoutMs 50 -OperationTimeoutSec 5)
            (Get-C13Row $two ("DC locator records: {0}" -f $script:C13Dc3))[0].Status | Should -Be 'Warning'
            (Get-C13Row $two ("DC A record: {0}" -f $script:C13Dc3))[0].Status | Should -Be 'Warning'
        }
        It 'reads a server that holds no zone for the name, or only a stub zone, or whose delegations could not be read, as Unread: one instrument, never Fail (<Case>)' -ForEach @(
            @{ Case = 'no zone'; Zones = @{ 'fabrikam.com' = 'Primary' }; NsFail = ''; Expect = 'holds no zone for the name' }
            @{ Case = 'stub zones'; Zones = @{ 'contoso.com' = 'Stub'; '_msdcs.contoso.com' = 'Stub' }; NsFail = ''; Expect = "of type 'Stub'" }
            @{ Case = 'forwarder zone'; Zones = @{ 'contoso.com' = 'Forwarder' }; NsFail = ''; Expect = "of type 'Forwarder'" }
            @{ Case = 'zone type not returned'; Zones = @{ 'contoso.com' = ''; '_msdcs.contoso.com' = '' }; NsFail = ''; Expect = "of type 'not returned'" }
            @{ Case = 'NS read failed'; Zones = @{ 'contoso.com' = 'Primary'; '_msdcs.contoso.com' = 'Primary' }; NsFail = 'The RPC server is unavailable.'; Expect = 'NS records of the zone it holds' }
        ) {
            $script:C13ZoneList = $Zones
            $script:C13NsFail = $NsFail
            # The resolver says dc2 is not a Kdc target; the server read cannot say anything.
            $script:C13Srv['_kerberos._tcp.dc._msdcs.contoso.com'] = @($script:C13Dc1)
            $rows = Invoke-C13Dac
            $two = (Get-C13Row $rows ("DC locator records: {0}" -f $script:C13Dc2))[0]
            $two.Status | Should -Be 'Warning'
            $two.Detail | Should -Match 'one instrument'
            $two.Evidence | Should -Match ([regex]::Escape($Expect))
        }
        It 'judges no GUID._msdcs CNAME on a server whose _msdcs is delegated out of the zone it holds' {
            $script:C13ZoneList = @{ 'contoso.com' = 'Primary' }
            $script:C13Delegations['contoso.com'] = @('_msdcs')
            $script:C13Cnames = @('99999999-8888-7777-6666-555555555555')
            $rows = Invoke-C13Dac
            (Get-C13Like $rows 'Stale DC record: *').Count | Should -Be 0
            $pop = (Get-C13Row $rows 'Stale DC records (population): contoso.com')[0]
            $pop.Status | Should -Be 'Not Assessed'
            $pop.Evidence | Should -Match ("CNAME on {0}: the name sits below a delegation" -f [regex]::Escape($script:C13Dc1))
        }
        It 'lists no live DC''s record as stale when the directory returned no DC' {
            $script:C13AdDcs = @()
            $rows = Invoke-C13Dac -Dsa @()
            (Get-C13Like $rows 'Stale DC record: *').Count | Should -Be 0
            $pop = (Get-C13Row $rows 'Stale DC records (population): contoso.com')[0]
            $pop.Status | Should -Be 'Not Assessed'
            $pop.Detail | Should -Match 'No domain controller is known'
        }
        It 'grades an A record one instrument cannot find as one instrument only, and one with no readable address as Not Assessed (two DCs)' {
            $script:C13Resolver = 'NoTool'
            $script:C13A.Remove($script:C13Dc2)
            $rows = Invoke-C13Dac
            $two = (Get-C13Row $rows ("DC A record: {0}" -f $script:C13Dc2))[0]
            $two.Status | Should -Be 'Warning'
            $two.Detail | Should -Match 'one instrument only'
            (Get-C13Row $rows ("DC A record: {0}" -f $script:C13Dc1))[0].Status | Should -Be 'Pass'
            $script:C13Resolver = 'Answer'
            $script:C13A[$script:C13Dc1] = @('')
            $script:C13A[$script:C13Dc2] = @($script:C13Ip2)
            Clear-AdfaDcPortCache
            $rows2 = Invoke-C13Dac
            $one = (Get-C13Row $rows2 ("DC A record: {0}" -f $script:C13Dc1))[0]
            $one.Status | Should -Be 'Not Assessed'
            $one.Detail | Should -Match 'not compared'
            (Get-C13Row $rows2 ("DC A record: {0}" -f $script:C13Dc2))[0].Status | Should -Be 'Pass'
        }
    }

    Context 'Collector: DC DNS client (Get-AdfaDcDnsClient)' {
        BeforeEach {
            $script:C13Down = @()
            $script:C13NetAnswer = @{}
            Mock Test-TcpPort { $script:C13Down -notcontains [string]$ComputerName }
            Mock Get-AdfaDcNetworkRaw {
                if ($script:C13NetAnswer.ContainsKey([string]$ComputerName)) { return $script:C13NetAnswer[[string]$ComputerName] }
                New-C13NetRaw -Adapters @((New-C13Adapter -Ip @($script:C13Ip1) -Dns @($script:C13Ip2, '127.0.0.1')))
            }
            $script:C13Three = @((New-C13Target $script:C13Dc1 'contoso.com' $script:C13Ip1), (New-C13Target $script:C13Dc2 'contoso.com' $script:C13Ip2), (New-C13Target $script:C13Dc3 'north.contoso.com' $script:C13Ip3))
        }
        It 'reads every DC once and gives each its row and each domain a population row' {
            $rows = @(Get-AdfaDcDnsClient -DomainControllers $script:C13Three -Config $script:C13Cfg -ScopedDomains @('contoso.com', 'north.contoso.com') -PortTimeoutMs 50 -OperationTimeoutSec 5)
            $dc = Get-C13Like $rows 'DNS client: *'
            # Declared population: three DCs.
            $dc.Count | Should -Be 3
            Should -Invoke Get-AdfaDcNetworkRaw -Times 3 -Exactly
            (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc3))[0].Scope | Should -Be 'north.contoso.com'
            (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc1))[0].DnsServers | Should -Be ("{0}, 127.0.0.1" -f $script:C13Ip2)
            (Get-C13Like $rows 'DNS client (population): *').Count | Should -Be 2
        }
        It 'reports unreachable, access denied and a failed read as three causes, never Pass' {
            $script:C13Down = @($script:C13Dc1)
            $script:C13NetAnswer[$script:C13Dc2] = New-C13NetRaw -Ok $false -Message 'Acesso negado.' -Code 'AccessDenied' -Adapters @()
            $script:C13NetAnswer[$script:C13Dc3] = New-C13NetRaw -Ok $false -Message 'The RPC server is unavailable.' -Adapters @()
            $rows = @(Get-AdfaDcDnsClient -DomainControllers $script:C13Three -Config $script:C13Cfg -ScopedDomains @('contoso.com', 'north.contoso.com') -PortTimeoutMs 50 -OperationTimeoutSec 5)
            (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc1))[0].Detail | Should -Match '^Unreachable'
            (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc2))[0].Detail | Should -Match '^Access denied'
            (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc3))[0].Detail | Should -Match '^Read failed'
            @((Get-C13Like $rows 'DNS client: *') | Where-Object { $_.Status -ne 'Not Assessed' }).Count | Should -Be 0
            (Get-C13Row $rows 'DNS client (population): contoso.com')[0].Status | Should -Be 'Not Assessed'
        }
        It 'warns on a DC that points to a single DNS server in a multi-DC run (mixed with healthy DCs)' {
            $script:C13NetAnswer[$script:C13Dc2] = New-C13NetRaw -Adapters @((New-C13Adapter -Ip @($script:C13Ip2) -Dns @('127.0.0.1')))
            $rows = @(Get-AdfaDcDnsClient -DomainControllers $script:C13Three -Config $script:C13Cfg -ScopedDomains @('contoso.com', 'north.contoso.com') -PortTimeoutMs 50 -OperationTimeoutSec 5)
            (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc2))[0].Status | Should -Be 'Warning'
            (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc1))[0].Status | Should -Be 'Info'
        }
        It 'reports a read that listed no adapter, and an adapter list with no DNS server list, as Not Assessed, never as a configuration fault' {
            $script:C13NetAnswer[$script:C13Dc2] = New-C13NetRaw -Adapters @()
            $script:C13NetAnswer[$script:C13Dc3] = New-C13NetRaw -Adapters @((New-C13Adapter -Ip @($script:C13Ip3) -Dns $null))
            $state = Get-AdfaDcNetworkState -ComputerName $script:C13Dc2 -Config $script:C13Cfg -PortTimeoutMs 50 -OperationTimeoutSec 5
            $state.Status | Should -Be 'Error'
            $state.Cause | Should -Match '^Read returned no adapter'
            $null -eq (Get-AdfaDcNetworkState -ComputerName $script:C13Dc3 -Config $script:C13Cfg -PortTimeoutMs 50 -OperationTimeoutSec 5).DnsServers | Should -BeTrue
            $rows = @(Get-AdfaDcDnsClient -DomainControllers $script:C13Three -Config $script:C13Cfg -ScopedDomains @('contoso.com', 'north.contoso.com') -PortTimeoutMs 50 -OperationTimeoutSec 5)
            $two = (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc2))[0]
            $two.Status | Should -Be 'Not Assessed'
            $two.Detail | Should -Match '^Read returned no adapter'
            $three = (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc3))[0]
            $three.Status | Should -Be 'Not Assessed'
            $three.Detail | Should -Match '^Not returned'
            $three.ConfiguredIPv4 | Should -Be $script:C13Ip3
            (Get-C13Row $rows ("DNS client: {0}" -f $script:C13Dc1))[0].Status | Should -Be 'Info'
            (Get-C13Row $rows 'DNS client (population): contoso.com')[0].Status | Should -Be 'Not Assessed'
        }
        It 'calls a single DNS server on the only DC tolerable only when the run covered the whole forest' {
            $solo = @((New-C13Target $script:C13Dc1 'contoso.com' $script:C13Ip1))
            $script:C13NetAnswer[$script:C13Dc1] = New-C13NetRaw -Adapters @((New-C13Adapter -Ip @($script:C13Ip1) -Dns @('127.0.0.1')))
            $part = @(Get-AdfaDcDnsClient -DomainControllers $solo -Config $script:C13Cfg -ScopedDomains @('contoso.com') -PortTimeoutMs 50 -OperationTimeoutSec 5)
            (Get-C13Row $part ("DNS client: {0}" -f $script:C13Dc1))[0].Status | Should -Be 'Not Assessed'
            $whole = @(Get-AdfaDcDnsClient -DomainControllers $solo -Config $script:C13Cfg -ScopedDomains @('contoso.com') -ForestComplete $true -PortTimeoutMs 50 -OperationTimeoutSec 5)
            (Get-C13Row $whole ("DNS client: {0}" -f $script:C13Dc1))[0].Status | Should -Be 'Info'
            $gap = @(Get-AdfaDcDnsClient -DomainControllers $solo -Config $script:C13Cfg -ScopedDomains @('contoso.com', 'north.contoso.com') -ForestComplete $true -InventoryFailures @([pscustomobject]@{ Domain = 'north.contoso.com'; Error = 'STUB: ADWS unreachable' }) -PortTimeoutMs 50 -OperationTimeoutSec 5)
            (Get-C13Row $gap ("DNS client: {0}" -f $script:C13Dc1))[0].Status | Should -Be 'Not Assessed'
        }
        It 'with no DC reports Not Assessed, with a row for each scoped domain' {
            $rows = @(Get-AdfaDcDnsClient -DomainControllers @() -Config $script:C13Cfg -ScopedDomains @('contoso.com') -InventoryFailures @([pscustomobject]@{ Domain = 'contoso.com'; Error = 'STUB: ADWS unreachable' }))
            (Get-C13Row $rows 'DNS client')[0].Status | Should -Be 'Not Assessed'
            (Get-C13Row $rows 'DNS client - contoso.com')[0].Detail | Should -Match 'ADWS unreachable'
            @($rows | Where-Object { $_.Status -ne 'Not Assessed' }).Count | Should -Be 0
        }
    }

    Context 'Collector: DNS record export (Export-AdfaDnsRecord, opt-in)' {
        BeforeEach {
            $script:C13Down = @()
            $script:C13Module = $true
            Mock Test-ModuleAvailable { [bool]$script:C13Module }
            Mock Test-TcpPort { $script:C13Down -notcontains [string]$ComputerName }
            Mock Get-AdfaDnsServerZoneNames { [pscustomobject]@{ Ok = $true; Names = @('contoso.com', '_msdcs.contoso.com'); Error = ''; ErrorCode = '' } }
            Mock Get-AdfaDnsRecordSetRaw {
                $n = 2
                if ($ZoneName -eq 'contoso.com') { $n = 5 }
                $all = @(1..$n | ForEach-Object { [pscustomobject]@{ HostName = ("host{0}" -f $_); RecordType = 'A'; TimeToLive = '00:20:00'; Timestamp = ''; RecordData = ('IPv4Address=192.0.2.{0}' -f $_); Target = ('192.0.2.{0}' -f $_) } })
                $keep = @($all | Select-Object -First $Cap)
                [pscustomobject]@{ Ok = $true; Outcome = 'Resolved'; Records = $keep; RealCount = $n; Truncated = ($n -gt $Cap); Error = ''; ErrorCode = '' }
            }
            $script:C13Csv = Join-Path $TestDrive ([guid]::NewGuid().ToString('N'))
            New-Item -ItemType Directory -Path $script:C13Csv | Out-Null
        }
        It 'writes one capped CSV per zone and server, and says how many were exported and whether the cap was hit' {
            $cfg = Merge-AdfaDnsConfig -BaseConfig $script:C13Cfg -Override @{ RecordExportCap = 3 } -OverrideSource 'x.json'
            $rows = @(Export-AdfaDnsRecord -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc2 'contoso.com')) -Config $cfg -CsvPath $script:C13Csv -ScopedDomains @('contoso.com'))
            $files = @(Get-ChildItem -LiteralPath $script:C13Csv -Filter 'DnsRecords_*.csv')
            # Declared population: two zones on two servers.
            $files.Count | Should -Be 4
            $big = @(Import-Csv -LiteralPath (Join-Path $script:C13Csv ('DnsRecords_{0}_{1}.csv' -f (New-SafeFileName $script:C13Dc1), (New-SafeFileName 'contoso.com'))))
            $big.Count | Should -Be 3
            $z = (Get-C13Row $rows ("Record export: contoso.com on {0}" -f $script:C13Dc1))[0]
            $z.Status | Should -Be 'Info'
            $z.Detail | Should -Match 'Exported 3 of 5'
            $z.Detail | Should -Match 'cap reached: yes'
            (Get-C13Row $rows ("Record export: _msdcs.contoso.com on {0}" -f $script:C13Dc1))[0].Detail | Should -Match 'cap reached: no'
            $total = (Get-C13Row $rows 'Record export: total')[0]
            $total.Detail | Should -Match '^10 record\(s\) exported'
            $total.Detail | Should -Match 'cap reached in 2'
        }
        It 'reports an unreachable server and a missing module as Not Assessed, writing nothing for them' {
            $script:C13Down = @($script:C13Dc2)
            $rows = @(Export-AdfaDnsRecord -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc2 'contoso.com')) -Config $script:C13Cfg -CsvPath $script:C13Csv -ScopedDomains @('contoso.com'))
            (Get-C13Row $rows ("Record export (population): {0}" -f $script:C13Dc2))[0].Status | Should -Be 'Not Assessed'
            @(Get-ChildItem -LiteralPath $script:C13Csv -Filter ('DnsRecords_{0}_*' -f (New-SafeFileName $script:C13Dc2))).Count | Should -Be 0
            $script:C13Module = $false
            $none = @(Export-AdfaDnsRecord -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com')) -Config $script:C13Cfg -CsvPath $script:C13Csv -ScopedDomains @('contoso.com'))
            @($none | Where-Object { $_.Status -ne 'Not Assessed' }).Count | Should -Be 0
        }
        It 'makes a server''s population row Not Assessed when one of its zones could not be read, and keeps the other server Info' {
            Mock Get-AdfaDnsRecordSetRaw {
                if ([string]$ComputerName -eq $script:C13Dc1 -and $ZoneName -eq '_msdcs.contoso.com') { return [pscustomobject]@{ Ok = $false; Outcome = 'Error'; Records = @(); RealCount = 0; Truncated = $false; Error = 'Access is denied.'; ErrorCode = ''; ErrorId = '' } }
                $all = @([pscustomobject]@{ HostName = 'host1'; RecordType = 'A'; TimeToLive = '00:20:00'; Timestamp = ''; RecordData = 'IPv4Address=192.0.2.1'; Target = '192.0.2.1' })
                [pscustomobject]@{ Ok = $true; Outcome = 'Resolved'; Records = $all; RealCount = 1; Truncated = $false; Error = ''; ErrorCode = ''; ErrorId = '' }
            }
            $rows = @(Export-AdfaDnsRecord -DomainControllers @((New-C13Target $script:C13Dc1 'contoso.com'), (New-C13Target $script:C13Dc2 'contoso.com')) -Config $script:C13Cfg -CsvPath $script:C13Csv -ScopedDomains @('contoso.com'))
            $failedZone = (Get-C13Row $rows ("Record export: _msdcs.contoso.com on {0}" -f $script:C13Dc1))[0]
            $failedZone.Status | Should -Be 'Not Assessed'
            $failedZone.Detail | Should -Match '^Access denied'
            $one = (Get-C13Row $rows ("Record export (population): {0}" -f $script:C13Dc1))[0]
            $one.Status | Should -Be 'Not Assessed'
            $one.Detail | Should -Match '1 exported, 1 not read'
            (Get-C13Row $rows ("Record export (population): {0}" -f $script:C13Dc2))[0].Status | Should -Be 'Info'
        }
    }

    Context 'Recommendations' {
        It 'gives each graded family its own advice, which says this tool changes nothing, whatever the Detail says' {
            $cases = @(
                @{ Section = 'DNS Health'; Item = 'Zone dynamic update: contoso.com'; Expect = 'Secure only' }
                @{ Section = 'DNS Health'; Item = 'Zone scavenging: contoso.com'; Expect = 'only one DNS server per zone' }
                @{ Section = 'DNS vs AD Consistency'; Item = ("DC locator records: {0}" -f $script:C13Dc1); Expect = 'Netlogon\.dns' }
                @{ Section = 'DNS vs AD Consistency'; Item = ("DC A record: {0}" -f $script:C13Dc1); Expect = 'host record' }
                @{ Section = 'DNS vs AD Consistency'; Item = ("Stale DC record: {0}" -f $script:C13Old); Expect = 'stale domain controllers' }
                @{ Section = 'DC DNS Client'; Item = ("DNS client: {0}" -f $script:C13Dc1); Expect = 'single point of failure' }
            )
            # Declared population: the six families that can be Warning or Fail.
            $cases.Count | Should -Be 6
            foreach ($c in $cases) {
                $rec = Get-AdfaRecommendation -Section $c.Section -Item $c.Item -Detail $script:C13Hostile
                $rec | Should -Match $c.Expect -Because $c.Item
                $rec | Should -Match 'changes nothing' -Because $c.Item
            }
        }
        It 'gives the inventory and population families no advice' {
            foreach ($c in @(@('DNS Health', 'DNS server: dc1.contoso.com'), @('DNS Health', 'Zone configuration: contoso.com on dc1.contoso.com'), @('DNS Health', 'DNS zones (population): contoso.com'),
                    @('DNS vs AD Consistency', 'Stale DC records (population): contoso.com'), @('DC DNS Client', 'DNS client (population): contoso.com'), @('DNS Record Export', 'Record export: total'))) {
                Get-AdfaRecommendation -Section $c[0] -Item $c[1] -Detail $script:C13Hostile | Should -Be '' -Because $c[1]
            }
        }
        It 'leaves the existing DNS Health and DNS vs AD rows on the advice they had' {
            Get-AdfaRecommendation -Section 'DNS Health' -Item 'dc1.contoso.com: zone transfer' -Detail 'Zones allowing transfer to ANY server: 1' | Should -Match 'Restrict zone transfers'
            Get-AdfaRecommendation -Section 'DNS vs AD Consistency' -Item 'SRV _ldap._tcp.dc._msdcs.contoso.com on dc1.contoso.com' -Detail 'missing (DC in AD, not advertised): dc2.contoso.com' | Should -Match 'nltest /dsregdns'
        }
        It 'sits ahead of the first unscoped entry' {
            $map = @($script:RecommendationMap)
            $firstUnscoped = -1
            for ($i = 0; $i -lt $map.Count; $i++) { if (-not $map[$i].ContainsKey('Section')) { $firstUnscoped = $i; break } }
            $mine = @(for ($i = 0; $i -lt $map.Count; $i++) { if ($map[$i].ContainsKey('Section') -and [string]$map[$i].Section -match 'dns health|dns vs ad|dc dns client|dns record export') { $i } })
            # Declared population: two DNS Health families and their catch-all, three DNS vs AD families
            # and their catch-all, the DNS client family and its catch-all, the export catch-all.
            $mine.Count | Should -Be 10
            @($mine | Where-Object { $_ -gt $firstUnscoped }).Count | Should -Be 0
        }
    }

    Context 'Wiring and read-only guard' {
        It 'adds DnsRecordExport to -Sections, outside the default All run' {
            $p = @($script:C13Ast.ParamBlock.Parameters | Where-Object { $_.Name.VariablePath.UserPath -eq 'Sections' })
            $vs = @($p[0].Attributes | Where-Object { $_.TypeName.Name -eq 'ValidateSet' })
            $values = @($vs[0].PositionalArguments | ForEach-Object { [string]$_.Value })
            $values | Should -Contain 'DnsRecordExport'
            $values | Should -Contain 'Dns'
            $branches = @(Get-C13Branch "`$Sections -contains 'DnsRecordExport'")
            $branches.Count | Should -Be 1
            @(Get-C13Branch "Test-SectionSelected 'DnsRecordExport' `$Sections").Count | Should -Be 0
            $calls = @($branches[0].Clauses[0].Item2.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq 'Export-AdfaDnsRecord' }, $true))
            $calls.Count | Should -Be 1
            (Get-C13Parameter -Call $calls[0] -Name 'Config').Extent.Text | Should -Be '$dnsConfig'
            (Get-C13Parameter -Call $calls[0] -Name 'CsvPath').Extent.Text | Should -Be '$csvPath'
            $assign = @($branches[0].Clauses[0].Item2.FindAll({ param($n) $n -is [System.Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -eq "`$sectionData['DNS Record Export']" }, $true))
            $assign.Count | Should -Be 1
        }
        It 'gives the Dns, DnsAdConsistency and DomainControllers branches the DNS config, the targets and the causes' {
            $expected = @(
                @{ Cond = "Test-SectionSelected 'Dns' `$Sections"; Call = 'Get-AdfaDnsHealth'; Key = "`$sectionData['DNS Health']"; Params = @{ Config = '$dnsConfig'; DomainControllers = '$dnsTargets'; InventoryFailures = '$dnsFailures'; EnumerationError = '$script:DcEnumerationError'; ScopedDomains = '$targetDomains'; ForestComplete = '$dnsForestComplete' } }
                @{ Cond = "Test-SectionSelected 'DnsAdConsistency' `$Sections"; Call = 'Get-AdfaDnsAdConsistency'; Key = "`$sectionData['DNS vs AD Consistency']"; Params = @{ Config = '$dnsConfig'; DsaInventory = '$dnsDsa'; DsaError = '$dnsDsaError'; ForestRoot = '$rootDomain'; DnsServers = '$dcNames' } }
                @{ Cond = "Test-SectionSelected 'DomainControllers' `$Sections"; Call = 'Get-AdfaDcDnsClient'; Key = "`$sectionData['DC DNS Client']"; Params = @{ Config = '$dnsConfig'; DomainControllers = '$inv'; InventoryFailures = '$dcInventoryFailures'; ScopedDomains = '$targetDomains'; ForestComplete = '$scopeCoversForest' } }
            )
            # The forest-coverage flag both take is computed once, from the forest's domains against
            # the scoped ones, and the DNS Health copy is cleared when it falls back to bare host names.
            $cover = @($script:C13Main[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -eq '$scopeCoversForest' }, $true))
            $cover.Count | Should -Be 1
            $cover[0].Right.Extent.Text | Should -Match '\$forestDomainList'
            $cover[0].Right.Extent.Text | Should -Match '\$scopedDomainList'
            $fallback = @($script:C13Main[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -eq '$dnsForestComplete' }, $true))
            # Declared population: the copy of the flag, then the fallback that clears it.
            $fallback.Count | Should -Be 2
            $fallback[1].Right.Extent.Text | Should -Be '$false'
            # Declared population: the three existing sections C13 extends.
            $expected.Count | Should -Be 3
            foreach ($e in $expected) {
                $b = @(Get-C13Branch $e.Cond)
                $b.Count | Should -Be 1 -Because $e.Cond
                $calls = @($b[0].Clauses[0].Item2.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq $e.Call }, $true))
                $calls.Count | Should -Be 1 -Because $e.Call
                foreach ($k in @($e.Params.Keys)) {
                    $given = Get-C13Parameter -Call $calls[0] -Name $k
                    $given | Should -Not -BeNullOrEmpty -Because ("{0} -{1}" -f $e.Call, $k)
                    $given.Extent.Text | Should -Be $e.Params[$k] -Because ("{0} -{1}" -f $e.Call, $k)
                }
                @($b[0].Clauses[0].Item2.FindAll({ param($n) $n -is [System.Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -eq $e.Key }, $true)).Count | Should -Be 1 -Because $e.Key
            }
            $cfgAssigns = @($script:C13Main[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -eq '$dnsConfig' }, $true))
            # Declared population: the built-in table, then the override.
            $cfgAssigns.Count | Should -Be 2
            $cfgAssigns[0].Right.Extent.Text | Should -Be '$script:Config.Dns'
            $cfgAssigns[1].Right.Extent.Text | Should -Be "`$configOverrides['Dns']"
            $guard = $cfgAssigns[1].Parent
            while ($null -ne $guard -and $guard -isnot [System.Management.Automation.Language.IfStatementAst]) { $guard = $guard.Parent }
            $guard.Clauses[0].Item1.Extent.Text | Should -Be "`$configOverrides.ContainsKey('Dns')"
        }
        It 'reads the adapters through the shared transport loop, which now knows the network seam' {
            $loop = @(Get-C13Function 'Invoke-AdfaDcRemoteRead')
            $readParam = @($loop[0].Body.ParamBlock.Parameters | Where-Object { $_.Name.VariablePath.UserPath -eq 'ReadCommand' })
            $allowed = @($readParam[0].Attributes | Where-Object { $_.TypeName.Name -eq 'ValidateSet' })
            (@($allowed[0].PositionalArguments | ForEach-Object { [string]$_.Value } | Sort-Object) -join ',') | Should -Be 'Get-AdfaDcDiskRaw,Get-AdfaDcHardeningRaw,Get-AdfaDcNetworkRaw'
            $state = @(Get-C13Function 'Get-AdfaDcNetworkState')
            @($state[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq 'Invoke-AdfaDcRemoteRead' }, $true)).Count | Should -Be 1
            @($state[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq 'Test-TcpPort' }, $true)).Count | Should -Be 0
        }
        It 'calls no command that changes DNS, DNS registration or an adapter, anywhere in the script' {
            $cmds = @($script:C13Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true))
            # Non-vacuity: the read cmdlets are there to be found, and so is the way the script starts
            # console tools (Invoke-ExternalCommand -FilePath 'nltest.exe'), which the guard must see.
            @($cmds | Where-Object { [string]$_.GetCommandName() -eq 'Get-DnsServerZone' }).Count | Should -BeGreaterThan 0
            @($cmds | Where-Object { [string]$_.GetCommandName() -eq 'Get-DnsServerResourceRecord' }).Count | Should -BeGreaterThan 0
            @($cmds | Where-Object { [string]$_.GetCommandName() -eq 'Invoke-ExternalCommand' -and $_.Extent.Text -match "-FilePath 'nltest\.exe'" }).Count | Should -BeGreaterThan 0
            $hits = Get-C13WriteHit -Ast $script:C13Ast
            ($hits -join ' | ') | Should -Be ''
            $adapterMethod = @($cmds | Where-Object { [string]$_.GetCommandName() -eq 'Invoke-CimMethod' -and $_.Extent.Text -match '(?i)NetworkAdapterConfiguration' })
            $adapterMethod.Count | Should -Be 0
            $net = @(Get-C13Function 'Get-AdfaDcNetworkRaw')
            @($net[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq 'Invoke-CimMethod' }, $true)).Count | Should -Be 0
        }
        It 'the read-only guard fails on a write started the way the script starts console tools: <Name>' -ForEach @(
            @{ Name = 'nltest /dsregdns through Invoke-ExternalCommand'; Code = "function Invoke-C13Injected { Invoke-ExternalCommand -FilePath 'nltest.exe' -Arguments '/dsregdns' }" }
            @{ Name = 'ipconfig /registerdns through Invoke-ExternalCommand'; Code = "function Invoke-C13Injected { Invoke-ExternalCommand -FilePath 'ipconfig.exe' -Arguments '/registerdns' }" }
            @{ Name = 'dnscmd through Invoke-ExternalCommand'; Code = "function Invoke-C13Injected { Invoke-ExternalCommand -FilePath 'dnscmd.exe' -Arguments '/config contoso.com /allowupdate 1' }" }
            @{ Name = 'a switch held in a variable'; Code = "function Invoke-C13Injected { `$a = '/dsderegdns:old-dc.contoso.com'; Invoke-ExternalCommand -FilePath 'nltest.exe' -Arguments `$a }" }
            @{ Name = 'the call operator'; Code = "function Invoke-C13Injected { & 'ipconfig.exe' /flushdns }" }
            @{ Name = 'a DnsServer write cmdlet'; Code = "function Invoke-C13Injected { Set-DnsServerPrimaryZone -Name 'contoso.com' -DynamicUpdate Secure }" }
        ) {
            $ast = [System.Management.Automation.Language.Parser]::ParseInput($Code, [ref]$null, [ref]$null)
            # Not wrapped in @(): the helper returns its list as one array, so @() would count 1 for none.
            $hits = Get-C13WriteHit -Ast $ast
            $hits.Count | Should -BeGreaterThan 0
            ($hits -join ' | ') | Should -Not -Be ''
        }
        It 'the read-only guard leaves advice text in the recommendation map alone, and only there' {
            $inMap = [System.Management.Automation.Language.Parser]::ParseInput("`$script:RecommendationMap = @( @{ Match = 'x'; Text = 'Run ""ipconfig /registerdns"" and ""nltest /dsregdns"".' } )", [ref]$null, [ref]$null)
            $none = Get-C13WriteHit -Ast $inMap
            $none.Count | Should -Be 0
            $outside = [System.Management.Automation.Language.Parser]::ParseInput("`$advice = 'Run ""ipconfig /registerdns"".'", [ref]$null, [ref]$null)
            $one = Get-C13WriteHit -Ast $outside
            $one.Count | Should -Be 1
            [string]$one[0] | Should -Match '^switch: '
        }
        It 'grades dynamic update in DNS Health only: DnsDepth no longer reads a zone' {
            $depth = @(Get-C13Function 'Get-AdfaDnsDepth')
            @($depth[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and $n.GetCommandName() -eq 'Get-DnsServerZone' }, $true)).Count | Should -Be 0
            # No query tool, so no real resolver is asked for a fictional name.
            Mock Test-CommandAvailable { $false }
            $rows = @(Get-AdfaDnsDepth -DomainName 'contoso.com' -DomainControllers @($script:C13Dc1))
            $sec = Get-C13Row $rows 'Secure dynamic updates'
            $sec.Count | Should -Be 1
            $sec[0].Status | Should -Be 'Info'
            $sec[0].Detail | Should -Match 'Zone dynamic update'
        }
        It 'documents the new section, the override key and the four DNS reads in the help and the README' {
            $help = $script:C13Ast.GetHelpContent()
            ([string]$help.Parameters['SECTIONS'] -replace '\s+', ' ') | Should -Match 'DnsRecordExport'
            ([string]$help.Parameters['CONFIGOVERRIDEPATH'] -replace '\s+', ' ') | Should -Match 'Sixteen sections can be named'
            ([string]$help.Parameters['CONFIGOVERRIDEPATH'] -replace '\s+', ' ') | Should -Match 'Dns, whose keys are'
            $readme = @(Get-Content -LiteralPath (Join-Path $script:RepoRoot 'README.md'))
            @($readme | Where-Object { $_ -match '^\| DNS record export \|' }).Count | Should -Be 1
            @($readme | Where-Object { $_ -match '^\| DNS \|' -and $_ -match 'Secure only' -and $_ -match 'scavenging' }).Count | Should -Be 1
        }
    }
}

Describe 'Reachability classes, subnets and clients without a site, clock offset against the forest root PDC, stale enabled objects, SYSVOL replication engine (C14)' {
    # PORT-PLAN C14: catalogue REACH-001..002, SITE-001, TIME-001, STALE-001..002, SYSVOL-004, built into
    # the existing sections PortMatrix ('Port Reachability'), Topology ('Site Health'), TimeHierarchy
    # ('Time Hierarchy'), StaleObjects ('Stale Objects') and Sysvol ('SYSVOL / DFSR'). Every name and
    # address below is fictional (contoso, fabrikam, 192.0.2.0/24, 198.51.100.0/24) and held in a variable
    # (PSAvoidUsingComputerNameHardcoded).
    BeforeAll {
        $script:C14Dc1 = 'dc1.contoso.com'
        $script:C14Dc2 = 'dc2.contoso.com'
        $script:C14Dc3 = 'dc3.north.contoso.com'
        $script:C14Pdc = 'dc1.contoso.com'
        $script:C14Ip1 = '192.0.2.21'
        $script:C14Ip2 = '192.0.2.22'
        $script:C14Ip3 = '198.51.100.23'
        $script:C14Client = '198.51.100.77'
        $script:C14Now = [datetime]::SpecifyKind([datetime]'2026-11-17 12:00:00', [System.DateTimeKind]::Utc)
        $script:C14Hostile = 'replication stale delegation secure dynamic zone transfer scavenging aging no a record does not resolve port 389 not reachable global catalog backup dcdiag NOT a pass log coverage pdc emulator missing from dns time sync clock skew w32tm sysvol dfsr inactive C:\Backup\stale.json'
        $script:C14Functions = @('Merge-AdfaSpecConfig', 'Resolve-AdfaHostAddress', 'Test-AdfaTcpAddress', 'Get-AdfaProbeClass', 'Resolve-AdfaDcReachClass',
            'Get-AdfaDcReachability', 'Get-AdfaDcReachRecord', 'Get-AdfaDcReachCause', 'Get-AdfaDcReachVerdict', 'Get-AdfaDcReachabilityRows',
            'Get-AdfaSubnetSiteVerdict', 'Get-AdfaNetlogonLogRaw', 'ConvertFrom-AdfaNetlogonNoClientSite', 'Get-AdfaNoClientSiteVerdict', 'Get-AdfaClientSiteRows',
            'Get-AdfaStripchartSample', 'Get-AdfaPdcClockOffsetVerdict', 'Get-AdfaStaleLdapFilter', 'Get-AdfaStaleRaw', 'Get-AdfaLogonSyncIntervalRaw',
            'Get-AdfaStaleCountVerdict', 'Get-AdfaPasswordAgeVerdict', 'Get-AdfaDirectoryObjectState', 'Get-AdfaSysvolEngineRaw',
            'Resolve-AdfaSysvolEngineDc', 'Get-AdfaSysvolEngineVerdict', 'New-AdfaC14Row', 'Get-AdfaStalePopulationRaw', 'Get-AdfaC14PopulationText')
        function New-C14Resolve { param([bool]$Ok = $true, [string[]]$Addresses = @('192.0.2.21'), [string]$SocketError = '', [bool]$TimedOut = $false, [string]$ErrorText = '')
            [pscustomobject]@{ Ok = $Ok; Addresses = @($Addresses); SocketError = $SocketError; TimedOut = $TimedOut; Error = $ErrorText } }
        function New-C14Probe { param([string]$Outcome = 'Open', [string]$SocketError = '', [bool]$TimedOut = $false)
            [pscustomobject]@{ Outcome = $Outcome; SocketError = $SocketError; TimedOut = $TimedOut; Error = '' } }
        function New-C14Target { param([string]$HostName, [string]$Scope)
            [pscustomobject]@{ HostName = $HostName; Scope = $Scope; Site = 'HQ'; IsReadOnly = $false } }
        # The comma keeps a one-row answer an array, so .Count works under StrictMode on Windows PowerShell 5.1.
        function Get-C14Row { param($Rows, [string]$Item) return , @($Rows | Where-Object { $null -ne $_ -and $null -ne $_.PSObject.Properties['Item'] -and [string]$_.Item -eq $Item }) }
        function New-C14Sample { param([double[]]$Offsets = @(), [double[]]$Delays = @(), [bool]$Queried = $true, [string]$ErrorText = '')
            [pscustomobject]@{ Queried = $Queried; Offsets = @($Offsets); Delays = @($Delays); Error = $ErrorText } }
        function New-C14Account { param([string]$Name, $LastLogonUtc = $null, $WhenCreatedUtc = $null)
            [pscustomobject]@{ Name = $Name; HasLastLogon = ($null -ne $LastLogonUtc); LastLogonUtc = $LastLogonUtc; WhenCreatedUtc = $WhenCreatedUtc; PwdLastSetRaw = $null } }
        function New-C14StaleRaw { param($Records = @(), [bool]$Ok = $true, [string]$ErrorText = '', [string]$ErrorType = '', [bool]$Capped = $false)
            [pscustomobject]@{ Ok = $Ok; Error = $ErrorText; ErrorType = $ErrorType; Records = @($Records); Capped = $Capped; Filter = '(x)'; Properties = @('sAMAccountName') } }
        # The declared population of a stale row, in the shape Get-AdfaStalePopulationRaw returns.
        function New-C14Population { param([bool]$Ok = $true, [int]$Count = 50, [bool]$Capped = $false, [string]$ErrorText = '', [string]$ErrorType = '')
            [pscustomobject]@{ Ok = $Ok; Count = $Count; Capped = $Capped; Error = $ErrorText; ErrorType = $ErrorType; Filter = '(x)' } }
        # One password record, in the shape Get-AdfaStaleRaw returns for -Kind Password.
        function New-C14PwdRecord { param([string]$Name, $PwdLastSetRaw, $UserAccountControl = 512)
            [pscustomobject]@{ Name = $Name; HasLastLogon = $false; LastLogonUtc = $null; WhenCreatedUtc = $null; PwdLastSetRaw = $PwdLastSetRaw; UserAccountControl = $UserAccountControl } }
        function New-C14Interval { param([bool]$Ok = $true, [bool]$Present = $false, $Value = $null, [string]$ErrorText = '')
            [pscustomobject]@{ Ok = $Ok; Present = $Present; Value = $Value; Error = $ErrorText } }
        function New-C14EngineDc { param([string]$HostName, [string]$Dfsr = 'Present', [string]$Frs = 'Absent', $IsReadOnly = $false, [string]$DfsrError = '', [string]$FrsError = '')
            [pscustomobject]@{ HostName = $HostName; IsReadOnly = $IsReadOnly; ComputerDn = ("CN={0},OU=Domain Controllers,DC=contoso,DC=com" -f $HostName.Split('.')[0]); Dfsr = $Dfsr; DfsrError = $DfsrError; Frs = $Frs; FrsError = $FrsError } }
        function New-C14EngineRaw { param($Dcs = @(), [bool]$Ok = $true, [string]$ErrorText = '', [string]$ErrorType = '', [string]$Global = 'Present', $Flags = 48, [string]$GlobalError = '')
            [pscustomobject]@{ Ok = $Ok; Error = $ErrorText; ErrorType = $ErrorType; DomainDn = 'DC=contoso,DC=com'; GlobalState = $Global; GlobalFlags = $Flags; GlobalError = $GlobalError; Dcs = @($Dcs) } }
        if ($null -eq ('Contoso.Stub.ADIdentityNotFoundException' -as [type])) {
            Add-Type -TypeDefinition 'namespace Contoso.Stub { public class ADIdentityNotFoundException : System.Exception { public ADIdentityNotFoundException(string m) : base(m) { } } }' -WarningAction SilentlyContinue
        }
        $script:C14Ast = [System.Management.Automation.Language.Parser]::ParseFile($script:Target, [ref]$null, [ref]$null)
        $script:C14Main = @($script:C14Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'Invoke-Main' }, $true))
        function Get-C14Function { param([string]$Name) @($script:C14Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq $Name }, $true)) }
        function Get-C14Branch { param([string]$Condition)
            @($script:C14Main[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.IfStatementAst] -and $n.Clauses[0].Item1.Extent.Text -eq $Condition }, $true)) }
        function Get-C14Call { param($Ast, [string]$Name)
            @($Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] -and [string]$n.GetCommandName() -eq $Name }, $true)) }
        function Get-C14Parameter { param($Call, [string]$Name)
            $elements = @($Call.CommandElements)
            for ($i = 0; $i -lt $elements.Count; $i++) {
                $e = $elements[$i]
                if ($e -is [System.Management.Automation.Language.CommandParameterAst] -and $e.ParameterName -eq $Name) {
                    if ($null -ne $e.Argument) { return $e.Argument }
                    if (($i + 1) -lt $elements.Count) { return $elements[$i + 1] }
                }
            }
            return $null
        }
        # The read-only guard of C14 over a parsed script. Anywhere: a cmdlet that writes the directory
        # (Set-, New-, Remove-, Disable-, Enable-, Move-, Rename-, Clear-, Add-, Reset-, Restore-, Unlock-,
        # Install-, Uninstall-AD*), a registry value write (Set-, New-, Remove-, Rename-, Clear-ItemProperty),
        # an StdRegProv Set*/Create*/Delete* method named in an Invoke-CimMethod call, a w32tm write switch
        # (/resync, /register, /unregister, /config, /debug) in any string of a command that names w32tm or in
        # any string literal outside the recommendation map, and a dfsrmig write switch (/setglobalstate,
        # /createglobalobjects, /deleterontfrsmember, /deleterodfsrmember) in any string literal outside the map.
        # Inside the C14 functions only: any Remove-* command and a -Properties argument that holds '*'.
        # What it cannot see: a switch or a cmdlet name assembled at run time from pieces.
        function Get-C14WriteHit { param($Ast, [string[]]$C14Names = @())
            $hits = @()
            $cmdletRx = '(?i)^(Set|New|Remove|Disable|Enable|Move|Rename|Clear|Add|Reset|Restore|Unlock|Install|Uninstall)-AD'
            $regRx = '(?i)^(Set|New|Remove|Rename|Clear)-ItemProperty$'
            $w32Rx = '(?i)(^|[\s"''])/(resync|register|unregister|config|debug)\b'
            $dfsRx = '(?i)(^|[\s"''])/(setglobalstate|createglobalobjects|deleterontfrsmember|deleterodfsrmember)\b'
            $strings = { param($node) @($node.FindAll({ param($n) $n -is [System.Management.Automation.Language.StringConstantExpressionAst] -or $n -is [System.Management.Automation.Language.ExpandableStringExpressionAst] }, $true) | ForEach-Object { [string]$_.Value }) }
            foreach ($c in @($Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true))) {
                $name = [string]$c.GetCommandName()
                # This script's own functions carry the Adfa prefix (New-AdfaC14Row) and are not ActiveDirectory cmdlets.
                if ($name -match $cmdletRx -and $name -notmatch '(?i)^\w+-Adfa') { $hits += ("directory write: {0}" -f $c.Extent.Text) }
                if ($name -match $regRx) { $hits += ("registry write: {0}" -f $c.Extent.Text) }
                $words = @($name) + @(& $strings $c)
                if ($name -eq 'Invoke-CimMethod' -and @($words | Where-Object { $_ -match '(?i)^(Set|Create|Delete)\w*$' }).Count -gt 0) { $hits += ("registry method: {0}" -f $c.Extent.Text) }
                if (@($words | Where-Object { $_ -match '(?i)(^|\\)w32tm(\.exe)?$' }).Count -gt 0 -and @($words | Where-Object { $_ -match $w32Rx }).Count -gt 0) { $hits += ("w32tm write: {0}" -f $c.Extent.Text) }
            }
            $map = @($Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.AssignmentStatementAst] -and $n.Left.Extent.Text -eq '$script:RecommendationMap' }, $true))
            foreach ($s in @($Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.StringConstantExpressionAst] -or $n -is [System.Management.Automation.Language.ExpandableStringExpressionAst] }, $true))) {
                $v = [string]$s.Value
                if ($v -notmatch $dfsRx -and -not ($v -match $w32Rx -and $v -match '(?i)w32tm|/(resync|register|unregister)\b')) { continue }
                # Advice text: inside the recommendation map, or the Detail of a finding row (New-Finding,
                # New-Adfa*Row), which tells the operator what to run and runs nothing.
                $inMap = $false
                $p = $s.Parent
                while ($null -ne $p) {
                    if ($map -contains $p) { $inMap = $true; break }
                    if ($p -is [System.Management.Automation.Language.CommandAst] -and [string]$p.GetCommandName() -match '(?i)^New-(Finding|Adfa\w*Row)$') { $inMap = $true; break }
                    $p = $p.Parent
                }
                if (-not $inMap) { $hits += ("switch: {0}" -f $s.Extent.Text) }
            }
            foreach ($fn in @($Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $C14Names -contains $n.Name }, $true))) {
                foreach ($c in @($fn.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true))) {
                    if ([string]$c.GetCommandName() -match '(?i)^Remove-') { $hits += ("remove in {0}: {1}" -f $fn.Name, $c.Extent.Text) }
                }
                # A '*' given as a property list: after -Properties, assigned to .Properties, or as the
                # value of a Properties key. A '*' filter (Get-ADDomainController -Filter *) is not one.
                foreach ($s in @($fn.FindAll({ param($n) $n -is [System.Management.Automation.Language.StringConstantExpressionAst] -and [string]$n.Value -eq '*' }, $true))) {
                    $asProperties = $false
                    $p = $s.Parent
                    while ($null -ne $p -and -not $asProperties) {
                        if ($p -is [System.Management.Automation.Language.AssignmentStatementAst] -and $p.Left.Extent.Text -match '(?i)\.Properties$') { $asProperties = $true }
                        elseif ($p -is [System.Management.Automation.Language.HashtableAst]) {
                            foreach ($pair in @($p.KeyValuePairs)) { if ([string]$pair.Item1.Extent.Text -match '(?i)^[''"]?Properties[''"]?$' -and $pair.Item2.Extent.Text -match '\*') { $asProperties = $true } }
                        }
                        elseif ($p -is [System.Management.Automation.Language.CommandAst]) {
                            $el = @($p.CommandElements)
                            for ($i = 1; $i -lt $el.Count; $i++) {
                                if ($el[$i - 1] -is [System.Management.Automation.Language.CommandParameterAst] -and $el[$i - 1].ParameterName -eq 'Properties' -and $el[$i].Extent.Text -match '\*') { $asProperties = $true }
                            }
                            break
                        }
                        $p = $p.Parent
                    }
                    if ($asProperties) { $hits += ("every property in {0}: {1}" -f $fn.Name, $s.Parent.Extent.Text) }
                }
            }
            return , @($hits)
        }
    }
    BeforeEach {
        Clear-AdfaDcPortCache
    }

    Context 'Config tables (Learn, read 2026-11-17)' {
        It 'declares the five C14 tables, each with its read date, its sources and its tool defaults labelled as such' {
            # Declared population: the five tables C14 reads.
            $names = @('Reach', 'SiteCoverage', 'ClockSkew', 'Stale', 'SysvolEngine')
            @($names | Where-Object { $script:Config.ContainsKey($_) -and $script:Config[$_] -is [hashtable] }).Count | Should -Be 5
            foreach ($n in @('Reach', 'SiteCoverage', 'Stale', 'SysvolEngine')) {
                [string]$script:Config[$n]['ReadDate'] | Should -Be '2026-11-17' -Because $n
                [string]$script:Config[$n]['SourceUrl'] | Should -Match '^https://learn\.microsoft\.com/' -Because $n
                [string]$script:Config[$n]['ThresholdSource'] | Should -Match 'tool default' -Because $n
            }
            [string]$script:Config.ClockSkew['PdcReadDate'] | Should -Be '2026-11-17'
            [string]$script:Config.ClockSkew['SkewTimeUrl'] | Should -Match '^https://learn\.microsoft\.com/'
        }
        It 'carries the defaults the catalogue and Learn give, and the tool defaults the brief chose' {
            $r = $script:Config.Reach
            @([int]$r['LdapPort'], [int]$r['WinRmPort'], [int]$r['RpcPort'], [int]$r['ProbeTimeoutMs']) -join ',' | Should -Be '389,5985,135,3000'
            [string]$r['UnreachableStatus'] | Should -Be 'Fail'
            [string]$r['NotManageableStatus'] | Should -Be 'Warning'
            (@($r['UnresolvedSocketErrors']) -join ',') | Should -Be 'HostNotFound,TryAgain,NoRecovery,NoData'
            $s = $script:Config.SiteCoverage
            [string]$s['UnassignedStatus'] | Should -Be 'Warning'
            [string]$s['NoClientSiteStatus'] | Should -Be 'Warning'
            [string]$s['NoClientSiteMarker'] | Should -Be 'NO_CLIENT_SITE:'
            [string]$s['NetlogonLogPath'] | Should -Be '\\{0}\ADMIN$\debug\netlogon.log'
            $t = $script:Config.Stale
            [int]$t['SyncIntervalDefaultDays'] | Should -Be 14
            [int]$t['SyncRandomisationDays'] | Should -Be 5
            [int]$t['PasswordAgeDays'] | Should -Be 365
            [int]$t['MaxObjects'] | Should -Be 100000
            $e = $script:Config.SysvolEngine
            [string]$e['FrsStatus'] | Should -Be 'Warning'
            [string]$e['DfsrSubscriptionDn'] | Should -Be 'CN=SYSVOL Subscription,CN=Domain System Volume,CN=DFSR-LocalSettings,{0}'
            [string]$e['FrsSubscriberDn'] | Should -Be 'CN=Domain System Volume (SYSVOL share),CN=NTFRS Subscriptions,{0}'
            [string]$e['GlobalSettingsDn'] | Should -Be 'CN=DFSR-GlobalSettings,CN=System,{0}'
            # Declared population: the four global states of dd639789.
            (@($e['GlobalStateNames'].Keys | Sort-Object { [int]$_ }) -join ',') | Should -Be '0,16,32,48'
            [string]$e['GlobalStateNames']['48'] | Should -Be 'Eliminated'
        }
        It 'carries version 1.31.0 in the script and the manifest (bumped by PORT-PLAN C14)' {
            [string]$script:Config.Version | Should -Be '1.31.0'
            (Import-PowerShellDataFile -Path (Join-Path $script:RepoRoot 'src/ADForestAssessment/ADForestAssessment.psd1')).ModuleVersion | Should -Be '1.31.0'
        }
    }

    Context 'Config override: the five C14 sections (Merge-AdfaSpecConfig)' {
        It 'registers the five sections, each with the generic validator' {
            foreach ($k in @('Reach', 'SiteCoverage', 'ClockSkew', 'Stale', 'SysvolEngine')) {
                @($script:ConfigOverrideSections.Keys) | Should -Contain $k
                [string]$script:ConfigOverrideSections[$k]['Merge'] | Should -Be 'Merge-AdfaSpecConfig'
                [string]$script:ConfigOverrideSections[$k]['ConfigKey'] | Should -Be $k
            }
            (@($script:ConfigOverrideSections.Keys) -join ',') | Should -Be 'DcDisk,DcHardening,Laps,DcCertificates,RidPool,SidHistory,Gpo,Acl,Privileged,DcDiag,Dns,Reach,SiteCoverage,ClockSkew,Stale,SysvolEngine'
        }
        It 'merges a valid override for each section and cites the file only for what it supplied: <Section>' -ForEach @(
            @{ Section = 'Reach'; Override = @{ ProbeTimeoutMs = 5000; UnreachableStatus = 'Warning' }; Key = 'ProbeTimeoutMs'; Value = 5000 }
            @{ Section = 'SiteCoverage'; Override = @{ UnassignedStatus = 'Info'; NameListCap = 5 }; Key = 'NameListCap'; Value = 5 }
            @{ Section = 'ClockSkew'; Override = @{ WarnSeconds = 30; Samples = 5 }; Key = 'WarnSeconds'; Value = 30 }
            @{ Section = 'Stale'; Override = @{ PasswordAgeDays = 180; StaleStatus = 'Info' }; Key = 'PasswordAgeDays'; Value = 180 }
            @{ Section = 'SysvolEngine'; Override = @{ FrsStatus = 'Fail' }; Key = 'FrsStatus'; Value = 'Fail' }
        ) {
            $base = $script:Config[$Section]
            $merged = Merge-AdfaSpecConfig -BaseConfig $base -Override $Override -OverrideSource 'C:\cfg\c14.json'
            $merged[$Key] | Should -Be $Value
            [string]$merged['ThresholdSource'] | Should -Match ([regex]::Escape('C:\cfg\c14.json'))
            # The built-in table is not changed.
            $base[$Key] | Should -Not -Be $Value
        }
        It 'refuses a malformed override: <Case>' -ForEach @(
            @{ Case = 'not an object'; Section = 'Reach'; Override = 'Fail'; Message = 'single object' }
            @{ Case = 'an empty object'; Section = 'Stale'; Override = @{}; Message = 'empty object' }
            @{ Case = 'an unknown key'; Section = 'SiteCoverage'; Override = @{ Bogus = 1 }; Message = "unknown key 'Bogus'" }
            @{ Case = 'a port'; Section = 'Reach'; Override = @{ LdapPort = 636 }; Message = "unknown key 'LdapPort'" }
            @{ Case = 'the Kerberos maximum'; Section = 'ClockSkew'; Override = @{ KerberosMaxSeconds = 600 }; Message = "unknown key 'KerberosMaxSeconds'" }
            @{ Case = 'a DN template'; Section = 'SysvolEngine'; Override = @{ DfsrSubscriptionDn = 'x' }; Message = "unknown key 'DfsrSubscriptionDn'" }
            @{ Case = 'a null'; Section = 'Stale'; Override = @{ StaleStatus = $null }; Message = 'null' }
            @{ Case = 'a status outside its set'; Section = 'SysvolEngine'; Override = @{ FrsStatus = 'Pass' }; Message = 'Warning, Fail' }
            @{ Case = 'a status that is not a string'; Section = 'Reach'; Override = @{ NotManageableStatus = 1 }; Message = 'must be a string' }
            @{ Case = 'a number written as text'; Section = 'Reach'; Override = @{ ProbeTimeoutMs = '5000' }; Message = 'JSON number' }
            @{ Case = 'a number below its range'; Section = 'Reach'; Override = @{ ProbeTimeoutMs = 99 }; Message = '100 to 60000' }
            @{ Case = 'a number above its range'; Section = 'ClockSkew'; Override = @{ WarnSeconds = 300 }; Message = '1 to 299' }
            @{ Case = 'a fraction'; Section = 'Stale'; Override = @{ MaxObjects = 10.5 }; Message = 'whole number' }
        ) {
            $thrown = ''
            try { Merge-AdfaSpecConfig -BaseConfig $script:Config[$Section] -Override $Override -OverrideSource 'C:\cfg\c14.json' | Out-Null } catch { $thrown = $_.Exception.Message }
            $thrown | Should -Match $Message
        }
        It 'refuses an override through the whole loader, prefixed with the section' {
            $thrown = ''
            try { Resolve-AdfaConfigOverride -Override @{ SysvolEngine = @{ FrsStatus = 'Pass' } } -BaseConfig $script:Config -Sections $script:ConfigOverrideSections | Out-Null } catch { $thrown = $_.Exception.Message }
            $thrown | Should -Match "section 'SysvolEngine'"
            $ok = Resolve-AdfaConfigOverride -Override @{ Stale = @{ StaleStatus = 'Info' } } -BaseConfig $script:Config -Sections $script:ConfigOverrideSections -OverrideSource 'C:\cfg\c14.json'
            [string]$ok['Stale']['StaleStatus'] | Should -Be 'Info'
        }
    }

    Context 'REACH-001/002: the pure classifier' {
        It 'classifies a name that does not resolve as Unreachable by name resolution: <SocketError>' -ForEach @(
            @{ SocketError = 'HostNotFound' }, @{ SocketError = 'TryAgain' }, @{ SocketError = 'NoRecovery' }, @{ SocketError = 'NoData' }
        ) {
            $c = Resolve-AdfaDcReachClass -Resolve (New-C14Resolve -Ok $false -Addresses @() -SocketError $SocketError) -LdapProbes @() -Config $script:Config.Reach
            $c.Class | Should -Be 'Unreachable'
            $c.Cause | Should -Be 'Unresolved'
        }
        It 'tells a resolution that timed out, a name with no address and a resolver fault apart' {
            $t = Resolve-AdfaDcReachClass -Resolve (New-C14Resolve -Ok $false -Addresses @() -TimedOut $true) -LdapProbes @() -Config $script:Config.Reach
            "$($t.Class)/$($t.Cause)" | Should -Be 'Unreachable/ResolveTimedOut'
            $n = Resolve-AdfaDcReachClass -Resolve (New-C14Resolve -Addresses @()) -LdapProbes @() -Config $script:Config.Reach
            "$($n.Class)/$($n.Cause)" | Should -Be 'Unreachable/NoAddress'
            # Not a socket error: a fault of the tool or the input, never a Fail of the DC.
            $f = Resolve-AdfaDcReachClass -Resolve (New-C14Resolve -Ok $false -Addresses @() -ErrorText 'ArgumentException') -LdapProbes @() -Config $script:Config.Reach
            "$($f.Class)/$($f.Cause)" | Should -Be 'NotAssessed/ResolveFailed'
        }
        It 'classifies a DC whose LDAP port answers on no address by the reason: <Case>' -ForEach @(
            @{ Case = 'refused everywhere'; Probes = @(@{ O = 'Failed'; S = 'ConnectionRefused'; T = $false }, @{ O = 'Failed'; S = 'ConnectionRefused'; T = $false }); Cause = 'Refused' }
            @{ Case = 'one timed out'; Probes = @(@{ O = 'Failed'; S = 'ConnectionRefused'; T = $false }, @{ O = 'Failed'; S = ''; T = $true }); Cause = 'TimedOut' }
            @{ Case = 'socket TimedOut'; Probes = @(@{ O = 'Failed'; S = 'TimedOut'; T = $false }); Cause = 'TimedOut' }
            @{ Case = 'no route'; Probes = @(@{ O = 'Failed'; S = 'HostUnreachable'; T = $false }); Cause = 'NetworkUnreachable' }
            @{ Case = 'another socket error'; Probes = @(@{ O = 'Failed'; S = 'ConnectionReset'; T = $false }); Cause = 'ConnectFailed' }
        ) {
            $probes = @($Probes | ForEach-Object { New-C14Probe -Outcome $_.O -SocketError $_.S -TimedOut $_.T })
            $c = Resolve-AdfaDcReachClass -Resolve (New-C14Resolve -Addresses @($script:C14Ip1, $script:C14Ip2)) -LdapProbes $probes -Config $script:Config.Reach
            $c.Class | Should -Be 'Unreachable'
            $c.Cause | Should -Be $Cause
        }
        It 'classifies a DC whose LDAP port answers by its management ports: <Case>' -ForEach @(
            @{ Case = 'WinRM answers'; WinRm = 'Open'; Rpc = 'Open'; Class = 'Reachable' }
            @{ Case = 'WinRM answers, RPC silent'; WinRm = 'Open'; Rpc = 'Failed'; Class = 'Reachable' }
            @{ Case = 'WinRM silent, RPC answers'; WinRm = 'Failed'; Rpc = 'Open'; Class = 'WinRmUnavailable' }
            @{ Case = 'both silent'; WinRm = 'Failed'; Rpc = 'Failed'; Class = 'NotManageable' }
        ) {
            $ldap = @((New-C14Probe -Outcome 'Failed' -SocketError 'ConnectionRefused'), (New-C14Probe -Outcome 'Open'))
            $c = Resolve-AdfaDcReachClass -Resolve (New-C14Resolve -Addresses @($script:C14Ip1, $script:C14Ip2)) -LdapProbes $ldap `
                -WinRm (New-C14Probe -Outcome $WinRm -SocketError 'TimedOut') -Rpc (New-C14Probe -Outcome $Rpc -SocketError 'TimedOut') -Config $script:Config.Reach
            $c.Class | Should -Be $Class
        }
        It 'is NotAssessed, never Reachable, when LDAP answered but a management port was not probed' {
            $c = Resolve-AdfaDcReachClass -Resolve (New-C14Resolve) -LdapProbes @((New-C14Probe)) -WinRm $null -Rpc $null -Config $script:Config.Reach
            $c.Class | Should -Be 'NotAssessed'
        }
    }

    Context 'REACH-001/002: the verdict row' {
        It 'grades each class: <Class>/<Cause>' -ForEach @(
            @{ Class = 'Unreachable'; Cause = 'Unresolved'; Status = 'Fail'; Text = 'name resolution' }
            @{ Class = 'Unreachable'; Cause = 'ResolveTimedOut'; Status = 'Fail'; Text = 'name resolution' }
            @{ Class = 'Unreachable'; Cause = 'Refused'; Status = 'Fail'; Text = 'refused' }
            @{ Class = 'Unreachable'; Cause = 'TimedOut'; Status = 'Fail'; Text = 'no answer within' }
            @{ Class = 'Unreachable'; Cause = 'NetworkUnreachable'; Status = 'Fail'; Text = 'no route' }
            @{ Class = 'NotManageable'; Cause = 'ManagementPortsSilent'; Status = 'Warning'; Text = 'default management ports' }
            @{ Class = 'Reachable'; Cause = ''; Status = 'Pass'; Text = 'WinRM' }
            @{ Class = 'WinRmUnavailable'; Cause = ''; Status = 'Pass'; Text = 'DCOM' }
            @{ Class = 'NotAssessed'; Cause = 'ResolveFailed'; Status = 'Not Assessed'; Text = 'not a clean result' }
        ) {
            $record = [pscustomobject]@{ HostName = $script:C14Dc1; Class = $Class; Cause = $Cause; Addresses = @($script:C14Ip1); PortText = '389=Open'; Error = '' }
            $row = Get-AdfaDcReachVerdict -HostName $script:C14Dc1 -Scope 'contoso.com' -Record $record -Config $script:Config.Reach
            $row.Item | Should -Be ("DC reachability: {0}" -f $script:C14Dc1)
            $row.Status | Should -Be $Status
            $row.Detail | Should -Match $Text
            # Access denied is never a probe class: it is reported by the read that met it.
            $row.Detail | Should -Not -Match '(?i)access denied'
            # Addresses are display columns, never in the text the advice is chosen from.
            $row.Detail | Should -Not -Match ([regex]::Escape($script:C14Ip1))
            [string]$row.Addresses | Should -Match ([regex]::Escape($script:C14Ip1))
        }
        It 'says which sections reuse an Unreachable class, and never that every check of the DC is Not Assessed (review finding 1)' {
            # The port matrix of the same section re-resolves the DC and grades it Fail, so a promise that
            # every check is Not Assessed would be contradicted by the report itself.
            $record = [pscustomobject]@{ HostName = $script:C14Dc2; Class = 'Unreachable'; Cause = 'Unresolved'; Addresses = @(); PortText = ''; Error = ''; SocketError = 'HostNotFound' }
            $row = Get-AdfaDcReachVerdict -HostName $script:C14Dc2 -Scope 'contoso.com' -Record $record -Config $script:Config.Reach
            $row.Detail | Should -Not -Match '(?i)every check'
            $row.Detail | Should -Match 'Time Hierarchy and Site Health rows of this domain controller reuse this result'
            $row.Detail | Should -Match 'port matrix rows and the other per-DC sections probe on their own'
        }
        It 'honours the statuses a file set' {
            $cfg = Merge-AdfaSpecConfig -BaseConfig $script:Config.Reach -Override @{ UnreachableStatus = 'Warning'; NotManageableStatus = 'Info' } -OverrideSource 'C:\cfg\c14.json'
            (Get-AdfaDcReachVerdict -HostName $script:C14Dc1 -Record ([pscustomobject]@{ Class = 'Unreachable'; Cause = 'Refused'; Addresses = @(); PortText = ''; Error = '' }) -Config $cfg).Status | Should -Be 'Warning'
            (Get-AdfaDcReachVerdict -HostName $script:C14Dc1 -Record ([pscustomobject]@{ Class = 'NotManageable'; Cause = 'ManagementPortsSilent'; Addresses = @(); PortText = ''; Error = '' }) -Config $cfg).Status | Should -Be 'Info'
        }
        It 'is Not Assessed with no record and with no host name' {
            (Get-AdfaDcReachVerdict -HostName $script:C14Dc1 -Record $null -Config $script:Config.Reach).Status | Should -Be 'Not Assessed'
            (Get-AdfaDcReachVerdict -HostName '' -Record $null -Config $script:Config.Reach).Status | Should -Be 'Not Assessed'
        }
    }

    Context 'REACH: the probe, run once per DC and reused' {
        It 'probes each DC once, seeds the shared port cache, and never probes the management ports of an unreachable DC' {
            Mock Resolve-AdfaHostAddress {
                if ($HostName -eq $script:C14Dc3) { return (New-C14Resolve -Ok $false -Addresses @() -SocketError 'HostNotFound') }
                if ($HostName -eq $script:C14Dc2) { return (New-C14Resolve -Addresses @($script:C14Ip2)) }
                return (New-C14Resolve -Addresses @($script:C14Ip1))
            }
            Mock Test-AdfaTcpAddress {
                if ($Address -eq $script:C14Ip2) { return (New-C14Probe -Outcome 'Failed' -SocketError 'ConnectionRefused') }
                return (New-C14Probe -Outcome 'Open')
            }
            Mock Test-TcpPort { throw 'the port cache was not seeded' }
            $a = Get-AdfaDcReachability -HostName $script:C14Dc1 -Config $script:Config.Reach
            $b = Get-AdfaDcReachability -HostName $script:C14Dc1 -Config $script:Config.Reach
            $a.Class | Should -Be 'Reachable'
            $b.Class | Should -Be 'Reachable'
            Should -Invoke Resolve-AdfaHostAddress -Times 1 -Exactly -ParameterFilter { $HostName -eq $script:C14Dc1 }
            # Declared population: the three ports probed for a reachable DC, 389, 5985 and 135.
            Should -Invoke Test-AdfaTcpAddress -Times 3 -Exactly
            (Test-AdfaDcPort -ComputerName $script:C14Dc1 -Port 389) | Should -BeTrue
            (Test-AdfaDcPort -ComputerName $script:C14Dc1 -Port 5985) | Should -BeTrue
            (Test-AdfaDcPort -ComputerName $script:C14Dc1 -Port 135) | Should -BeTrue
            $r2 = Get-AdfaDcReachability -HostName $script:C14Dc2 -Config $script:Config.Reach
            "$($r2.Class)/$($r2.Cause)" | Should -Be 'Unreachable/Refused'
            Should -Invoke Test-AdfaTcpAddress -Times 0 -Exactly -ParameterFilter { $Address -eq $script:C14Ip2 -and $Port -ne 389 }
            (Test-AdfaDcPort -ComputerName $script:C14Dc2 -Port 389) | Should -BeFalse
            $r3 = Get-AdfaDcReachability -HostName $script:C14Dc3 -Config $script:Config.Reach
            "$($r3.Class)/$($r3.Cause)" | Should -Be 'Unreachable/Unresolved'
            (Get-AdfaDcReachCause -HostName $script:C14Dc2) | Should -Match 'refused'
            (Get-AdfaDcReachCause -HostName $script:C14Dc3) | Should -Match 'name resolution'
            (Get-AdfaDcReachCause -HostName $script:C14Dc1) | Should -Be ''
        }
        It 'probes LDAP address by address until one answers, then WinRM and RPC at that address only (review finding 11)' {
            Mock Resolve-AdfaHostAddress {
                if ($HostName -eq $script:C14Dc2) { return (New-C14Resolve -Addresses @($script:C14Ip3, $script:C14Ip2)) }
                return (New-C14Resolve -Addresses @($script:C14Ip1, $script:C14Ip2))
            }
            Mock Test-AdfaTcpAddress {
                if ($Address -eq $script:C14Ip3) { return (New-C14Probe -Outcome 'Failed' -SocketError 'TimedOut' -TimedOut $true) }
                return (New-C14Probe -Outcome 'Open')
            }
            # Two DCs, each with two addresses: dc1 answers on its first, dc2 only on its second.
            $a = Get-AdfaDcReachability -HostName $script:C14Dc1 -Config $script:Config.Reach
            $a.Class | Should -Be 'Reachable'
            $a.LdapAddress | Should -Be $script:C14Ip1
            # The second address of dc1 is never probed: the first answered.
            Should -Invoke Test-AdfaTcpAddress -Times 0 -Exactly -ParameterFilter { $Address -eq $script:C14Ip2 }
            Should -Invoke Test-AdfaTcpAddress -Times 1 -Exactly -ParameterFilter { $Address -eq $script:C14Ip1 -and $Port -eq 5985 }
            Should -Invoke Test-AdfaTcpAddress -Times 1 -Exactly -ParameterFilter { $Address -eq $script:C14Ip1 -and $Port -eq 135 }
            $b = Get-AdfaDcReachability -HostName $script:C14Dc2 -Config $script:Config.Reach
            $b.Class | Should -Be 'Reachable'
            $b.LdapAddress | Should -Be $script:C14Ip2
            Should -Invoke Test-AdfaTcpAddress -Times 1 -Exactly -ParameterFilter { $Address -eq $script:C14Ip3 -and $Port -eq 389 }
            Should -Invoke Test-AdfaTcpAddress -Times 0 -Exactly -ParameterFilter { $Address -eq $script:C14Ip3 -and $Port -ne 389 }
            Should -Invoke Test-AdfaTcpAddress -Times 1 -Exactly -ParameterFilter { $Address -eq $script:C14Ip2 -and $Port -eq 5985 }
        }
        It 'seeds a silent WinRM as closed, never as open (review finding 12)' {
            Mock Resolve-AdfaHostAddress { New-C14Resolve -Addresses @($script:C14Ip1) }
            Mock Test-AdfaTcpAddress {
                if ($Port -eq 5985) { return (New-C14Probe -Outcome 'Failed' -SocketError 'TimedOut' -TimedOut $true) }
                return (New-C14Probe -Outcome 'Open')
            }
            Mock Test-TcpPort { throw 'the port cache was not seeded' }
            $r = Get-AdfaDcReachability -HostName $script:C14Dc1 -Config $script:Config.Reach
            $r.Class | Should -Be 'WinRmUnavailable'
            (Test-AdfaDcPort -ComputerName $script:C14Dc1 -Port 5985) | Should -BeFalse
            (Test-AdfaDcPort -ComputerName $script:C14Dc1 -Port 135) | Should -BeTrue
            (Test-AdfaDcPort -ComputerName $script:C14Dc1 -Port 389) | Should -BeTrue
            Should -Invoke Test-TcpPort -Times 0 -Exactly
        }
        It 'forgets every classification at the start of a run' {
            Mock Resolve-AdfaHostAddress { New-C14Resolve }
            Mock Test-AdfaTcpAddress { New-C14Probe }
            Get-AdfaDcReachability -HostName $script:C14Dc1 -Config $script:Config.Reach | Out-Null
            $null -ne (Get-AdfaDcReachRecord -HostName $script:C14Dc1) | Should -BeTrue
            Clear-AdfaDcPortCache
            Get-AdfaDcReachRecord -HostName $script:C14Dc1 | Should -BeNullOrEmpty
        }
        It 'gives every DC of every scoped domain a row, and a domain with no DC a population row' {
            Mock Resolve-AdfaHostAddress {
                if ($HostName -eq $script:C14Dc3) { return (New-C14Resolve -Ok $false -Addresses @() -SocketError 'HostNotFound') }
                if ($HostName -eq $script:C14Dc2) { return (New-C14Resolve -Addresses @($script:C14Ip2)) }
                return (New-C14Resolve -Addresses @($script:C14Ip1))
            }
            Mock Test-AdfaTcpAddress {
                if ($Address -eq $script:C14Ip2) { return (New-C14Probe -Outcome 'Failed' -SocketError 'TimedOut') }
                if ($Port -eq 5985 -or $Port -eq 135) { return (New-C14Probe -Outcome 'Failed' -SocketError 'TimedOut') }
                return (New-C14Probe -Outcome 'Open')
            }
            $targets = @((New-C14Target $script:C14Dc1 'contoso.com'), (New-C14Target $script:C14Dc2 'contoso.com'), (New-C14Target $script:C14Dc3 'north.contoso.com'))
            $rows = @(Get-AdfaDcReachabilityRows -DomainControllers $targets -Config $script:Config.Reach -InventoryFailures @([pscustomobject]@{ Domain = 'south.contoso.com'; Error = 'STUB: ADWS unreachable' }) `
                    -ScopedDomains @('contoso.com', 'north.contoso.com', 'south.contoso.com'))
            # Declared population: three DCs, one row each.
            (Get-C14Row $rows ("DC reachability: {0}" -f $script:C14Dc1))[0].Status | Should -Be 'Warning'
            (Get-C14Row $rows ("DC reachability: {0}" -f $script:C14Dc2))[0].Status | Should -Be 'Fail'
            (Get-C14Row $rows ("DC reachability: {0}" -f $script:C14Dc3))[0].Status | Should -Be 'Fail'
            (Get-C14Row $rows ("DC reachability: {0}" -f $script:C14Dc3))[0].Scope | Should -Be 'north.contoso.com'
            $gap = Get-C14Row $rows 'DC reachability (population): south.contoso.com'
            $gap.Count | Should -Be 1
            $gap[0].Status | Should -Be 'Not Assessed'
            $gap[0].Detail | Should -Match 'ADWS unreachable'
            @($rows | Where-Object { $_.Status -eq 'Pass' }).Count | Should -Be 0
        }
        It 'is Not Assessed, never Pass, with no DC at all' {
            $rows = @(Get-AdfaDcReachabilityRows -DomainControllers @() -Config $script:Config.Reach -ScopedDomains @())
            $rows.Count | Should -Be 1
            $rows[0].Status | Should -Be 'Not Assessed'
        }
    }

    Context 'SITE-001: subnets without a site (pure)' {
        It 'warns when a subnet has no site, naming it in a column and never in the text' {
            $subnets = @([pscustomobject]@{ Name = '192.0.2.0/24'; Site = 'CN=HQ,CN=Sites,CN=Configuration,DC=contoso,DC=com' }, [pscustomobject]@{ Name = '198.51.100.0/24'; Site = $null })
            $row = Get-AdfaSubnetSiteVerdict -Subnets $subnets -ReadError '' -ForestName 'contoso.com' -Config $script:Config.SiteCoverage
            $row.Item | Should -Be 'Subnets without a site: contoso.com'
            $row.Status | Should -Be 'Warning'
            $row.Detail | Should -Match '1 of 2'
            $row.Detail | Should -Not -Match '198\.51\.100'
            [string]$row.Subnets | Should -Match '198\.51\.100\.0/24'
            $row.Evidence | Should -Match 'reasoning'
        }
        It 'passes when every subnet read has a site' {
            $subnets = @([pscustomobject]@{ Name = '192.0.2.0/24'; Site = 'CN=HQ' }, [pscustomobject]@{ Name = '198.51.100.0/24'; Site = 'CN=Branch' })
            (Get-AdfaSubnetSiteVerdict -Subnets $subnets -ReadError '' -ForestName 'contoso.com' -Config $script:Config.SiteCoverage).Status | Should -Be 'Pass'
        }
        It 'is Not Assessed, never Pass, when the read failed or returned nothing' {
            $f = Get-AdfaSubnetSiteVerdict -Subnets @() -ReadError 'STUB: access denied' -ForestName 'contoso.com' -Config $script:Config.SiteCoverage
            $f.Status | Should -Be 'Not Assessed'
            $f.Detail | Should -Match 'STUB: access denied'
            (Get-AdfaSubnetSiteVerdict -Subnets @() -ReadError '' -ForestName 'contoso.com' -Config $script:Config.SiteCoverage).Status | Should -Be 'Not Assessed'
        }
        It 'honours UnassignedStatus from a file' {
            $cfg = Merge-AdfaSpecConfig -BaseConfig $script:Config.SiteCoverage -Override @{ UnassignedStatus = 'Info' } -OverrideSource 'C:\cfg\c14.json'
            (Get-AdfaSubnetSiteVerdict -Subnets @([pscustomobject]@{ Name = '192.0.2.0/24'; Site = '' }) -ReadError '' -ForestName 'contoso.com' -Config $cfg).Status | Should -Be 'Info'
        }
    }

    Context 'SITE-001: clients without a site, from netlogon.log' {
        It 'parses NO_CLIENT_SITE lines: the first word after the marker is the name, the second the address (event 5807)' {
            $text = @(
                '11/17 10:00:01 [MISC] [1234] CONTOSO: NO_CLIENT_SITE: WS01 198.51.100.77'
                '11/17 10:00:02 [SESSION] [1234] CONTOSO: NlSessionSetup: Try Session setup'
                '11/17 10:05:01 [MISC] [1234] CONTOSO: NO_CLIENT_SITE: WS01 198.51.100.77'
                '11/17 10:06:01 [MISC] [1234] CONTOSO: NO_CLIENT_SITE: WS02 198.51.100.78'
                '11/17 10:07:01 [MISC] [1234] CONTOSO: NO_CLIENT_SITE:'
            ) -join "`r`n"
            $p = ConvertFrom-AdfaNetlogonNoClientSite -Text $text -Marker 'NO_CLIENT_SITE:'
            $p.Lines | Should -Be 4
            $p.Unparsed | Should -Be 1
            # Declared population: two distinct clients.
            @($p.Entries).Count | Should -Be 2
            (@($p.Entries | ForEach-Object { "{0} {1}" -f $_.Name, $_.Address }) -join ',') | Should -Be 'WS01 198.51.100.77,WS02 198.51.100.78'
        }
        It 'grades a read log: entries Warning, none Info and never Pass' {
            $raw = [pscustomobject]@{ Ok = $true; Class = 'Read'; Text = ("x NO_CLIENT_SITE: WS01 {0}" -f $script:C14Client); Error = ''; Path = '\\dc1.contoso.com\ADMIN$\debug\netlogon.log'; Partial = $false; BytesRead = 40 }
            $w = Get-AdfaNoClientSiteVerdict -HostName $script:C14Dc1 -Scope 'contoso.com' -Raw $raw -PortOpen $true -Config $script:Config.SiteCoverage
            $w.Item | Should -Be ("Clients without a site: {0}" -f $script:C14Dc1)
            $w.Status | Should -Be 'Warning'
            $w.Detail | Should -Not -Match ([regex]::Escape($script:C14Client))
            [string]$w.Clients | Should -Match ([regex]::Escape($script:C14Client))
            $raw.Text = 'nothing to see'
            $i = Get-AdfaNoClientSiteVerdict -HostName $script:C14Dc1 -Scope 'contoso.com' -Raw $raw -PortOpen $true -Config $script:Config.SiteCoverage
            $i.Status | Should -Be 'Info'
            $i.Detail | Should -Match 'not a clean result|not proof'
        }
        It 'tells the failures apart, each Not Assessed: <Case>' -ForEach @(
            @{ Case = 'access denied'; Class = 'AccessDenied'; Port = $true; Reach = ''; Text = 'access denied'; Not = 'unreachable' }
            @{ Case = 'unreachable path'; Class = 'Unreachable'; Port = $true; Reach = ''; Text = 'unreachable'; Not = 'access denied' }
            @{ Case = 'log not found'; Class = 'NotFound'; Port = $true; Reach = ''; Text = 'not found'; Not = 'access denied' }
            @{ Case = 'timed out'; Class = 'TimedOut'; Port = $true; Reach = ''; Text = 'timed out'; Not = 'access denied' }
            @{ Case = 'SMB silent'; Class = ''; Port = $false; Reach = ''; Text = 'SMB \(445\)'; Not = 'access denied' }
            @{ Case = 'DC classified unreachable'; Class = ''; Port = $true; Reach = 'Unreachable (refused): every address refused LDAP (389)'; Text = 'refused'; Not = 'access denied' }
        ) {
            $raw = $null
            if ($Class -ne '') { $raw = [pscustomobject]@{ Ok = $false; Class = $Class; Text = ''; Error = 'STUB'; Path = 'x'; Partial = $false; BytesRead = 0 } }
            $row = Get-AdfaNoClientSiteVerdict -HostName $script:C14Dc2 -Scope 'contoso.com' -Raw $raw -PortOpen $Port -ReachCause $Reach -Config $script:Config.SiteCoverage
            $row.Status | Should -Be 'Not Assessed'
            $row.Detail | Should -Match ("(?i){0}" -f $Text)
            $row.Detail | Should -Not -Match ("(?i){0}" -f $Not)
        }
        It 'reads only the tail of the log, read-only, and drops the partial first line' {
            $path = Join-Path $TestDrive 'netlogon.log'
            $lines = @(1..200 | ForEach-Object { ("11/17 10:{0:00}:00 [MISC] CONTOSO: NO_CLIENT_SITE: WS{0:000} 198.51.100.{1}" -f ($_ % 60), ($_ % 250)) })
            [System.IO.File]::WriteAllText($path, ($lines -join "`r`n"))
            $raw = Get-AdfaNetlogonLogRaw -Path $path -MaxBytes 1000
            $raw.Ok | Should -BeTrue
            $raw.Partial | Should -BeTrue
            $raw.BytesRead | Should -BeLessOrEqual 1000
            $first = @($raw.Text -split "`r?`n")[0]
            $first | Should -Match '^11/17 '
            $missing = Get-AdfaNetlogonLogRaw -Path (Join-Path $TestDrive 'absent.log') -MaxBytes 1000
            $missing.Ok | Should -BeFalse
            $missing.Class | Should -Be 'NotFound'
        }
        It 'gives every DC its row, and probes SMB through the shared cache' {
            Mock Test-TcpPort { $ComputerName -ne $script:C14Dc3 }
            Mock Get-AdfaNetlogonLogRaw {
                if ($Path -like ("*{0}*" -f $script:C14Dc2)) { return [pscustomobject]@{ Ok = $false; Class = 'AccessDenied'; Text = ''; Error = 'Access is denied.'; Path = $Path; Partial = $false; BytesRead = 0 } }
                return [pscustomobject]@{ Ok = $true; Class = 'Read'; Text = ("x NO_CLIENT_SITE: WS01 {0}" -f $script:C14Client); Error = ''; Path = $Path; Partial = $false; BytesRead = 50 }
            }
            $targets = @((New-C14Target $script:C14Dc1 'contoso.com'), (New-C14Target $script:C14Dc2 'contoso.com'), (New-C14Target $script:C14Dc3 'north.contoso.com'))
            $rows = @(Get-AdfaClientSiteRows -DomainControllers $targets -Config $script:Config.SiteCoverage -PortTimeoutMs 100 -ScopedDomains @('contoso.com', 'north.contoso.com'))
            (Get-C14Row $rows ("Clients without a site: {0}" -f $script:C14Dc1))[0].Status | Should -Be 'Warning'
            (Get-C14Row $rows ("Clients without a site: {0}" -f $script:C14Dc2))[0].Detail | Should -Match 'access denied'
            (Get-C14Row $rows ("Clients without a site: {0}" -f $script:C14Dc3))[0].Detail | Should -Match 'SMB \(445\)'
            Should -Invoke Get-AdfaNetlogonLogRaw -Times 2 -Exactly
            Should -Invoke Get-AdfaNetlogonLogRaw -Times 1 -Exactly -ParameterFilter { $Path -eq ('\\{0}\ADMIN$\debug\netlogon.log' -f $script:C14Dc1) }
        }
    }

    Context 'TIME-001: clock offset against the forest root PDC emulator (pure)' {
        It 'grades the offset difference against the reference: <Case>' -ForEach @(
            @{ Case = 'in step'; Dc = @(10.5, 10.6, 10.4); Ref = @(0.2, 0.1, 0.3); Status = 'Pass' }
            @{ Case = 'just below the warning level'; Dc = @(59.9); Ref = @(0.0); Status = 'Pass' }
            @{ Case = 'at the warning level'; Dc = @(60.0); Ref = @(0.0); Status = 'Warning' }
            @{ Case = 'behind by more than a minute'; Dc = @(-70.0); Ref = @(0.0); Status = 'Warning' }
            @{ Case = 'just below the Kerberos maximum'; Dc = @(299.0); Ref = @(0.0); Status = 'Warning' }
            @{ Case = 'at the Kerberos maximum, the PDC ahead'; Dc = @(-200.0); Ref = @(100.0); Status = 'Fail' }
            @{ Case = 'far ahead'; Dc = @(400.0); Ref = @(0.0); Status = 'Fail' }
            @{ Case = 'both off by the same, so in step with the reference'; Dc = @(500.0); Ref = @(500.0); Status = 'Pass' }
        ) {
            $row = Get-AdfaPdcClockOffsetVerdict -DomainController $script:C14Dc2 -Scope 'contoso.com' -ReferencePdc $script:C14Pdc `
                -Sample (New-C14Sample -Offsets $Dc -Delays @(0.02)) -ReferenceSample (New-C14Sample -Offsets $Ref -Delays @(0.02)) -WarnSeconds 60 -FailSeconds 300
            $row.Item | Should -Be ("Clock offset vs forest root PDC: {0}" -f $script:C14Dc2)
            $row.Status | Should -Be $Status
        }
        It 'labels the warning level a tool default, the 300 s a Microsoft value, and the error bound as reasoning' {
            $row = Get-AdfaPdcClockOffsetVerdict -DomainController $script:C14Dc2 -ReferencePdc $script:C14Pdc -Sample (New-C14Sample -Offsets @(90.0) -Delays @(0.04)) -ReferenceSample (New-C14Sample -Offsets @(0.0) -Delays @(0.02)) -WarnSeconds 60 -FailSeconds 300
            $row.Detail | Should -Match 'tool default, not a Microsoft value'
            $row.Detail | Should -Match 'Kerberos'
            $row.Evidence | Should -Match 'tool reasoning'
            [double]$row.ErrorBoundSeconds | Should -BeGreaterThan 0
        }
        It 'states the error bound it documents: half the DC''s largest round trip plus half the reference''s median (review finding 14)' {
            # DC round trips 0.04 and 0.06 (largest 0.06); reference 0.02, 0.04, 0.10 (median 0.04): (0.06 + 0.04) / 2 = 0.05.
            $row = Get-AdfaPdcClockOffsetVerdict -DomainController $script:C14Dc2 -ReferencePdc $script:C14Pdc -Sample (New-C14Sample -Offsets @(1.0, 1.1) -Delays @(0.04, 0.06)) `
                -ReferenceSample (New-C14Sample -Offsets @(0.0, 0.1, 0.2) -Delays @(0.02, 0.04, 0.10)) -WarnSeconds 60 -FailSeconds 300
            [double]::Parse([string]$row.ErrorBoundSeconds, [System.Globalization.CultureInfo]::InvariantCulture) | Should -Be 0.05
            $row.Detail | Should -Match 'error bound about 0\.05 s'
        }
        It 'reports the reference DC itself as Info' {
            (Get-AdfaPdcClockOffsetVerdict -DomainController $script:C14Pdc -ReferencePdc $script:C14Pdc -IsReference $true -Sample (New-C14Sample -Offsets @(0.1)) -ReferenceSample (New-C14Sample -Offsets @(0.1))).Status | Should -Be 'Info'
        }
        It 'is Not Assessed, never Pass, when anything was not measured: <Case>' -ForEach @(
            @{ Case = 'no reference identified'; Ref = ''; Sample = @{ Q = $true; O = @(1.0) }; RefSample = @{ Q = $true; O = @(1.0) }; Reach = ''; Text = 'not identified' }
            @{ Case = 'reference not measured'; Ref = 'dc1.contoso.com'; Sample = @{ Q = $true; O = @(1.0) }; RefSample = @{ Q = $false; O = @() }; Reach = ''; Text = 'reference' }
            @{ Case = 'reference with no sample'; Ref = 'dc1.contoso.com'; Sample = @{ Q = $true; O = @(1.0) }; RefSample = @{ Q = $true; O = @() }; Reach = ''; Text = 'reference' }
            @{ Case = 'DC not measured'; Ref = 'dc1.contoso.com'; Sample = @{ Q = $false; O = @() }; RefSample = @{ Q = $true; O = @(1.0) }; Reach = ''; Text = 'could not be measured' }
            @{ Case = 'DC classified unreachable'; Ref = 'dc1.contoso.com'; Sample = @{ Q = $true; O = @(1.0) }; RefSample = @{ Q = $true; O = @(1.0) }; Reach = 'Unreachable (timed out)'; Text = 'timed out' }
        ) {
            $row = Get-AdfaPdcClockOffsetVerdict -DomainController $script:C14Dc2 -ReferencePdc $Ref -ReachCause $Reach `
                -Sample (New-C14Sample -Queried $Sample.Q -Offsets $Sample.O -ErrorText 'every NTP sample timed out') -ReferenceSample (New-C14Sample -Queried $RefSample.Q -Offsets $RefSample.O -ErrorText 'Access is denied.')
            $row.Status | Should -Be 'Not Assessed'
            $row.Detail | Should -Match $Text
            $row.Detail | Should -Match 'unmeasured offset is not a small one'
        }
    }

    Context 'TIME-001: the stripchart reading and the time hierarchy collector' {
        BeforeEach {
            $script:C14W32Calls = @()
            Mock Test-CommandAvailable { $true }
            Mock Test-TcpPort { $ComputerName -ne $script:C14Dc3 }
            Mock Invoke-ExternalCommand {
                $script:C14W32Calls += $Arguments
                $out = ''
                if ($Arguments -match '/stripchart /computer:(\S+)') {
                    $target = $Matches[1]
                    $off = '0.100'
                    if ($target -eq $script:C14Dc2) { $off = '400.000' }
                    $out = ("Tracking {0} [{1}].`r`nRdtscStart,RdtscEnd,FileTime,RoundtripDelay,NtpOffset`r`n1,2,3,0.020,{2}`r`n1,2,3,0.020,{2}" -f $target, $script:C14Ip1, $off)
                }
                elseif ($Arguments -match '/source') { $out = 'dc1.contoso.com' }
                elseif ($Arguments -match '/configuration') { $out = "Type: NTP (Local)`r`nNtpServer: time.contoso.com,0x8 (Local)" }
                [pscustomobject]@{ Success = $true; ExitCode = 0; Attempt = 1; Error = $null; StdOut = $out; OutFile = '' }
            }
        }
        It 'reads a stripchart sample through one bounded w32tm call that changes nothing' {
            $s = Get-AdfaStripchartSample -ComputerName $script:C14Dc1 -Samples 2 -TimeoutSeconds 30
            $s.Queried | Should -BeTrue
            @($s.Offsets).Count | Should -Be 2
            @($script:C14W32Calls).Count | Should -Be 1
            $script:C14W32Calls[0] | Should -Match '^/stripchart /computer:\S+ /dataonly /samples:2 /rdtsc$'
        }
        It 'names an access denied, a timed-out and an unreadable stripchart differently' {
            Mock Invoke-ExternalCommand { [pscustomobject]@{ Success = $false; ExitCode = 5; Attempt = 1; Error = $null; StdOut = 'The following error occurred: Access is denied. (0x80070005)'; OutFile = '' } }
            (Get-AdfaStripchartSample -ComputerName $script:C14Dc1 -Samples 2 -TimeoutSeconds 30).Error | Should -Match 'access denied'
            Mock Invoke-ExternalCommand { [pscustomobject]@{ Success = $true; ExitCode = 0; Attempt = 1; Error = $null; StdOut = "RdtscStart,RdtscEnd,FileTime,RoundtripDelay,NtpOffset`r`nRequest timed out."; OutFile = '' } }
            (Get-AdfaStripchartSample -ComputerName $script:C14Dc1 -Samples 2 -TimeoutSeconds 30).Error | Should -Match 'timed out'
        }
        It 'gives every DC a forest-root-PDC offset row, measured against the root PDC, not the host running the assessment' {
            $rows = @(Get-AdfaTimeHierarchyHealth -DomainControllers @($script:C14Dc1, $script:C14Dc2, $script:C14Dc3) -PdcEmulators @{ $script:C14Pdc = 'contoso.com' } `
                    -ForestRootPdc $script:C14Pdc -RpcPortTimeoutMs 100 -TimeoutSeconds 30 -SkewSamples 2 -WarnSeconds 60 -FailSeconds 300)
            # Declared population: three DCs, one PDC-offset row each.
            (Get-C14Row $rows ("Clock offset vs forest root PDC: {0}" -f $script:C14Dc1))[0].Status | Should -Be 'Info'
            (Get-C14Row $rows ("Clock offset vs forest root PDC: {0}" -f $script:C14Dc2))[0].Status | Should -Be 'Fail'
            (Get-C14Row $rows ("Clock offset vs forest root PDC: {0}" -f $script:C14Dc3))[0].Status | Should -Be 'Not Assessed'
            # The existing runner-relative rows are kept.
            (Get-C14Row $rows ("Clock offset on {0}" -f $script:C14Dc2)).Count | Should -Be 1
        }
        It 'does not probe again a DC classified Unreachable: its time source and offset rows carry the class, not a silent RPC port (review finding 4)' {
            Mock Resolve-AdfaHostAddress {
                if ($HostName -eq $script:C14Dc2) { return (New-C14Resolve -Ok $false -Addresses @() -SocketError 'HostNotFound') }
                return (New-C14Resolve -Addresses @($script:C14Ip1))
            }
            Mock Test-AdfaTcpAddress { New-C14Probe -Outcome 'Open' }
            # Two DCs classified first, as Invoke-Main does: dc1 Reachable, dc2 Unreachable by name resolution.
            (Get-AdfaDcReachability -HostName $script:C14Dc1 -Config $script:Config.Reach).Class | Should -Be 'Reachable'
            "$((Get-AdfaDcReachability -HostName $script:C14Dc2 -Config $script:Config.Reach).Cause)" | Should -Be 'Unresolved'
            Mock Test-TcpPort { $true }
            $rows = @(Get-AdfaTimeHierarchyHealth -DomainControllers @($script:C14Dc1, $script:C14Dc2) -PdcEmulators @{ $script:C14Pdc = 'contoso.com' } `
                    -ForestRootPdc $script:C14Pdc -RpcPortTimeoutMs 100 -TimeoutSeconds 30 -SkewSamples 2 -WarnSeconds 60 -FailSeconds 300)
            # No probe of dc2, on any port, and no w32tm call against it.
            Should -Invoke Test-TcpPort -Times 0 -Exactly -ParameterFilter { $ComputerName -eq $script:C14Dc2 }
            @($script:C14W32Calls | Where-Object { $_ -match ("/computer:{0}( |$)" -f [regex]::Escape($script:C14Dc2)) }).Count | Should -Be 0
            # Declared population: dc2's three rows, time source, runner offset and PDC offset.
            $src = @($rows | Where-Object { [string]$_.Item -like ("Time source on {0} *" -f $script:C14Dc2) })
            $src.Count | Should -Be 1
            $src[0].Status | Should -Be 'Not Assessed'
            $src[0].Detail | Should -Match 'does not resolve'
            $src[0].Detail | Should -Not -Match 'RPC \(135\) was not reachable'
            $off = Get-C14Row $rows ("Clock offset on {0}" -f $script:C14Dc2)
            $off.Count | Should -Be 1
            $off[0].Status | Should -Be 'Not Assessed'
            $off[0].Detail | Should -Match 'does not resolve'
            $off[0].Detail | Should -Not -Match 'RPC \(135\) was not reachable'
            (Get-C14Row $rows ("Clock offset vs forest root PDC: {0}" -f $script:C14Dc2))[0].Detail | Should -Match 'does not resolve'
            # dc1 is still read: its RPC answer came from the shared cache the probe seeded.
            @($script:C14W32Calls | Where-Object { $_ -match ("/source" ) -and $_ -match [regex]::Escape($script:C14Dc1) }).Count | Should -Be 1
            Should -Invoke Test-TcpPort -Times 0 -Exactly -ParameterFilter { $ComputerName -eq $script:C14Dc1 }
        }
        It 'measures the root PDC on its own when it is not among the DCs asked, and every DC is Not Assessed when it cannot be measured' {
            $rows = @(Get-AdfaTimeHierarchyHealth -DomainControllers @($script:C14Dc2) -PdcEmulators @{} -ForestRootPdc $script:C14Pdc -RpcPortTimeoutMs 100 -TimeoutSeconds 30 -SkewSamples 2)
            @($script:C14W32Calls | Where-Object { $_ -match ("/stripchart /computer:{0} " -f [regex]::Escape($script:C14Pdc)) }).Count | Should -Be 1
            (Get-C14Row $rows ("Clock offset vs forest root PDC: {0}" -f $script:C14Dc2))[0].Status | Should -Be 'Fail'
            Mock Invoke-ExternalCommand {
                $out = 'dc1.contoso.com'
                if ($Arguments -match ("/stripchart /computer:{0} " -f [regex]::Escape($script:C14Pdc))) { $out = 'error: 0x800705B4' }
                elseif ($Arguments -match '/stripchart') { $out = "RdtscStart,RdtscEnd,FileTime,RoundtripDelay,NtpOffset`r`n1,2,3,0.020,0.5" }
                [pscustomobject]@{ Success = $true; ExitCode = 0; Attempt = 1; Error = $null; StdOut = $out; OutFile = '' }
            }
            $none = @(Get-AdfaTimeHierarchyHealth -DomainControllers @($script:C14Dc2) -PdcEmulators @{} -ForestRootPdc $script:C14Pdc -RpcPortTimeoutMs 100 -TimeoutSeconds 30 -SkewSamples 2)
            $row = (Get-C14Row $none ("Clock offset vs forest root PDC: {0}" -f $script:C14Dc2))[0]
            $row.Status | Should -Be 'Not Assessed'
            $row.Detail | Should -Match 'reference'
        }
    }

    Context 'STALE-001/002: the directory read' {
        It 'builds the LDAP filters: enabled only, lastLogonTimestamp at or before the cutoff, or never logged on and created before it' {
            $cut = [datetime]::SpecifyKind([datetime]'2026-08-19 12:00:00', [System.DateTimeKind]::Utc)
            $ft = $cut.ToFileTimeUtc()
            $u = Get-AdfaStaleLdapFilter -Kind 'User' -CutoffUtc $cut
            $u | Should -Match ([regex]::Escape('(objectCategory=person)(objectClass=user)'))
            $u | Should -Match ([regex]::Escape('(!(userAccountControl:1.2.840.113556.1.4.803:=2))'))
            $u | Should -Match ([regex]::Escape(("(lastLogonTimestamp<={0})" -f $ft)))
            $u | Should -Match ([regex]::Escape('(&(!(lastLogonTimestamp=*))(whenCreated<=20260819120000.0Z))'))
            $c = Get-AdfaStaleLdapFilter -Kind 'Computer' -CutoffUtc $cut
            $c | Should -Match ([regex]::Escape('(objectCategory=computer)'))
            $c | Should -Match ([regex]::Escape('(!(objectClass=msDS-GroupManagedServiceAccount))'))
            $c | Should -Match ([regex]::Escape('(!(objectClass=msDS-ManagedServiceAccount))'))
            (Get-AdfaStaleLdapFilter -Kind 'Password' -CutoffUtc $cut) | Should -Match ([regex]::Escape(("(pwdLastSet<={0})" -f $ft)))
        }
        It 'asks the named domain for a listed property set, never every property, with a result cap one above MaxObjects' {
            $script:C14UserCalls = @()
            function Get-ADUser { param([string]$Server, [string]$LDAPFilter, [string[]]$Properties, [int]$ResultSetSize, $ErrorAction)
                $script:C14UserCalls += [pscustomobject]@{ Server = $Server; LDAPFilter = $LDAPFilter; Properties = @($Properties); ResultSetSize = $ResultSetSize }
                [pscustomobject]@{ SamAccountName = 'old.user'; lastLogonTimestamp = [int64]([datetime]'2025-01-01').ToFileTimeUtc(); whenCreated = [datetime]'2020-01-01'; userAccountControl = 512 }
                [pscustomobject]@{ SamAccountName = 'never.user'; whenCreated = [datetime]'2020-01-01'; userAccountControl = 512 }
            }
            $raw = Get-AdfaStaleRaw -DomainName 'north.contoso.com' -Kind 'User' -CutoffUtc ([datetime]'2026-08-19') -MaxObjects 10
            $raw.Ok | Should -BeTrue
            $raw.Capped | Should -BeFalse
            @($raw.Records).Count | Should -Be 2
            $script:C14UserCalls[0].Server | Should -Be 'north.contoso.com'
            $script:C14UserCalls[0].ResultSetSize | Should -Be 11
            @($script:C14UserCalls[0].Properties) | Should -Not -Contain '*'
            (@($script:C14UserCalls[0].Properties) -join ',') | Should -Be 'sAMAccountName,lastLogonTimestamp,whenCreated,userAccountControl'
            $never = @($raw.Records | Where-Object { $_.Name -eq 'never.user' })[0]
            $never.HasLastLogon | Should -BeFalse
            $capped = Get-AdfaStaleRaw -DomainName 'north.contoso.com' -Kind 'User' -CutoffUtc ([datetime]'2026-08-19') -MaxObjects 1
            $capped.Capped | Should -BeTrue
            # Exactly MaxObjects objects is a complete read, not a capped one (review finding 13a).
            $exact = Get-AdfaStaleRaw -DomainName 'north.contoso.com' -Kind 'User' -CutoffUtc ([datetime]'2026-08-19') -MaxObjects 2
            @($exact.Records).Count | Should -Be 2
            $exact.Capped | Should -BeFalse
        }
        It 'asks the password read for pwdLastSet and userAccountControl, and keeps both raw in the record (review findings 3 and 7)' {
            $script:C14PwdCalls = @()
            # Get-ADUser returns pwdLastSet only when it is asked for: it is not in the default property set.
            function Get-ADUser { param([string]$Server, [string]$LDAPFilter, [string[]]$Properties, [int]$ResultSetSize, $ErrorAction)
                $script:C14PwdCalls += [pscustomobject]@{ Server = $Server; LDAPFilter = $LDAPFilter; Properties = @($Properties) }
                $o = [pscustomobject]@{ SamAccountName = 'svc.never'; userAccountControl = 66048 }
                if (@($Properties) -contains 'pwdLastSet') { $o | Add-Member -NotePropertyName 'pwdLastSet' -NotePropertyValue ([int64]0) }
                $o
            }
            $raw = Get-AdfaStaleRaw -DomainName 'north.contoso.com' -Kind 'Password' -CutoffUtc ([datetime]'2025-11-17') -MaxObjects 10
            $raw.Ok | Should -BeTrue
            (@($script:C14PwdCalls[0].Properties) -join ',') | Should -Be 'sAMAccountName,pwdLastSet,userAccountControl'
            $script:C14PwdCalls[0].LDAPFilter | Should -Match 'pwdLastSet<='
            $rec = @($raw.Records)[0]
            $rec.PwdLastSetRaw | Should -Be 0
            $rec.UserAccountControl | Should -Be 66048
        }
        It 'counts the declared population with the stale filter less its time term, the default property set and a cap (review finding 2)' {
            $script:C14PopCalls = @()
            function Get-ADUser { param([string]$Server, [string]$LDAPFilter, [string[]]$Properties, [int]$ResultSetSize, $ErrorAction)
                $script:C14PopCalls += [pscustomobject]@{ Kind = 'user'; Server = $Server; LDAPFilter = $LDAPFilter; AskedProperties = $PSBoundParameters.ContainsKey('Properties'); ResultSetSize = $ResultSetSize }
                [pscustomobject]@{ SamAccountName = 'a.user' }
                [pscustomobject]@{ SamAccountName = 'b.user' }
                [pscustomobject]@{ SamAccountName = 'c.user' }
            }
            function Get-ADComputer { param([string]$Server, [string]$LDAPFilter, [string[]]$Properties, [int]$ResultSetSize, $ErrorAction)
                $script:C14PopCalls += [pscustomobject]@{ Kind = 'computer'; Server = $Server; LDAPFilter = $LDAPFilter; AskedProperties = $PSBoundParameters.ContainsKey('Properties'); ResultSetSize = $ResultSetSize }
                [pscustomobject]@{ SamAccountName = 'WS1$' }
            }
            $u = Get-AdfaStalePopulationRaw -DomainName 'north.contoso.com' -Kind 'User' -MaxObjects 10
            $u.Ok | Should -BeTrue
            $u.Count | Should -Be 3
            $u.Capped | Should -BeFalse
            $script:C14PopCalls[0].Server | Should -Be 'north.contoso.com'
            $script:C14PopCalls[0].ResultSetSize | Should -Be 11
            # The default property set: no -Properties at all, so never every property.
            $script:C14PopCalls[0].AskedProperties | Should -BeFalse
            $script:C14PopCalls[0].LDAPFilter | Should -Be '(&(objectCategory=person)(objectClass=user)(!(userAccountControl:1.2.840.113556.1.4.803:=2)))'
            $c = Get-AdfaStalePopulationRaw -DomainName 'north.contoso.com' -Kind 'Computer' -MaxObjects 10
            $c.Count | Should -Be 1
            $script:C14PopCalls[1].AskedProperties | Should -BeFalse
            $script:C14PopCalls[1].LDAPFilter | Should -Match ([regex]::Escape('(!(objectClass=msDS-ManagedServiceAccount))(!(userAccountControl:1.2.840.113556.1.4.803:=2)))'))
            $script:C14PopCalls[1].LDAPFilter | Should -Not -Match 'lastLogonTimestamp'
            (Get-AdfaStalePopulationRaw -DomainName 'north.contoso.com' -Kind 'User' -MaxObjects 3).Capped | Should -BeFalse
            (Get-AdfaStalePopulationRaw -DomainName 'north.contoso.com' -Kind 'User' -MaxObjects 2).Capped | Should -BeTrue
            function Get-ADUser { param([Parameter(ValueFromRemainingArguments)]$a) throw [System.UnauthorizedAccessException]'STUB: population read refused' }
            $denied = Get-AdfaStalePopulationRaw -DomainName 'north.contoso.com' -Kind 'User' -MaxObjects 10
            $denied.Ok | Should -BeFalse
            $denied.ErrorType | Should -Match 'UnauthorizedAccessException'
        }
        It 'never throws: a refused read comes back with its exception type' {
            function Get-ADComputer { param([Parameter(ValueFromRemainingArguments)]$a) throw [System.UnauthorizedAccessException]'STUB: computer query refused' }
            $raw = Get-AdfaStaleRaw -DomainName 'contoso.com' -Kind 'Computer' -CutoffUtc ([datetime]'2026-08-19') -MaxObjects 10
            $raw.Ok | Should -BeFalse
            $raw.ErrorType | Should -Match 'UnauthorizedAccessException'
        }
    }

    Context 'STALE-001/002: the verdict (pure)' {
        It 'counts stale enabled users, never-logged-on ones separately, and states the logon-sync caveat' {
            $records = @(
                (New-C14Account 'old.user' -LastLogonUtc $script:C14Now.AddDays(-200) -WhenCreatedUtc $script:C14Now.AddDays(-900))
                (New-C14Account 'never.user' -WhenCreatedUtc $script:C14Now.AddDays(-400))
            )
            $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw $records) -Interval (New-C14Interval) -StaleDays 90 -Now $script:C14Now -Config $script:Config.Stale
            $row.Item | Should -Be 'Inactive enabled users'
            $row.Scope | Should -Be 'contoso.com'
            $row.Status | Should -Be 'Warning'
            $row.Detail | Should -Match '^2 enabled user'
            $row.Detail | Should -Match '1 of them never logged on'
            $row.Detail | Should -Match 'msDS-LogonTimeSyncInterval'
            $row.Detail | Should -Match '14 day'
            $row.Detail | Should -Not -Match 'old\.user|never\.user'
            [string]$row.Accounts | Should -Match 'old\.user'
        }
        It 'counts at the cutoff, not one day after it, and a never-logged-on account only once it is older than the cutoff' {
            $records = @(
                (New-C14Account 'at.cutoff' -LastLogonUtc $script:C14Now.AddDays(-90) -WhenCreatedUtc $script:C14Now.AddDays(-900))
                (New-C14Account 'inside' -LastLogonUtc $script:C14Now.AddDays(-89) -WhenCreatedUtc $script:C14Now.AddDays(-900))
                (New-C14Account 'never.new' -WhenCreatedUtc $script:C14Now.AddDays(-10))
                (New-C14Account 'never.old' -WhenCreatedUtc $script:C14Now.AddDays(-91))
            )
            $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'Computer' -Raw (New-C14StaleRaw $records) -Interval (New-C14Interval) -StaleDays 90 -Now $script:C14Now -Config $script:Config.Stale
            $row.Item | Should -Be 'Inactive enabled computers'
            $row.Detail | Should -Match '^2 enabled computer'
            [string]$row.Accounts | Should -Match 'at\.cutoff'
            [string]$row.Accounts | Should -Match 'never\.old'
            [string]$row.Accounts | Should -Not -Match 'inside|never\.new'
        }
        It 'passes a complete read that found none, against a declared population it could see' {
            $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw @()) -Interval (New-C14Interval) -StaleDays 90 -Now $script:C14Now -Population (New-C14Population -Count 40) -Config $script:Config.Stale
            $row.Status | Should -Be 'Pass'
            $row.Detail | Should -Match '40 enabled user account'
            $row.Population | Should -Be '40'
        }
        It 'is Not Assessed, never Pass, when nothing was found and the declared population is not known: <Case> (review finding 2)' -ForEach @(
            @{ Case = 'not counted'; Pop = $null; Text = 'not counted' }
            @{ Case = 'count refused'; Pop = @{ Ok = $false; Count = 0; E = 'Insufficient access rights'; T = 'System.UnauthorizedAccessException' }; Text = 'access denied' }
            @{ Case = 'count unreachable'; Pop = @{ Ok = $false; Count = 0; E = 'Unable to contact the server.'; T = 'Microsoft.ActiveDirectory.Management.ADServerDownException' }; Text = 'unreachable' }
            @{ Case = 'empty population'; Pop = @{ Ok = $true; Count = 0; E = ''; T = '' }; Text = 'declared population is empty' }
        ) {
            $population = $null
            if ($null -ne $Pop) { $population = New-C14Population -Ok $Pop.Ok -Count $Pop.Count -ErrorText $Pop.E -ErrorType $Pop.T }
            # Declared population: both stale kinds and the password row, each with an empty read.
            foreach ($kind in @('User', 'Computer')) {
                $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind $kind -Raw (New-C14StaleRaw @()) -Interval (New-C14Interval) -StaleDays 90 -Now $script:C14Now -Population $population -Config $script:Config.Stale
                $row.Status | Should -Be 'Not Assessed' -Because $kind
                $row.Detail | Should -Match ("(?i){0}" -f $Text)
            }
            $pwdRow = Get-AdfaPasswordAgeVerdict -DomainName 'contoso.com' -Raw (New-C14StaleRaw @()) -Now $script:C14Now -Population $population -Config $script:Config.Stale
            $pwdRow.Status | Should -Be 'Not Assessed'
            $pwdRow.Detail | Should -Match ("(?i){0}" -f $Text)
        }
        It 'still grades stale accounts it found when the population count failed, and says so' {
            $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw @((New-C14Account 'old.user' -LastLogonUtc $script:C14Now.AddDays(-200)))) -Interval (New-C14Interval) -StaleDays 90 -Now $script:C14Now `
                -Population (New-C14Population -Ok $false -ErrorText 'Insufficient access rights' -ErrorType 'System.UnauthorizedAccessException') -Config $script:Config.Stale
            $row.Status | Should -Be 'Warning'
            $row.Detail | Should -Match 'Counting the enabled user accounts of this domain failed'
        }
        It 'is Not Assessed when a returned object cannot be classified: <Case> (review finding 5)' -ForEach @(
            @{ Case = 'a lastLogonTimestamp that is not a time'; Has = $true; Last = 'not-a-date'; Created = 'old' }
            @{ Case = 'no lastLogonTimestamp and no whenCreated'; Has = $false; Last = $null; Created = $null }
        ) {
            $created = $null
            if ($Created -eq 'old') { $created = $script:C14Now.AddDays(-900) }
            $odd = [pscustomobject]@{ Name = 'odd.user'; HasLastLogon = $Has; LastLogonUtc = $Last; WhenCreatedUtc = $created; PwdLastSetRaw = $null }
            # With one ordinary stale account beside it, so the row would otherwise be a Warning.
            $records = @((New-C14Account 'old.user' -LastLogonUtc $script:C14Now.AddDays(-200) -WhenCreatedUtc $script:C14Now.AddDays(-900)), $odd)
            $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw $records) -Interval (New-C14Interval) -StaleDays 90 -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
            $row.Status | Should -Be 'Not Assessed'
            $row.Detail | Should -Match '^1 returned object\(s\) carried no readable lastLogonTimestamp'
            # Alone, it must not leave a clean Pass either.
            $alone = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw @($odd)) -Interval (New-C14Interval) -StaleDays 90 -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
            $alone.Status | Should -Be 'Not Assessed'
        }
        It 'is Not Assessed, never Pass or zero, when the count is not complete: <Case>' -ForEach @(
            @{ Case = 'access denied'; Raw = @{ Ok = $false; E = 'Insufficient access rights'; T = 'System.UnauthorizedAccessException'; C = $false }; Interval = @{ Ok = $true; P = $false; V = $null }; Days = 90; Text = 'access denied' }
            @{ Case = 'unreachable'; Raw = @{ Ok = $false; E = 'Unable to contact the server.'; T = 'Microsoft.ActiveDirectory.Management.ADServerDownException'; C = $false }; Interval = @{ Ok = $true; P = $false; V = $null }; Days = 90; Text = 'unreachable' }
            @{ Case = 'timed out'; Raw = @{ Ok = $false; E = 'The operation has timed out'; T = 'System.TimeoutException'; C = $false }; Interval = @{ Ok = $true; P = $false; V = $null }; Days = 90; Text = 'timed out' }
            @{ Case = 'the cap reached'; Raw = @{ Ok = $true; E = ''; T = ''; C = $true }; Interval = @{ Ok = $true; P = $false; V = $null }; Days = 90; Text = 'cap' }
            @{ Case = 'updates disabled'; Raw = @{ Ok = $true; E = ''; T = ''; C = $false }; Interval = @{ Ok = $true; P = $true; V = 0 }; Days = 90; Text = 'disabled' }
            @{ Case = 'a threshold inside the logon-sync window'; Raw = @{ Ok = $true; E = ''; T = ''; C = $false }; Interval = @{ Ok = $true; P = $false; V = $null }; Days = 14; Text = 'StaleDays' }
        ) {
            $raw = New-C14StaleRaw -Records @() -Ok $Raw.Ok -ErrorText $Raw.E -ErrorType $Raw.T -Capped $Raw.C
            $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw $raw -Interval (New-C14Interval -Ok $Interval.Ok -Present $Interval.P -Value $Interval.V) -StaleDays $Days -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
            $row.Status | Should -Be 'Not Assessed'
            $row.Detail | Should -Match ("(?i){0}" -f $Text)
        }
        It 'grades a -StaleDays one day longer than the sync interval: the lag is at most the interval, not the interval plus 5 days (review finding 8)' {
            # Default interval 14: 15 to 19 were Not Assessed before the fix.
            foreach ($days in @(15, 19)) {
                $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw @((New-C14Account 'old.user' -LastLogonUtc $script:C14Now.AddDays(-200)))) -Interval (New-C14Interval) -StaleDays $days -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
                $row.Status | Should -Be 'Warning' -Because ("StaleDays {0}" -f $days)
                $row.Detail | Should -Match 'up to the interval more recent than the value read, never more'
                $row.Detail | Should -Not -Match '(?i)plus up to'
            }
            # A set interval of 30 days moves the window with it.
            (Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw @()) -Interval (New-C14Interval -Present $true -Value 30) -StaleDays 30 -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale).Status | Should -Be 'Not Assessed'
            (Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw @()) -Interval (New-C14Interval -Present $true -Value 30) -StaleDays 31 -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale).Status | Should -Be 'Pass'
        }
        It 'keeps the verdict when the interval could not be read, and says it assumed the default' {
            $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw @((New-C14Account 'old.user' -LastLogonUtc $script:C14Now.AddDays(-200)))) -Interval (New-C14Interval -Ok $false -ErrorText 'STUB: refused') -StaleDays 90 -Now $script:C14Now -Config $script:Config.Stale
            $row.Status | Should -Be 'Warning'
            $row.Detail | Should -Match 'could not be read'
        }
        It 'reads a set interval and widens the caveat with it' {
            $row = Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw @()) -Interval (New-C14Interval -Present $true -Value 30) -StaleDays 90 -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
            $row.Detail | Should -Match '30 day'
            $row.SyncIntervalDays | Should -Be 30
        }
        It 'honours StaleStatus from a file' {
            $cfg = Merge-AdfaSpecConfig -BaseConfig $script:Config.Stale -Override @{ StaleStatus = 'Info' } -OverrideSource 'C:\cfg\c14.json'
            (Get-AdfaStaleCountVerdict -DomainName 'contoso.com' -Kind 'User' -Raw (New-C14StaleRaw @((New-C14Account 'old.user' -LastLogonUtc $script:C14Now.AddDays(-200)))) -Interval (New-C14Interval) -StaleDays 90 -Now $script:C14Now -Config $cfg).Status | Should -Be 'Info'
        }
        It 'grades old passwords, and names pwdLastSet 0 as must-change-at-next-logon, not never set' {
            $records = @((New-C14PwdRecord 'old.pwd' ([int64]$script:C14Now.AddDays(-400).ToFileTimeUtc())), (New-C14PwdRecord 'must.change' ([int64]0)), (New-C14PwdRecord 'recent' ([int64]$script:C14Now.AddDays(-10).ToFileTimeUtc())))
            $row = Get-AdfaPasswordAgeVerdict -DomainName 'contoso.com' -Raw (New-C14StaleRaw $records) -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
            $row.Item | Should -Be 'Enabled users with an old password'
            $row.Status | Should -Be 'Warning'
            $row.Detail | Should -Match '^1 enabled user'
            $row.Detail | Should -Match 'must change'
            $row.Detail | Should -Not -Match '(?i)never set'
            $none = Get-AdfaPasswordAgeVerdict -DomainName 'contoso.com' -Raw (New-C14StaleRaw @((New-C14PwdRecord 'must.change' ([int64]0)))) -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
            $none.Status | Should -Be 'Pass'
            $none.MustChangeAtNextLogon | Should -Be '1'
            (Get-AdfaPasswordAgeVerdict -DomainName 'contoso.com' -Raw (New-C14StaleRaw -Ok $false -ErrorText 'Insufficient access rights') -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale).Status | Should -Be 'Not Assessed'
        }
        It 'counts a password set exactly PasswordAgeDays ago, as the filter and Evidence say (review finding 13b)' {
            $records = @((New-C14PwdRecord 'at.cutoff' ([int64]$script:C14Now.AddDays(-365).ToFileTimeUtc())), (New-C14PwdRecord 'inside' ([int64]$script:C14Now.AddDays(-364).ToFileTimeUtc())))
            $row = Get-AdfaPasswordAgeVerdict -DomainName 'contoso.com' -Raw (New-C14StaleRaw $records) -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
            $row.Status | Should -Be 'Warning'
            $row.Detail | Should -Match '^1 enabled user'
            [string]$row.Accounts | Should -Match 'at\.cutoff'
            [string]$row.Accounts | Should -Not -Match 'inside'
        }
        It 'is Not Assessed when a returned object carries no pwdLastSet (review finding 6)' {
            # Beside an account with a recent password, so the row would otherwise Pass.
            $records = @((New-C14PwdRecord 'recent' ([int64]$script:C14Now.AddDays(-10).ToFileTimeUtc())), (New-C14PwdRecord 'no.value' $null))
            $row = Get-AdfaPasswordAgeVerdict -DomainName 'contoso.com' -Raw (New-C14StaleRaw $records) -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
            $row.Status | Should -Be 'Not Assessed'
            $row.Detail | Should -Match '^1 returned object\(s\) carried no readable pwdLastSet'
        }
        It 'reads pwdLastSet 0 as must-change only where UF_DONT_EXPIRE_PASSWD is clear: <Case> (review finding 3)' -ForEach @(
            @{ Case = 'flag set, alone'; Uac = 66048; Old = $false; Status = 'Not Assessed'; Text = 'UF_DONT_EXPIRE_PASSWD set'; Must = '0' }
            @{ Case = 'flag set, beside an old password'; Uac = 66048; Old = $true; Status = 'Warning'; Text = 'age of their password is not known'; Must = '0' }
            @{ Case = 'flag clear'; Uac = 512; Old = $false; Status = 'Pass'; Text = '1 more must change'; Must = '1' }
            @{ Case = 'userAccountControl not readable'; Uac = $null; Old = $false; Status = 'Not Assessed'; Text = 'no readable userAccountControl'; Must = '' }
        ) {
            $records = @((New-C14PwdRecord 'svc.zero' ([int64]0) -UserAccountControl $Uac), (New-C14PwdRecord 'recent' ([int64]$script:C14Now.AddDays(-10).ToFileTimeUtc())))
            if ($Old) { $records += (New-C14PwdRecord 'old.pwd' ([int64]$script:C14Now.AddDays(-400).ToFileTimeUtc())) }
            $row = Get-AdfaPasswordAgeVerdict -DomainName 'contoso.com' -Raw (New-C14StaleRaw $records) -Now $script:C14Now -Population (New-C14Population) -Config $script:Config.Stale
            $row.Status | Should -Be $Status
            $row.Detail | Should -Match $Text
            [string]$row.MustChangeAtNextLogon | Should -Be $Must
            if ($Uac -eq 66048) {
                [string]$row.AgeNotKnown | Should -Be '1'
                [string]$row.AgeNotKnownAccounts | Should -Match 'svc\.zero'
                $row.Detail | Should -Not -Match 'svc\.zero'
            }
        }
    }

    Context 'SYSVOL-004: replication engine per DC and per domain' {
        It 'resolves the engine of one DC from its two subscription objects: <Dfsr>/<Frs>' -ForEach @(
            @{ Dfsr = 'Present'; Frs = 'Absent'; Engine = 'DFSR' }
            @{ Dfsr = 'Absent'; Frs = 'Present'; Engine = 'FRS' }
            @{ Dfsr = 'Present'; Frs = 'Present'; Engine = 'Transitional' }
            @{ Dfsr = 'Absent'; Frs = 'Absent'; Engine = 'Unknown' }
            @{ Dfsr = 'Unread'; Frs = 'Absent'; Engine = 'Unknown' }
            @{ Dfsr = 'Present'; Frs = 'Unread'; Engine = 'Unknown' }
        ) {
            (Resolve-AdfaSysvolEngineDc -Dfsr $Dfsr -Frs $Frs) | Should -Be $Engine
        }
        It 'passes a domain whose every writable DC uses DFSR, quoting msDFSR-Flags as corroboration' {
            $raw = New-C14EngineRaw -Dcs @((New-C14EngineDc $script:C14Dc1), (New-C14EngineDc $script:C14Dc2), (New-C14EngineDc 'rodc1.contoso.com' -Dfsr 'Absent' -Frs 'Present' -IsReadOnly $true))
            $rows = @(Get-AdfaSysvolEngineVerdict -DomainName 'contoso.com' -Raw $raw -Config $script:Config.SysvolEngine)
            $d = (Get-C14Row $rows 'SYSVOL replication engine: contoso.com')[0]
            $d.Status | Should -Be 'Pass'
            $d.Detail | Should -Match 'Eliminated'
            # Declared population: three DCs, one row each.
            (Get-C14Row $rows ("SYSVOL engine: {0}" -f $script:C14Dc1))[0].Engine | Should -Be 'DFSR'
            (Get-C14Row $rows ("SYSVOL engine: {0}" -f $script:C14Dc2))[0].Engine | Should -Be 'DFSR'
            (Get-C14Row $rows 'SYSVOL engine: rodc1.contoso.com')[0].Engine | Should -Be 'FRS'
        }
        It 'warns when a writable DC still uses FRS or is between the two, also with another DC unread: <Case>' -ForEach @(
            @{ Case = 'second DC FRS'; Second = @{ D = 'Absent'; F = 'Present' } }
            @{ Case = 'second DC transitional'; Second = @{ D = 'Present'; F = 'Present' } }
        ) {
            $raw = New-C14EngineRaw -Flags 16 -Dcs @((New-C14EngineDc $script:C14Dc1), (New-C14EngineDc $script:C14Dc2 -Dfsr $Second.D -Frs $Second.F), (New-C14EngineDc $script:C14Dc3 -Dfsr 'Unread' -DfsrError 'STUB: refused'))
            $d = (Get-C14Row @(Get-AdfaSysvolEngineVerdict -DomainName 'contoso.com' -Raw $raw -Config $script:Config.SysvolEngine) 'SYSVOL replication engine: contoso.com')[0]
            $d.Status | Should -Be 'Warning'
            $d.Detail | Should -Match 'FRS'
            $d.Detail | Should -Match 'Windows Server 2019'
        }
        It 'is Not Assessed, never Pass, when the engine is not known for every writable DC: <Case>' -ForEach @(
            @{ Case = 'one DC unread'; Raw = @{ Ok = $true; Dcs = 'unread' }; Text = 'could not be read|not known' }
            @{ Case = 'neither object'; Raw = @{ Ok = $true; Dcs = 'neither' }; Text = 'neither' }
            @{ Case = 'no writable DC'; Raw = @{ Ok = $true; Dcs = 'rodc' }; Text = 'no writable' }
            @{ Case = 'no DC at all'; Raw = @{ Ok = $true; Dcs = 'none' }; Text = 'no writable' }
            @{ Case = 'DC list refused'; Raw = @{ Ok = $false; Dcs = 'none' }; Text = 'access denied' }
        ) {
            $dcs = @()
            switch ($Raw.Dcs) {
                'unread' { $dcs = @((New-C14EngineDc $script:C14Dc1), (New-C14EngineDc $script:C14Dc2 -Frs 'Unread' -FrsError 'Insufficient access rights')) }
                'neither' { $dcs = @((New-C14EngineDc $script:C14Dc1), (New-C14EngineDc $script:C14Dc2 -Dfsr 'Absent' -Frs 'Absent')) }
                'rodc' { $dcs = @((New-C14EngineDc 'rodc1.contoso.com' -IsReadOnly $true)) }
            }
            $raw = New-C14EngineRaw -Dcs $dcs -Ok $Raw.Ok -ErrorText 'Insufficient access rights' -ErrorType 'System.UnauthorizedAccessException'
            $d = (Get-C14Row @(Get-AdfaSysvolEngineVerdict -DomainName 'contoso.com' -Raw $raw -Config $script:Config.SysvolEngine) 'SYSVOL replication engine: contoso.com')[0]
            $d.Status | Should -Be 'Not Assessed'
            $d.Detail | Should -Match ("(?i){0}" -f $Text)
        }
        It 'counts a DC whose read-only flag could not be read as writable, so its FRS is graded (review finding 10)' {
            # Declared population: two DCs, one with IsReadOnly unread ($null) on FRS, one RODC on DFSR.
            $raw = New-C14EngineRaw -Dcs @((New-C14EngineDc $script:C14Dc1 -Dfsr 'Absent' -Frs 'Present' -IsReadOnly $null), (New-C14EngineDc 'rodc1.contoso.com' -IsReadOnly $true))
            $d = (Get-C14Row @(Get-AdfaSysvolEngineVerdict -DomainName 'contoso.com' -Raw $raw -Config $script:Config.SysvolEngine) 'SYSVOL replication engine: contoso.com')[0]
            $d.Status | Should -Be 'Warning'
            $d.Detail | Should -Match '^1 of 1 writable'
            [string]$d.Writable | Should -Be '1'
        }
        It 'honours FrsStatus from a file' {
            $cfg = Merge-AdfaSpecConfig -BaseConfig $script:Config.SysvolEngine -Override @{ FrsStatus = 'Fail' } -OverrideSource 'C:\cfg\c14.json'
            $raw = New-C14EngineRaw -Dcs @((New-C14EngineDc $script:C14Dc1 -Dfsr 'Absent' -Frs 'Present'))
            (Get-C14Row @(Get-AdfaSysvolEngineVerdict -DomainName 'contoso.com' -Raw $raw -Config $cfg) 'SYSVOL replication engine: contoso.com')[0].Status | Should -Be 'Fail'
        }
        It 'reads the two objects of each DC from its own domain, telling not found from refused' {
            $script:C14ObjCalls = @()
            function Get-ADDomainController { param([string]$Server, [string]$Filter, $ErrorAction)
                [pscustomobject]@{ HostName = 'dc1.north.contoso.com'; IsReadOnly = $false; ComputerObjectDN = 'CN=DC1,OU=Domain Controllers,DC=north,DC=contoso,DC=com' }
                [pscustomobject]@{ HostName = 'dc2.north.contoso.com'; IsReadOnly = $false; ComputerObjectDN = 'CN=DC2,OU=Domain Controllers,DC=north,DC=contoso,DC=com' }
            }
            function Get-ADDomain { param([string]$Identity, $ErrorAction) [pscustomobject]@{ DistinguishedName = 'DC=north,DC=contoso,DC=com'; DNSRoot = $Identity } }
            function Get-ADObject { param([string]$Identity, [string]$Server, [string[]]$Properties, $ErrorAction)
                $script:C14ObjCalls += ("{0}@{1}" -f $Identity, $Server)
                if ($Identity -like 'CN=DFSR-GlobalSettings,*') { return [pscustomobject]@{ DistinguishedName = $Identity; 'msDFSR-Flags' = 48 } }
                if ($Identity -like 'CN=SYSVOL Subscription,*CN=DC2,*') { throw [System.UnauthorizedAccessException]'STUB: refused' }
                if ($Identity -like 'CN=SYSVOL Subscription,*') { return [pscustomobject]@{ DistinguishedName = $Identity } }
                throw (New-Object Contoso.Stub.ADIdentityNotFoundException 'Cannot find an object with identity')
            }
            $raw = Get-AdfaSysvolEngineRaw -DomainName 'north.contoso.com' -Config $script:Config.SysvolEngine
            $raw.Ok | Should -BeTrue
            $raw.GlobalFlags | Should -Be 48
            # Declared population: two DCs, two objects each, plus the global settings object.
            @($script:C14ObjCalls).Count | Should -Be 5
            @($script:C14ObjCalls | Where-Object { $_ -notmatch '@north\.contoso\.com$' }).Count | Should -Be 0
            $dc1 = @($raw.Dcs | Where-Object { $_.HostName -eq 'dc1.north.contoso.com' })[0]
            "$($dc1.Dfsr)/$($dc1.Frs)" | Should -Be 'Present/Absent'
            $dc2 = @($raw.Dcs | Where-Object { $_.HostName -eq 'dc2.north.contoso.com' })[0]
            $dc2.Dfsr | Should -Be 'Unread'
            $dc2.DfsrError | Should -Match 'refused'
        }
    }

    Context 'Advice: section-scoped, anchored on the tool-written Item prefixes, ahead of the unscoped entries' {
        It 'chooses its own advice whatever the Detail says: <Section> / <Item>' -ForEach @(
            @{ Section = 'Port Reachability'; Item = 'DC reachability: dc2.contoso.com'; Expect = 'metadata cleanup' }
            @{ Section = 'Site Health'; Item = 'Subnets without a site: contoso.com'; Expect = 'subnet' }
            @{ Section = 'Site Health'; Item = 'Clients without a site: dc1.contoso.com'; Expect = 'subnet object' }
            @{ Section = 'Time Hierarchy'; Item = 'Clock offset vs forest root PDC: dc2.contoso.com'; Expect = 'forest root PDC emulator' }
            @{ Section = 'Stale Objects'; Item = 'Inactive enabled users'; Expect = 'lastLogonTimestamp' }
            @{ Section = 'Stale Objects'; Item = 'Enabled users with an old password'; Expect = 'pwdLastSet' }
            @{ Section = 'SYSVOL / DFSR'; Item = 'SYSVOL replication engine: contoso.com'; Expect = 'dfsrmig' }
        ) {
            $advice = Get-AdfaRecommendation -Section $Section -Item $Item -Detail $script:C14Hostile
            $advice | Should -Match $Expect
            # Not the unscoped AD replication, DNS or time-sync advice.
            $advice | Should -Not -Match '(?i)most post-restore RPC 1722'
            $advice | Should -Not -Match '(?i)w32tm /resync'
        }
        It 'says what dfsrmig says: rollback is possible until Eliminated, which is irreversible (review finding 9)' {
            $advice = Get-AdfaRecommendation -Section 'SYSVOL / DFSR' -Item 'SYSVOL replication engine: contoso.com' -Detail 'x'
            $advice | Should -Not -Match '(?i)one-way'
            $advice | Should -Match 'rolled back \("dfsrmig /setglobalstate 0"\)'
            $advice | Should -Match 'reaching Eliminated is irreversible'
        }
        It 'leaves an Item outside the C14 families to the map it had' {
            (Get-AdfaRecommendation -Section 'Stale Objects' -Item 'PasswordNeverExpires users' -Detail '3 enabled users') | Should -Match 'Disable first'
        }
    }

    Context 'Wiring and read-only guards (AST)' {
        It 'declares every C14 function (declared population: 29 functions)' {
            $script:C14Functions.Count | Should -Be 29
            foreach ($n in $script:C14Functions) { @(Get-C14Function $n).Count | Should -Be 1 -Because $n }
        }
        It 'classifies reachability once, before the first per-DC section, and reports it in Port Reachability' {
            $calls = @(Get-C14Call $script:C14Main[0] 'Get-AdfaDcReachabilityRows')
            $calls.Count | Should -Be 1
            $repl = @(Get-C14Branch "Test-SectionSelected 'Replication' `$Sections")
            $repl.Count | Should -Be 1
            $calls[0].Extent.StartOffset | Should -BeLessThan $repl[0].Extent.StartOffset
            $port = @(Get-C14Branch "Test-SectionSelected 'PortMatrix' `$Sections")
            $port.Count | Should -Be 2
            # The later PortMatrix branch puts the rows in its section, next to the port matrix.
            $last = $port | Sort-Object { $_.Extent.StartOffset } | Select-Object -Last 1
            $last.Extent.Text | Should -Match '\$reachRows'
            @(Get-C14Call $last 'Get-AdfaPortMatrix').Count | Should -Be 1
        }
        It 'grades subnets and clients without a site in the Topology branch, outside the DC inventory gate' {
            $topo = @(Get-C14Branch "Test-SectionSelected 'Topology' `$Sections")
            $topo.Count | Should -Be 1
            @(Get-C14Call $topo[0] 'Get-AdfaSubnetSiteVerdict').Count | Should -Be 1
            @(Get-C14Call $topo[0] 'Get-AdfaClientSiteRows').Count | Should -Be 1
            $gate = @($topo[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.IfStatementAst] -and $n.Clauses[0].Item1.Extent.Text -match 'allDcInventory\.Count' }, $true))
            foreach ($g in $gate) { @(Get-C14Call $g 'Get-AdfaSubnetSiteVerdict').Count | Should -Be 0 }
        }
        It 'reads the SYSVOL engine once per scoped domain' {
            $sys = @(Get-C14Branch "Test-SectionSelected 'Sysvol' `$Sections")
            $loops = @($sys[0].FindAll({ param($n) $n -is [System.Management.Automation.Language.ForEachStatementAst] -and $n.Condition.Extent.Text -eq '$targetDomains' -and @(Get-C14Call $n 'Get-AdfaSysvolEngineRaw').Count -gt 0 }, $true))
            $loops.Count | Should -Be 1
            @(Get-C14Call $loops[0] 'Get-AdfaSysvolEngineVerdict').Count | Should -Be 1
        }
        It 'grades stale objects per scoped domain with the Stale table' {
            $st = @(Get-C14Branch "Test-SectionSelected 'StaleObjects' `$Sections")
            $call = @(Get-C14Call $st[0] 'Get-AdfaStaleObject')
            $call.Count | Should -Be 1
            (Get-C14Parameter $call[0] 'Config').Extent.Text | Should -Be '$staleConfig'
            (Get-C14Parameter $call[0] 'DomainName').Extent.Text | Should -Be '$d'
        }
        It 'passes the ClockSkew table, override included, to the time hierarchy' {
            $th = @(Get-C14Branch "Test-SectionSelected 'TimeHierarchy' `$Sections")
            $call = @(Get-C14Call $th[0] 'Get-AdfaTimeHierarchyHealth')
            (Get-C14Parameter $call[0] 'WarnSeconds').Extent.Text | Should -Be '$clockConfig.WarnSeconds'
            (Get-C14Parameter $call[0] 'SkewSamples').Extent.Text | Should -Be '$clockConfig.Samples'
            $th[0].Extent.Text | Should -Match "configOverrides\['ClockSkew'\]"
        }
        It 'no longer probes the time hierarchy with the uncached Test-TcpPort' {
            $fn = @(Get-C14Function 'Get-AdfaTimeHierarchyHealth')
            @(Get-C14Call $fn[0] 'Test-TcpPort').Count | Should -Be 0
            @(Get-C14Call $fn[0] 'Test-AdfaDcPort').Count | Should -Be 1
        }
        It 'probes through the C14 seams only: no new code calls Test-TcpPort' {
            foreach ($n in $script:C14Functions) { @(Get-C14Call (Get-C14Function $n)[0] 'Test-TcpPort').Count | Should -Be 0 -Because $n }
        }
        It 'the whole script passes the C14 read-only guard' {
            $cmds = @($script:C14Ast.FindAll({ param($n) $n -is [System.Management.Automation.Language.CommandAst] }, $true))
            # Non-vacuity: the reads the guard must see are there.
            @($cmds | Where-Object { [string]$_.GetCommandName() -eq 'Invoke-ExternalCommand' -and $_.Extent.Text -match "w32tm\.exe" }).Count | Should -BeGreaterThan 0
            @($cmds | Where-Object { [string]$_.GetCommandName() -eq 'Invoke-ExternalCommand' -and $_.Extent.Text -match "dfsrmig\.exe" }).Count | Should -BeGreaterThan 0
            @($cmds | Where-Object { [string]$_.GetCommandName() -eq 'Get-ADUser' }).Count | Should -BeGreaterThan 0
            $hits = Get-C14WriteHit -Ast $script:C14Ast -C14Names $script:C14Functions
            ($hits -join ' | ') | Should -Be ''
        }
        It 'the read-only guard fails on: <Name>' -ForEach @(
            @{ Name = 'Set-ADUser'; Code = "function Invoke-C14Injected { Set-ADUser -Identity 'old.user' -Enabled `$false }" }
            @{ Name = 'Disable-ADAccount'; Code = "function Invoke-C14Injected { Disable-ADAccount -Identity 'old.user' }" }
            @{ Name = 'Remove-ADComputer'; Code = "function Invoke-C14Injected { Remove-ADComputer -Identity 'ws-stale' }" }
            @{ Name = 'a registry value write'; Code = "function Invoke-C14Injected { Set-ItemProperty -Path 'HKLM:\SYSTEM' -Name 'x' -Value 1 }" }
            @{ Name = 'an StdRegProv write method'; Code = "function Invoke-C14Injected { Invoke-CimMethod -ClassName StdRegProv -MethodName SetDWORDValue -Arguments @{} }" }
            @{ Name = 'w32tm /resync'; Code = "function Invoke-C14Injected { Invoke-ExternalCommand -FilePath 'w32tm.exe' -Arguments '/resync /computer:dc1' }" }
            @{ Name = 'w32tm /config in a variable'; Code = "function Invoke-C14Injected { `$a = 'w32tm /config /update'; `$a }" }
            @{ Name = 'w32tm /register'; Code = "function Invoke-C14Injected { & 'w32tm.exe' '/register' }" }
            @{ Name = 'dfsrmig /setglobalstate'; Code = "function Invoke-C14Injected { Invoke-ExternalCommand -FilePath 'dfsrmig.exe' -Arguments '/setglobalstate 3' }" }
            @{ Name = 'Remove-Item in a C14 function'; Code = "function Get-AdfaStaleRaw { Remove-Item -Path 'x' }" }
            @{ Name = 'every property in a C14 function'; Code = "function Get-AdfaStaleRaw { Get-ADUser -LDAPFilter '(x)' -Properties '*' }" }
            @{ Name = 'every property assigned in a C14 function'; Code = "function Get-AdfaStaleRaw { `$q = @{}; `$q.Properties = @('*'); Get-ADUser @q }" }
            @{ Name = 'every property as a splat key in a C14 function'; Code = "function Get-AdfaStaleRaw { `$q = @{ LDAPFilter = '(x)'; Properties = '*' }; Get-ADUser @q }" }
        ) {
            $ast = [System.Management.Automation.Language.Parser]::ParseInput($Code, [ref]$null, [ref]$null)
            $hits = Get-C14WriteHit -Ast $ast -C14Names @('Get-AdfaStaleRaw')
            $hits.Count | Should -BeGreaterThan 0
        }
        It 'does not take a filter of every object for a list of every property' {
            $ast = [System.Management.Automation.Language.Parser]::ParseInput("function Get-AdfaStaleRaw { `$q = @{}; `$q.Filter = '*'; Get-ADDomainController @q -Properties @('HostName') }", [ref]$null, [ref]$null)
            $none = Get-C14WriteHit -Ast $ast -C14Names @('Get-AdfaStaleRaw')
            $none.Count | Should -Be 0
        }
        It 'leaves advice text in the recommendation map alone' {
            $inMap = [System.Management.Automation.Language.Parser]::ParseInput("`$script:RecommendationMap = @( @{ Match = 'x'; Text = 'Run ""w32tm /resync"" and ""dfsrmig /setglobalstate 3"".' } )", [ref]$null, [ref]$null)
            $none = Get-C14WriteHit -Ast $inMap
            $none.Count | Should -Be 0
        }
        It 'documents the C14 rows and the five override keys in the help and the README' {
            $help = $script:C14Ast.GetHelpContent()
            $cfgHelp = ([string]$help.Parameters['CONFIGOVERRIDEPATH'] -replace '\s+', ' ')
            $cfgHelp | Should -Match 'Sixteen sections can be named'
            foreach ($k in @('Reach', 'SiteCoverage', 'ClockSkew', 'Stale', 'SysvolEngine')) { $cfgHelp | Should -Match ("And {0}, " -f $k) }
            $sec = ([string]$help.Parameters['SECTIONS'] -replace '\s+', ' ')
            $sec | Should -Match 'DC reachability'
            $sec | Should -Match 'NO_CLIENT_SITE'
            $sec | Should -Match 'forest root PDC'
            $sec | Should -Match 'SYSVOL replication engine'
            $readme = (Get-Content -LiteralPath (Join-Path $script:RepoRoot 'README.md') -Raw)
            $readme | Should -Match 'DC reachability'
            $readme | Should -Match 'Subnets without a site'
            $readme | Should -Match 'SYSVOL replication engine'
        }
    }
}
